window.__D("text/torat-shmuel/c008",{"p":[[2000570467,"כו' (וש' הוי' הוא ל' התהוות ויו\"ד מורה על תמידות ההתהוות ולכן הוא עיקר שם הוי' כו') ויוסף הוא יו\"ד סוד פי' שהוא ממשיך ש' הוי' שהי' בסוד תחלה כו'. וביאור ענין מה שהשבטים ממשיכי' בחי' סוד ה', דהנה כתיב כל הנפש הבאה לבית יעקב ששים ושש ואח\"כ כתיב כל הנפש הבאה לבית יעקב שבעים, פי' ששים ושש הוא ב' ווי\"ן וא\"ו רבתא הוא בחי' ששים וא\"ו זעירא הוא בחי' שש, וזהו בחי' ס' ו' שבתיבת סוד, והנפש הבאה כו' שבעים שניתוספו ד' רומז לבחי' ד' שבתיבת סוד ולכן הם הממשיכים בחי' סוד הוי', וגם יין בגימ' סוד, ובקידוש הוא ע' תיבין, ולכן ע\"י שמברכין קידוש על היין ממשיכים ג\"כ בחי' סוד הוי' כו'.\n<b>ולהבין</b> בתוס' ביאור ענין בחי' סוד הוי' יובן ממה שנת' במ\"א ע\"פ אלה מסעי בנ\"י כו' שהלכו מ\"ב מסעות שצ\"ל מהו ענין מ\"ב מסעות אך הענין הוא דהנה ש' מ\"ב הוא נגד השרפים שיש להם וא\"ו כנפי' כמ\"ש שש כנפים לא', וששה פעמים ז' עולה מ\"ב, וזהו שרש ענין ש' מ\"ב. ולהבין זה יובן בהפרש בין שרפים לחיות ואופנים שיש להם רק ד' כנפים, והענין הוא דהנה הבריאה היא יש מאין ולכאו' צ\"ל הלא ממך הכל כתיב ואיך יתכן לומר שהבריאה יש מאין הלא הוא ית' הוא יש האמיתי כו', ויובן בהפרש שבין שרפים לאופנים, דהנה השרפים אומרים קדוש ואופנים וחיות אומרים ברוך, והענין הוא דהנה קדוש פי' שקדוש ומובדל מגדר עלמין וזהו בחי' סוד ה' שטמיר ונעלם מעין כל, והשרפים אומרים ג\"פ קדוש להיות שהוא מובדל ג\"פ כו', אבל האופנים והחיות אומרים ברוך ולהם ד' כנפים כו' שהם כנגד ד' אותיות דשם אד', ונמצא כי האופנים וחיות עם השרפים הם כנגד ה' ואלקים, והלכו מ\"ב מסעות במדבר שכדי שיצאו ממצרים ערות הארץ לבוא לארץ כנען הלכו מ\"ב מסעות דוקא כדי לבוא לבחי' גילוי סוד ה' כו'."],[2000570468,"<b>ובזה</b> יובן מה שהבריאה יש מאין הלא ממך הכל כנ\"ל, דהנה כתיב שאו מרום עיניכם וראו מי ברא אלה, אלה הוא בחי' ו\"ק לך ה' הגדולה כו' ובחי' מי ברא אלה בבחי' בריאה יש מאין, דהנה יש בחי' השתלשלות שהוא עו\"ע אבל הבריאה היא יש מאין, אך איך נא' מאין הלא ממך הכל כתיב, הענין הוא דפי' מאין אינו מהארה בעלמא כ\"א מאין מבחי' שאינו מושג כלל וזהו מי ברא כו' מי שאינו מושג כלל. ובכ\"ז יובן ענין הנסכים שכשם שהשרפי' ממשיכים בחי' סוד ה', כמו\"כ ע\"י ניסוך היין ממשיכים בחי' סוד ה' להיות כי נכנס יין יצא סוד בחי' סוד ה' כנ\"ל.\n<b>והנה</b> בנסכים כתיב ונסכו רביעית ההין יין, ואיתא בזהר שזהו בחי' ומדריגת יוסף שהוא רביעי לנהורין עילאין שהם ג' אבות כו'. ובזה יובן ג\"כ מה ששמע\"צ הוא רגל בפ\"ע ואעפ\"כ בתורה לא נא' כ\"א שלש רגלים, שנחשב שמע\"צ בכלל חגה\"ס, דהנה כתיב אלה תולדות יעקב יוסף, וצ\"ל מפני מה נא' יוסף דוקא והל\"ל אלה תולדות יעקב ראובן, אך הענין דהנה יוסף הוא בחי' יסוד צ\"ע והוא המוביל כל ההמשכות שממשיך יעקב, דהנה יעקב הוא בחי' בריח התיכון המבריח מן הקצה אל הקצה, אך הנה כל המשכות נמשך רק באצי' כנודע אבל כדי שיומשך בבי\"ע זהו ע\"י יוסף צ\"ע בחי' יסוד שע\"י נמשך ההשפעה בבי\"ע, ולכן נא' אלה תולדות יעקב יוסף. וביאור הענין דהנה יעקב ויוסף הוא ב' ואוי\"ן וא\"ו רברבא ווא\"ו זעירא והם בחי' וא\"ו עם המילוי שהוא ג\"כ וא\"ו, והנה א\"א לומר וא\"ו כ\"א שיאמר מלוי הוא\"ו ג\"כ, ונמצא כי ב' הואוי\"ן לא יוכשרו זב\"ז כ\"א שניהם כא' דוקא, וזהו בחי' יעקב ויוסף שיעקב הוא בחי' וא\"ו רברבא שכל ההמשכות נמשך ע\"י בחי' בריח התיכון, אמנם הנה כ\"ז הוא באצי' ומה יועיל זה למטה בבי\"ע, וכדי שיומשך למטה זהו ע\"י יוסף כנ\"ל והוא בחי' מילוי הוא\"ו, וזהו שהם בחי' וא\"ו עם מלוי וא\"ו. וז\"ע ונסכו יין רביעית ההין דא יוסף רביעאה לנהורין עילאין שהוא בחי' וא\"ו המילוי כנ\"ל.\n<b>וז\"ע</b> ביום השמיני עצרת ואיתא בזהר ויחי דר\"ח ע\"פ ולא עמד איש אתו בהתוודע יוסף אל אחיו ששמע\"צ הוא בחי' ומדרגת יוסף רגלא רביעאה ולכן לא נחשב רגל בפ\"ע בתורה כמ\"ש שלש רגלים להיות כי הוא מילוי וא\"ו והוא בחי' א' עם יעקב אך אעפ\"כ בתושבע\"פ נחשב רגל בפ\"ע להיות כי כדי"],[2000570469,"שיומשך למטה זהו ע\"י יוסף, ולכן בתושב\"כ בחי' ס\"ת היא בחי' בינה לא נחשב רגל בפ\"ע ובתושבע\"פ נחשב רגל בפ\"ע כו', ופי' ביום השמע\"צ פי' עצרת ל' קליטה שכל מה שנמשך בחגה\"ס בחי' ענני כבוד בשמע\"צ נמשך בבחי' פנימיות כו', ופי' תהי' לכם כי בז' ימי הסוכות הקריבו ע' פרים כנגד ע' שרים, אבל בשמע\"צ פר א' איל א' כו' ולכן תהי' לכם דוקא שאינו נמשך כ\"א לישראל עם קרובו דוקא כו'."],[2000570470,"<h3>ויגש אליו יהודה</h3>\n<b>בס\"ד</b>\n<b>ויגש</b> אליו יהודה ויאמר בי אדוני ידבר נא עבדיך דבר כו' ואל יחר אפך כו', ואיתא בזהר שענין הגשת יהודה ליוסף זהו כענין סמיכת גאולה לתפלה, ובעה\"ט פי' שס\"ת ויגש אליו יהודה הוא שוה, ולכן ארז\"ל במד\"ר ע\"פ כי הנה המלכים נועדו, על יהודה ויוסף, כוונתו שהם שוים, וצ\"ל הלא ידוע פי' וענין כי המלכים נועדו שקאי על יוסף ויהודה שז\"ע יחוד זו\"נ, וא\"כ איך הם שוים. ויובן בהקדם מה שעכשיו נק' נש\"י ע\"ש יוסף כמ\"ש רועה ישראל האזינה נוהג כצאן יוסף (תילי' סי' פ') ולע\"ל יהי' העיקר יהודה וכמ\"ש בהפטורה דפ' זו ודוד עבדי נשיא עליהם לעולם שיהי' משבט יהודה דוקא, וצ\"ל שורש ענין ההפרש בין ההמשכה דעכשיו להגילוי שיהי' לע\"ל שאז יקראו נש\"י ע\"ש יהודה דוקא.\n<b>הנה</b> ארז\"ל בברכות ד\"ז סע\"ב כל הקובע מקום לתפילתו (נ\"א לתורתו) אויביו נופלים תחתיו שנא' ושמתי מקום לעמי ישראל כו' ולא יוסיפו בני עולה לענותו (בש\"ב ז') ורב אלפס ותר\"י גורסי' לתורתו, והענין הוא דהנה מקום קאי על בהמק\"ד כמובן מפסוק ושמתי מקום הנ\"ל שזהו הי' תשובת נתן הנביא לדוד בענין בנין בהמק\"ד, ועכשיו תפלה כנגד תמידין תקנו ולכן כמו שבבהמק\"ד הי' צ\"ל קביעת מקום דוקא, כמו\"כ בענין התפלה שכנגד תמידין צ\"ל קביעת מקום ולר\"א ותר\"י שגורסי' לתורתו ג\"כ אמת נכון הדבר כי משחרב בהמק\"ד אין להקב\"ה בעולמו אלא ד\"א של הלכה, ולכן צ\"ל קביעת מקום לתורתו כמו בהמק\"ד שהי' דירת קבע.\n<b>ולהבין</b> כ\"ז צלה\"ק תחלה מ\"ש בדבר ה' שמים נעשו וברוח פיו כל צבאם, שנברא הכל בע\"מ וכמארז\"ל בע\"מ נברה\"ע, והלא כתיב כל אשר חפץ ה' עשה בשוב\"א משמע שנברא בחפץ ורצון ה' ולא במאמר לבד. אך"],[2000570471,"הענין הוא דהנה בכ\"ד שנברא בשי\"ב יש בכל דו\"ד חומר וצורה, פי' שהחומר הוא בחי' גוף דבר ההוא בכלל כמו השמים או הארץ או שארי הנבראים שבדצח\"ם הנה הדבר ההוא בכלל הוא בחי' החומר, והצורה הוא ענין ציור הדבר איך ומה שהוא כמו שהשמים והארץ יהי' כדורי', ומן הארץ לרקיע מהלך ת\"ק שנה ועובי הרקיע ת\"ק שנה, ובין כל רקיע ת\"ק שנה, נמצא צ\"ל שטח כדור השמים כך שיוכל להקיף הארץ ושיהי' המרחק ביניהם כך, או השמש והגלגלים יהי' גלגלים מאירי', וכמו\"כ בכל פרטי דצח\"ם שיהי' עגולי' או בעל קרנות או משולש או ציור אחר במראה ושטח זהו הנק' צורה. ועפ\"ז יובן שורש ענין צער הנשמות במה שמתגלגלי' בבע\"ח או צומח וכדומה, שלהיות האדם יש בציור גופו שם הוי' כנודע שהראש הוא תמונת היו\"ד והגוף הוא תמונת וא\"ו וה' אצבעות שביד וה' אצבעות שברגל הם ב' ההי\"ן, והיינו לפי שנפש האדם היא חלק אלק' ממעל כמ\"ש כי חלק ה' עמו שהוא בחי' חלק ה' ובעבודה היו\"ד הוא בחי' חכ' וה' בחי' התבוננות, ו\"ה הוא בחי' מדות ודבור, וקוש\"י הוא בחי' ביטול שלמעלה מן החכ' כמ\"ש בזה בכ\"ד בלק\"ת ומהם בד\"ה ולא אבה, ובד\"ה ראה, וע' בד\"ה ועשו לי מקדש בענין ההשתחואה שבבהמק\"ד שז\"ע הבטול שלמעלה מן השכל, וע' בד\"ה את ה' האמרת היום בענין חלקי ה' אמרה נפשי, ולכן כדי שיהי' הגוף חומר מוכן"],[2000570472,"לקבל צורת הנפש צ\"ל בציור החומר של הגוף ג\"כ תמונת ד' אותיות הוי' כו', וא\"כ ממילא מובן שכאשר נפש האדם מתגלגלת בבהמה עד\"מ שאין ציור חומר גוף הבהמה שוה לציור גוף נפש האדם לכן יש לה צער גדול מזה, וע' מזה בד\"ה קדש ישראל (דתרי\"ד). והנה החומר נברא בדבר ה' ובע\"מ שבמאמר יהי אור נתהוה בחי' האור מאין ליש וכן במאמר יהי רקיע נתהוה הרקיע מאין ליש, ועד\"ז בכל הנבראים בשי\"ב, אבל אופן צורת הרקיע עד\"מ או ציור שארי פרטי הנבראי' דדצח\"ם בדמותם ובצלמם הוא נעשה בחפץ ה' שלא בא לכלל דבור בגילוי או מאמר, וע' בסדור בד\"ה כבוד מל' יאמרו וגבורתך ידברו, ההפרש בין אמירה לדבור, ובד\"ה תקעו בחדש שופר (ך\"ט). והענין הוא דבאמת בחי' אותיות הדבור הם ג\"כ חומר לגבי האור החכ' המלובש בהאותיות, והמשל בזה הוא ע\"ד מ\"ש כי ביום אכלך ממנו כו' שלא נפרט בדבור איזהו יום אם יום האדם או יומו של הקב\"ה שהוא אלף שנה, וע\"פ החכ' הוא בחי' הצורה שבאותיות גזרה חכמתו שזהו בחי' יומו של הקב\"ה ולכן חי תתק\"ל שנים (שהניח ע' שנה לדוד כמ\"ש במ\"א) וע' בד\"ה ויחי יעקב*.\n<b>והנה</b> מה שנברא החומר במאמר ודבור ולא נברא הכל בחפץ ה' ורצונו בלבד הוא מפני שאז לא הי' יכול להיות התהוות היש הגשמי רק שהי' העולם רוחני והי' בבחי' ביטול במציאות ממש. וכמו שאנו רואים בכל בחי' השתלשלות עו\"ע שהעלול בטל לעילה כמו למשל מדות משכל שהמדות נולדים מן השכל, וכמו שאנו רואים שאם מתבונן בשכלו שהדבר ההוא טוב לפניו אזי נולד לו אהבה לזה, ובזה יובן מ\"ש ואהבת את הוי' אלקיך דלכאו' אינו מובן איך יתכן הציווי על אהבה שהיא מדה שבלב, אך הענין הוא דהציווי"],[2000570473,"הוא על התבוננות וכמ\"ש תחלה שמע ישראל כו' מל' הסכת ושמע שהו\"ע ההתבוננות שיתבונן באלקות ועי\"ז ממילא יבוא לבחי' האהבה לפי שהמדות מקבלים מן השכל דרך השתלשלות עו\"ע בבחי' קירוב וכן בגשמי' כמו במו\"מ המדות נולדים מן השכל ולפי שהמדות נולדים מן השכל לכן הם בטלים להשכל כו' כי העלול בטל להעילה וכמו\"כ אם הי' נברא הנ\"ל בחפץ ורצון הוי' הי' העולם בטל במציאות ממש כמו עלמא דאתכסי' שהם בתכלית הביטול וא\"כ לא הי' עבודה כלל. רק עיקר גילוי מציאות התהוות היש ע\"י דבר הוי' וכמו שאנו רואי' שאותיות הדבור נראים כאלו הם נפרדים, הגם כי למעלה אינו שייך לומר נפרד כו' כי אין לך דבר שחוץ ממנו אך מ\"מ דיברה תורה כלשון בנ\"א כו' וע\"כ לפי שנתהוו מבחי' דבר הוי' לכן הם נראים ליש ודבר.\nב) <b>והנה</b> בחי' דבר ה' הוא בחי' מל' כי מל' מל' כ\"ע אין מלך בלא עם שבחי' מל' הוא בחי' ההתנשאו' והסתלקות שלא יאיר ויתגלה אלא בבחי' שם בלבד, ולכן בשם הוי' כתיב יהללו את שם הוי' כי הוא צוה ונבראו כמו עד\"מ מלך בו\"ד שמלכותו הוא שמו בלבד אשר נקרא על מדינתו אבל לא בבחי' התלבשות כח הפועל בנפעל, וזהו ונבראו שהוא ממילא כו', וזהו ג\"כ מ\"ש אתה הוא עד שלא נבה\"ע אתה הוא משנבה\"ע ולא כתיב ברא לפי שברא משמע שהיא כח הפועל בנפעל ממש וכמ\"ש בראשית ברא אלקים שהוא בחי' התלבשות כח הפועל בנפעל כו' אבל נברא משמע שאינו בבחי' התלבשות כלל ועל בחי' שם הוי' הוא שאמר בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, אבל התהוות עולמות הנבראי' דבי\"ע הוא רק מבחי' זיו והארה בעלמא בבחי' התנשאות וריחוק בחי' דבר ה' בחי' מל' כדי שיתהווה יש מאין כו' ע\"י בחי' הפרסא שבין אצי' לבי\"ע, ואם הי' התהוות העולמות בבחי' השתלשלות הי' העולם בטל במציאות ממש ולא הי' גילוי בחי' יש, ולזה התהוות החומר היא מבחי' דבר הוי'.\n<b>אך</b> אם הי' התהוות הצורה ג\"כ מבחי' דבר ה' היו נפרדים ממש ולא הי' בהם בחי' ביטול כלל, ותכלית בריאת יש מאין הוא כדי להיות ביטול היש לאין ונגלה כבוד ה' למטה כמו למעלה וכמו שיהי' לע\"ל כי עין בעין יראו כו', וזהו ע\"י שנעשה הצורה ע\"י חכ' כמ\"ש כולם בחכמה עשית, אשר יצר את האדם בחכ', כי חכ' הוא כח מ\"ה בחי' ביטול והיינו בחי' מו\"ס שבו מלובש גבורה דע\"י בוצינא דקרדוניתא המודד כל המדידות איך שיהי' בציורם כתמונתם כו', ועי\"ז יכול להיות בנבראים בחי' ביטול היש לאין ובחכ' אתברירו."],[2000570474,"<b>וזהו</b> מ\"ש רז\"ל במד\"ר בראשית פי\"ב הוא עשך ויכוננך הוא וב\"ד נמנו על כל אבר ואבר, וי\"ל הוא דא עתיקא, וב\"ד חב\"ד, ב\"ד הגדול בבינה כמ\"ש ברע\"מ ס\"פ משפטים, וכמ\"ש באו\"ת פ' בראשית סד\"ה כל האומר ויכולו, שבינה ציירא ציורין. והנה המכוון מזה הביטול הוא כדי שיזכו לעוה\"ב שכל ישראל יש להם חלק לעוה\"ב וכדי שיזכו לעוה\"ב זה תלוי בעבודתינו כל ימינו היום לעשותם, לעשות ביטול היש לאין ועי\"ז יזכו לעוה\"ב שהוא גילוי בחי' חכ' כח מ\"ה כי חו\"ב תרדל\"מ, כי שכר מצוה מצוה.\nג) <b>והנה</b> עוה\"ב הוא בחי' עולם התחי' שיעמדו נשמות בגופים דוקא ויהי' הגוף ניזון ג\"כ מאלקות וכמשארז\"ל עוה\"ב אין בו לא אכילה ולא שתי' שא\"א לומר שקאי על ג\"ע דא\"כ מאי רבותא שהרי ג\"ע הוא נשמות בלא גופים ואין שייך בהם אכילה כלל, א\"ו שקאי על עולם התחי' שיהיו נשמות בגופים ואעפ\"כ לא יהי' בהם אכילה ושתי' אלא יהיו ניזונים מזיו השכינה וגם הגוף יקבל חיות כמו הנשמה, וזהו ענין מה שלע\"ל יהי' טעם עצו ופריו שוה שעתה הארץ שינתה מהציווי עץ פרי עושה פרי אבל לע\"ל יהי' טעם עצו ופריו שוה ובאדם הוא שהגוף יקבל חיות רוחני מזיו השכינה כמו הנשמה ממש. אך לכאו' אינו מובן מהו יתרון המעלה במה שלע\"ל בעולם התחי' יתלבשו הנשמות בגופים דוקא, והנשמות הגבוהות שהם יותר משלשה אלפים שנה בג\"ע כמו נשמות האבות ומשה שהם משיגים השגות עד אין קץ וכמ\"ש וקדושים בכ\"י יהללוך סלה בלי הפסק כלל, וכתיב ילכו מחיל אל חיל וארז\"ל ע\"ז צדיקים אין להם מנוחה שעולי' תמיד ממדריגה למדריגה, ומהו היתרון במה שירדו להתלבש בגוף דוקא, שלכאורה היא ירידה גדולה ועצומה. אך הענין הוא דירידה צורך עלי' היא.\n<b>ולהבין</b> מהו העלי' יותר גדולה מג\"ע, והנה להבין זה י\"ל ההפרש שבין משכן לבהמ\"ק שהמשכן הי' מארזים כמ\"ש עצי שטים עומדים והמכסה הי' מיריעות עזים ועורות אלים מאדמים ועורות תחשים כו' ובהמ\"ק הי' מאבנים ועפר דוקא, שאסור לעשות בו עץ בולט כו' ואכסדראות של עץ כמ\"ש הרמב\"ם פ\"א מה' בית הבחירה כו', וע' בס' החינוך מצוה תצ\"ב, רק שהיו כלונסאות של ארזים בתקרת האולם, וצ\"ל מפני מה במשכן היו הארזים עיקר בבנין והעפר הי' רק בקרקע המשכן למטה, ובמקדש נהפוך הוא שהיו האבנים והעפר עיקר שאפי' הגג הי' מהן ולא היו עצים רק כלונסאות של ארז הנ\"ל שהיו טפלים לעיקר הבנין, ובהבין דבר זה יובן ג\"כ ההפרש שבין יוסף ליהודה שהמשכן הי' בחלקו של יוסף שעמד שס\"ט שנה בשילה, וזהו שקדשים קלים נאכלים בשילה בכל הרואה, ובירושלים לפנים מן החומה, והיינו לפי שבשילה"],[2000570475,"הוא בחלקו של יוסף וע\"כ נאכלים בכל הרואה וכמ\"ש במד\"ר בשכר שלא זן עינו מן הערוה ולא רצה להביט ברע לכך זכה שיהי' נאכלים בכל הרואה, ובהמ\"ק הי' בחלקו של יהודה ובנימין, והענין הוא דהנה המשכן נק' דירת עראי וכמ\"ש (ש\"ב ז') ואהי' מתהלך באהל ובמשכן, אבל בהמ\"ק נק' דירת קבע, וכמ\"ש ושמתי מקום כו', וא\"כ אינו מובן למה המקדש הי' מאבנים ועפר דוקא שהוא בחי' דומם שהוא למטה מצומח וחי והמשכן הי' מצומח וחי כו', אך הענין הוא דלא ראי זה כראי זה שאעפ\"י שהדומם למטה מהצומח וחי עכ\"ז יש בו מעלה יתירה מצד שרשו שלמעלה מבחי' צומח וחי כו'.\n<b>דהנה</b> ידוע מחלוקת התנאי' בגמ' חגיגה ח\"א שמים קדמה לארץ כמ\"ש בראשית ברא את השמים ואת הארץ, וח\"א ארץ קדמה לשמים כמ\"ש ביום עשות ה' אלקי' ארץ ושמים ואלו ואלו דא\"ח שבמחשבה ארץ קדמה לשמים וכשברא ברא השמים תחלה, והענין כי סוף מעשה עבמח\"ת, פי' כי הארץ לפי שהוא סוף מעשה ע\"כ שרשה במח' היא בבחי' תחילת המחשבה, אבל שמים שהם תחלת המעשה הם אחרונים במח' כי זהו הכלל שהסוף מעשה עולה בתחילת המח', והיינו לפי שעיקר המכוון נגמר בסוף וכמו שאנו רואים למטה בגשמי' בכל השפעה שעיקר המכוון נשלם בסוף כמו למשל תבואה או אילן שמתחילה נגדל האילן והקש ואח\"כ נגמר הפרי שהוא עיקר המכוון כו', וכן בהשפעת שכל שמשפיע הרב לתלמיד שמתחלה צריך להקדים לו הקדמות ומשלים ואח\"כ מבין את השכל שהוא העיקר, וכן פרש\"י בחומש ע\"פ בראשית ברא אר\"י לא הי' צריך להתחיל את התורה אלא מהחודש הזה לכם, אלא כח מעשיו הגיד לעמו לתת להם נחלת גוים ומכח זה הקדים ברה\"ע כו' (הגם שספר בראשית הוא למעלה משאר ספרים שנק' ספר הישר מ\"מ עיקר התורה היא מהחודש הזה לכם כו') וכך במח' ארץ קדמה, אך בהשתלשלות ברה\"ע נברא שמים תחלה לפי שארץ מקבל מבחי' שמים וכמ\"ש אני אענה את השמים והם יענו את הארץ, לכך נברא שמים תחלה.\n<b>וזהו</b> ענין הפלוגתא בגמ' תלמוד גדול או מעשה גדול נמנו וגמרו תלמוד גדול שמביא לידי מעשה, והיינו לפי שבשרש מעשה גדול כי לע\"ל יתעלה בחי' מעשה א\"ח עט\"ב, אך לע\"ע תלמוד גדול מפני שמביא לידי מעשה שע\"י תורה דוקא נעשה המצוה כי בחכ' אתברירו, ועי\"ז נעשה המצוה גשמי' שיעורר עי\"ז אתדל\"ע, וזהו שבפ' ראשונה שבק\"ש נאמר מתחלה והיו הדברים האלה ושננתם כו' ואח\"כ וקשרתם תלמוד גדול שמביא לידי מעשה אבל לע\"ל יהי' מעשה גדול וכמ\"ש בפ' שני' וקשרתם ולמדתם כו' כי היא מדברת איך שיהי' לע\"ל והיינו לפי כי שרש המצוה היא בבחי' כתר בחי' גלגלתא.\nד) <b>ושרש</b> הענין הוא דהנה יש בחי' השתלשלות ולמעלה מהשתלשלות, והענין הוא דהנה כדי שיהי' התהוות העולמות שהם בבחי' גבול"],[2000570476,"מאא\"ס שהוא למעלה מבחי' גבול ואינו בגדר עולמות כלל הוצרך להיות צמצום באא\"ס, וזהו ענין יו\"ד של שם הוי' כי יו\"ד הוא בחי' חכ' וכדי שיהי' בחי' חכ' דהנה כתיב כולם בחכ' עשית שהחכ' נחשבת כעשי' גשמי' לפניו וא\"כ כדי שיהי' בחי' חכ' זהו ע\"י צמצום ונקודה כו' ומחכ' ולמטה נמשך דרך השתלשלות, אבל התהוות החכ' מלמעלה מן החכ' אינו נמשך בדרך השתלשלות וכמ\"ש והחכ' מאין תמצא כו' שהוא ע\"י צמצום, והוא כמו א' כשמוצא מציאה שא\"י מאין היא באה לו, וכך עד\"ז הו\"ע התהוות החכ' מאין דכתר, אך עיקר המכוון הי' כדי שיהי' התגלות אא\"ס כמו שהוא למעלה מן הצמצום היינו מה שלמעלה מסדר השתלשלות, ומ\"מ לא יתבטלו העולמות ממציאותם, שמאחר שכבר נעשה סדר השתלשלו' ע\"י בחי' הצמצום כנ\"ל יכולים אח\"כ להמשיך גילוי אא\"ס ע\"י תומ\"צ שלמעלה מסדר השתלשלו' רק שלכתחלה בברה\"ע לא הי' אפשר להיות גילוי אא\"ס שלמעלה מסדר השתל' שא\"כ לא הי' אפשר להוות עולמות רק אח\"כ שכבר נתהווה עולמות ע\"י צמצום יכולים אח\"כ להמשיך גילוי אוא\"ס שלמעלה מן הצמצום כו', וכמ\"ש בכהאריז\"ל שהתהוות העולמות הי' מתחלה ע\"י צמצום ואח\"כ המשכת הקו, ולכאו' למה לא נשאר מתחלה הקו אלא לפי שאם הי' נשאר הקו מתחלה לא הי' יכול להתהוות עולמות בבחי' גבול כמו שהן עתה אלא אח\"כ דוקא שנתהוו הכלי' והעולמות (ע' בהגהות לד\"ה תקעו שבלק\"ת מענין עולמות הא\"ס) אינם מתבטלי' מחמת המשכת הקו, וכמו\"כ הוא בענין ההמשכה מלמעלה מסדר ההשתל' יכולים לקבל ג\"כ ולא יהיו בטלים כו'.\n<b>וזהו</b> דעת המ\"ד ארץ נבראת תחלה והיינו לפי שעיקר המכוון הי' בשביל הארץ לפי שאדם עלי' בראתי שהוא עיקר המכוון לפי שהוא ממשיך גילוי אא\"ס ע\"י תומ\"צ למטה כו', אך כדי שיהי' התהוות בחי' ארץ הוצרך להיות נברא תחלה שמים לפי שבסדר השתלשלות שמים קדמו כו'. וזהו ג\"כ החילוק שבין משכן למקדש שהמשכן הי' מצומח דוקא, והיינו לפי שבמשכן הי' הגילוי שבבחי' סדר ההשתל' כי הי' רק דירת עראי של הקב\"ה וכמ\"ש ואהי' מתהלך באהל ובמשכן כו', וזהו שבמשכן הי' למעלה יריעות ע\"ש נוטה שמים כיריעה בחי' שמים קדמו, ולכך כל מה שהי' בבריאת העולם הי' במשכן כמ\"ש במדרש, ולכך הי' מצומח וחי שבבחי' סדר השתל' צומח וחי למעלה מדומם כו', אבל בבהמ\"ק שהי' מעין דלע\"ל שיהי' הגילוי שלמעלה מסדר השתלשלות כו', הי' דירת קבע של הקב\"ה דהיינו כי קבע הוא בחי' שלמעלה מסדר השתלשלות ע\"כ הי' מאבנים ועפר דוקא לפי שדומם שהוא סוף מדרגה ע\"כ נעוץ תחב\"ס כו' לפי שבמח' ארץ קדמה. וזהו ג\"כ ענין הפלוגתא שבגמ' סוכה אי דירת קבע בעינן או דירת עראי, והיינו שהפלוגתא הוא בהמשכה זו של סוכה שממשיכי' ע\"י סכך דסוכה מקיפי' עליונים דבינה עלמא עילאה מעין"],[2000570477,"עוה\"ב אם היא דירת עראי היינו עכ\"פ מבחי' המקיפי' דסדר השתל', או דירת קבע שלמעלה מסדר השתל' כמו לע\"ל ממש.\nה) <b>ובזה</b> יובן ג\"כ מה שנשמות עליונות שבג\"ע ירדו למטה להתלבש בגופים דוקא והיינו לפי שג\"ע הגם שיושבין ונהנין מזיו השכינה, אך מ\"מ הגילוי שבג\"ע הוא רק מבחי' גילוי אא\"ס שבסדר השתלשלות כו' וכמ\"ש ונהר יוצא מעדן להשקות את הגן, עדן הוא בחי' חכ', והנה חכ' הוא בחי' סדר ההשתל' כי מחכ' נמשך ראשית ההשתל' וכמ\"ש והחכ' מאין תמצא שהוא בחי' ממכ\"ע, וכן ארז\"ל ביו\"ד נברא העוה\"ב שהוא בחי' חכ', אבל תח\"ה יהי' הגילוי מבחי' שלמעלה מן סדר השתל' מבחי' סוכ\"ע וע' בד\"ה אלי' הוי שכיח (ך\"ט) מענין טל תחי' ובד\"ה כל כהן שמברך, וע\"כ יהי' נשמות דוקא בגופים לפי שלגבי עצמות אוא\"ס הסוכ\"ע המגביהי לשבת המשפילי לראות כו' שניהם שוין לפניו השוה ומשוה גדול וקטן, ואדרבה כל שהאור גבוה יותר יכול להשפיל יותר וכידוע, וע\"כ יהיו נשמות דוקא בגופים, ונשמות גבוהות שהם יותר מג' אלפים שנה בג\"ע ירדו למטה להתלבש בגוף כדי לקבל ולהנות מאור הסוכ\"ע שלא נתגלה עדיין להם בג\"ע, וזהו ירידה צורך עלי' כו', אך מ\"מ צריכה להיות הנשמה תחלה בג\"ע ואינה יכולה לקבל אור הסוכ\"ע כ\"א ע\"י שהי' תחלה בג\"ע כמ\"ש באגה\"ק סי' י\"ז, והיינו לפי שבהשתל' שמים קדמו ואחר שתהי' בג\"ע יכולה אח\"כ לקבל ג\"כ אור הסוכ\"ע שארץ קדמה, וכנ\"ל בענין הצמצום.\n<b>והנה</b> זהו ג\"כ ענין יוסף ויהודה שהוא ג\"כ בחי' ומדריגת שמים וארץ ובחי' צומח ודומם כו' כי יוסף לשון תוס' וריבוי שמתוסף והולך בהגדלה והגבהה למעלה והוא ענין בחי' צומח שהוא בחי' יסוד שעולה עד הדעת ודעת עולה עד הכתר שז\"ע הצמיחה, ויהודה הוא בחי' ארץ מל' דאצי' שהוא בחי' הרוממות וההתנשאות דמל' דאצי' ולכן יהודה הוא בחי' הודאה וביטול שבדומם יש בו בחי' הביטול ביותר כנ\"ל, והנה בסדר ההשתל' עתה יוסף הוא למעלה מיהודה שהרי המל' מקבלת שפעה וחיותה מן הז\"א ולכן הי' יוסף המלך במצרים שהוא בחי' צומח בחי' גידול והוא הי' המשביר והמשפיע לכולם וכמ\"ש ויוסף הוא השליט על הארץ שהוא מושל על בחי' ארץ שהיא בחי' מל'"],[2000570478,"ויהודה הוא המקבל כו', וז\"ש ויגש אליו יהודה ופי' בזהר שהוא ענין סמיכות גאולה לתפלה, כי תפלה הוא בחי' השתחווא' בחי' ביטול שהוא בחי' יהודה, וגאולה הוא בחי' יוסף שהוא בחי' יסוד כו', וכנודע ממ\"ש במ\"א מענין אם יגאלך טוב יגאל.\n<b>והיינו</b> שהסמיכות גאולה לתפלה הוא כמו ענין שארז\"ל הקובע מקום לתפלתו, דלכאו' אינו מובן שהרי ארז\"ל אל תעש תפלתך קבע, אלא הענין הוא דהנה פי' הקובע מקום לתפלתו היינו כמארז\"ל עשה תורתך קבע ומלאכתך עראי, והנה אין הפי' קבע ועראי בריבוי ומיעוט שימעט במלאכה שהרי אמרו כל תורה שאין עמה מלאכה סופה בטלה כו' וכן אמרו יפה ת\"ת עם ד\"א כו', אלא הפי' קבע היינו עיקר המכוון שעיקר הכוונה יהי' הכל בשביל התורה דהיינו שכל כוונתו שעוסק במו\"מ הוא כדי שיוכל ללמוד תורה ולעבוד את ה'. וזהו מ\"ש ואספת דגנך בפ' שני' של ק\"ש והיינו שיאסוף את דגנך לבחי' אחד והיינו ע\"י שיעבוד בזה להקב\"ה וילמוד בכח זה ויקיים מצותיו, עי\"ז נאספים ג\"כ לבחי' אחד מה שהי' תחלה בבחי' פירוד כו', וז\"ע גוי אחד בארץ שגם בארץ יהי' בחי' אחד כו' כמ\"ש מזה במ\"א בד\"ה ואהבת (ך\"ו), וזהו ענין ואנחנו מאלמים אלומים כו', ע' בת\"א פ' וישב, וזהו ענין כל הקובע מקום לתפלתו דהיינו שכל עיקר כוונתו יהי' בבחי' תפלה כי תפלה הוא לשון התחברות כמו התופל כלי חרס והיינו שמחבר את נה\"א המאיר בגוף עם שרש הנפש בחי' מזל שהוא בחי' אלקות ממש ועי\"ז ממשיך ג\"כ מבחי' קבע כמו שהי' בהמ\"ק דירת קבע דהיינו המשכה שלמעלה מסדר השתלשלו' וכמארז\"ל מט\"ט קושר כתרים מתפלותיהן של ישראל שנתעלה התפלה בבחי' כתר שלמעלה מן החכ' סדר השתלשלות כו' שהוא בחי' קבע, וזהו ע\"י קביעת מקום לתפלתו שכל עיקר כוונתו הוא בתפלה לחבר את נפשו לאלקות בקביעות כו', ומה שאמרו אל תעש תפלתך קבע היינו שלא תעשה בדרך חובה כאילו מגיע לו כי אם רחמים ותחנונים.\n<b>וזהו</b> ויגש אליו יהודה שהוא ענין סמיכת גאולה לתפלה, והיינו כי כדי שיוכל להיות העלאה של תפלה צריך שיהי' נמשך זה הכח מלמעלה כדי לעורר את העלאה זו, וכענין לכה דודי לקראת כלה שנת' בלק\"ת בד\"ה והי' מדי חדש, וכמ\"ש בפרע\"ח ובסידור האריז\"ל בענין פי' תהילות לאל עליון"],[2000570479,"גאלם, וזהו ענין סמיכת גאולה לתפלה המשכה מבחי' גאולה בחי' יוסף לתפלה, ואח\"כ ויגש אליו יהודה שנעשה העלאה של תפלה.\n<b>והנה</b> זהו ענין ג' ראשונות דשמו\"ע שהוא בחי' סידור שבחו של מקום וכמארז\"ל לעולם יסדר אדם שבחו ש\"מ ואח\"כ יתפלל, וזהו ויגש אליו יהודה שהוא בחי' הודאה וביטול במציאות ממש כו', ואח\"כ ויאמר אליו בי אדוני שהוא בחי' י\"ב ברכות אמצעיות כי בי הוא י\"ב שהוא בחי' י\"ב בקר דבריאה שהוא כנגד י\"ב שבטים מרכבתא תתאה ויוסף הוא בחי' יסוד ז\"א דאצי', וזהו ויאמר אליו בי אדוני שהוא בקשה שיומשך אליו למרכבתא תתאה י\"ב בקר דבריאה המשכה מבחי' אצי' שהוא בקשת רפאנו ברך עלינו המשכת גילוי אלקות למטה. ואל יחר אפך בעבדך הוא ענין נפ\"א שהוא בחי' המשכות י\"ג מדה\"ר אל רחום וחנון ארך אפים כו'.\n<b>ועוד</b> יש לפרש ויגש אליו יהודה ס\"ת שוה, והענין הוא דהנה מה שמבואר לעיל שעתה יוסף למעלה מבחי' יהודה כי בהשתל' שמים קדמו, ולע\"ל יתעלה יהודה כי במח' ארץ קדמה ולכן עבדי דוד נשיא עליהם לעולם, זהו רק לפי הפלוגתא אם שמים קדמו או ארץ קדמה, אך יש עוד דיעה שלישית והוא דעת רשב\"י שסובר ששמים וארץ כאחד נבראו וכמ\"ש קורא אני עליהם יעמדו יחדיו ששניהם שוין, וזהו כענין זכור ושמור בד\"א נאמרו שאף שזכור לדכורא ושמור לנוק' שזהו ענין מעלי שבתא ויומא דשבתא, מ\"מ יש בחי' בשבת שלמעלה משניהם שזכור ושמור בד\"א נאמרו, וכמו\"כ שמים וארץ כא' נבראו היינו בחי' שלמעלה משניהם והיינו שאף שבמח' ארץ קדמה דהיינו בבחי' סוכ\"ע, מ\"מ בבחי' מקיף הכללי שהוא מח' הקדומה שצופה ומביט כל הדורות שניהם שוה כא' ממש כו' וד\"ל."],[2000570480,"<h3>ברוך תהי' מכל העמים</h3>\n<b></b><b>קיצור ורשומי דברים, תרכ\"ט</b>\n<b>ברוך</b> תהי' מכל העמים לא יהי' בך עקר כו'. וארז\"ל (בכורות דמ\"ב ב') עקר מן התלמידים, ובמד\"ר (עקב) עקר ועקרה מן התשובה, ומביא המעשה שרכב ר' יונתן אצל טיפולין של כותים כו', עד שהבהמי השיב לו תשובה מפסוק ויכוסו כל ההרים הגבוהים אשר תחת כל השמים ואפי' שבא\"י, כפי' הרמב\"ן בשם פרקי דר\"א שגם בא\"י הי' המים על פני כל הארץ, רק ששם לא נבקעו מעינות התהום, וגם הגשם לא הי' רק שבאו שם המים מחו\"ל, וקרי ר\"י עליו לא יהי' בך עקר ועקרה מן התשובה, ובבהמתך אפי' בבהמות שבך, ונמצא שמפרשים הפסוק על התורה. ובעה\"ט כתב שהפסוק מתחיל בבי\"ת ומסיים בכ\"ף שזהו\"ע כ\"ב אותיות התורה, ולפ\"ז כי ענין הברכה שבפסוק זה הוא בחי' הברכה שיש בתורה שמרומזת בתיבת שלום, שהוא כמו ברכתו של הקב\"ה שלום שיש בה גם מעלת התפלה, כי יש בכלל מאתים מנה כמ\"ש בד\"ה אריב\"ל כל כהן שמברך כו', וצ\"ל מהו שייך לעמים.\n<b>ובירושלמי</b> (ספ\"ח דברכות) ע\"פ זה א\"ר תנחום אם ברכך גוי ענה אחריו אמן שנא' ברוך תהי' מכל העמים, נמצא שמפרש שהברכה הוא מכל העמים דוקא, שהעמים יברכו את ישראל, ולא כפי' הפשוט שתהי' ברוך יותר מכל העמים כ\"א שהברכה תהי' מכל העמים, וכענין והייתם לי"],[2000570481,"סגולה מכל העמים כמ\"ש במ\"א מזה באורך בד\"ה והייתם לי סגולה מכל העמים דחג השבועות, וכ\"מ במד\"ר שארז\"ל אין שבחה של מטרוניתא בזמן שהיא מתקלסת מקרובותי' אלא בזמן שמתקלסת מצרותי', וצ\"ל מהו ענין יתרון הברכה בברכת הגוי דלכאורה ברכת ישראל הי' צריך להיות חשובה יותר, וגם איך יענו אמן על ברכת הגוי דבזהר פ' וילך דרפ\"ה פי' דאמן משיך ברכאן ממבועא למלכא וממלכא למטרוניתא, ואיך יתפרש זה על ברכת הגוי כו'.\n<b>אך</b> הענין יובן בהקדים ענין מ\"ש תורה צוה לנו משה מורשה קהלת יעקב שהתורה נק' בשם ירושה, וצ\"ל הלא ארז\"ל (באבות פ\"ב מי\"ב) התקן עצמך ללמוד תורה שאינה ירושה לך, וגם הלא ארז\"ל (בברכות ד\"ה) ג' מתנות נתנו לישראל וכלם לא נתנו אלא ע\"י יסורים וקחשיב א' מהם תורה, ובמד\"ר (בראשית פ\"ו) ג' מתנות נתנו לעולם התורה והמאורות וגשמים, התורה מנין ויתן אל משה (בפ' כי תשא) וכ\"ה בכ\"מ, וענין המתנה הוא מדעת הנותן ולא כענין הירושה שהיא בהכרח, שאם התנה האב על מה שכתוב בתורה תנאו בטל כמשארז\"ל בפ\"ח דב\"ב. והענין הוא דהנה ארז\"ל ג' שעות ראשונות הקב\"ה יושב ועוסק בתורה, וצ\"ל מהו ענין ג' שעות אלו הלא ארז\"ל כל הקורא בתורה הקב\"ה קורא ושונה כנגדו, ובכל העולם זה קורא בשעה זו והשני בשעה אחרת, ונמצא כי כל היום הקב\"ה קורא ושונה, גם כי מצות התורה הוא להיות והגית בו יומם ולילה לפ\"ד ר\"י (במנחות דצ\"ט סע\"ב) ומהו\"ע ג\"ש ראשונות כו'.\n<b>אך</b> הענין הוא דיש בתורה שני בחי' טל ומטר כמ\"ש יערוף כמטר, תזל כטל, פי' הגם כי בד\"כ תפלה הוא מלמטה למעלה ותורה הוא מלמעלה למטה מ\"מ הרי אמרו שיש בכלל מאתים מנה, ונמצא כי יש בתורה ג\"כ מעלת בחי' התפלה שהוא מלמטה למעלה, וזהו\"ע בחי' מטר כי ענין המטר הוא ע\"י ואד"],[2000570482,"יעלה מן הארץ באתעדל\"ת אתעדל\"ע, משא\"כ טל לא מיעצר ולכן אליהו לא פעל אלא על המטר להיות כי לא אכשור דרא אז שלא הי' אתעדל\"ת לכן פעל שלא יהי' מטר, אבל על טל לא פעל והיינו הגם כי לא אכשור דרא מ\"מ ירד הטל. ועד\"ז יובן בתורה שענין מה שקורא ושונה כנגדו זהו באתעדל\"ת אתעדל\"ע, ולכן יש בזה חילוקי מדרגות עשרה שיושבין כו' ומנין אפי' חמשה כו' עד ומנין אפי' א' כו', וכ\"ז באתעדל\"ת אבל ג' שעות ראשונות זהו בחי' טל תורה.\n<b>וביאור</b> הענין יובן בהקדים ענין מ\"ש זמירות היו לי חוקיך בבית מגורי, וארז\"ל (בסוטה דל\"ה ע\"ב) דוד זמירות קרית להו הריני מכשילך בדבר שאפי' תינוקות של בית רבן יודעין אותו שנא' ולבני קהת לא נתן כי עבודת הקדש עליהם בכתף ישאו, והוא שכח והוביל את הארון בעגלה חדשה, וצ\"ל חטא דוד ועונשו. והענין הוא שדוד שיבח את התורה שכל קיום וחיות העולמות תלוים בדקדוק אחד מד\"ת, ולכן נשתעשע בלימוד תורתו בכדי שלא יתפוס מקום אצלו כל הצרות שהי' לו בגשמי', כי מה תופס מקום היסורים שלו של ע' שנה נגד מעלת התורה שכל חיות העולמות עליונים ותחתונים תלוים בדקדוק א' והוא למד כל התורה, ובאמת כן הוא שהרי נודע כי ע\"י הקרבן הי' נעשה עלי' העולמות מסוכ\"ד עד רכ\"ד, וכמ\"ש בזהר דרזא דקרבנא עולה עד רזא דא\"ס, וקרבן הוא לשון קירוב הכוחות והשמות כמ\"ש הבחיי בשם הרמב\"ן ז\"ל. וכ\"ז כשהקרבן כשר אבל אם קבל הדם בשמאל או שלא בכלי שרת או כ\"ד הפוסל לא נעשה שום עלי', ונמצא כי בדקדוק א' תלויים כל עלי' העולמות מסוכ\"ד עד רכ\"ד.\n<b>ועד\"ז</b> הוא בענין המשכת אלקו', כמו עד\"מ כשישראל מניח תפילין ממשיך להיות הקב\"ה מניח תפילין, ע' מזה בד\"ה ויקחו לי תרומה (ך\"ח) והיינו ענין המשכת מוחין לז\"א, ונודע ההפרש בין מוחין למדות דמבשרי אחזה, שהמדות שייכים לזולתו דוקא וכ\"ש השפעת המדה, אבל השפעת השכל אינו שייך לזולתו דוקא שיכול לישב [לעצמו] ולהשכיל השכלות, וגם בעצם השכל ה\"ה בדרך העלאה דוקא וכענין שתיק רב, אשתומם כשעא חדא, וכמו בסנהדרין שהיו נושאין ונותנים כו', ופרש\"י והרמב\"ם כ\"א בביתו או עם בן זוגו ולא כולם יחד, להיות כי כשצריך לברר אמיתי' הענין בהכרח שישבות השכל"],[2000570483,"מפעולתו בדרך ירידה ויעלה אותו שיקבל ממקור השכל כו', כמ\"ש מזה במ\"א באורך ומזה בד\"ה אשר ברא (דך\"ח). ועד\"ז יובן למעלה שענין המדות הם מקור לעולמות כמ\"ש זכור רחמיך ה' וחסדיך כי מעולם המה, וכתיב כי אמרתי עולם חסד יבנה, ויש בזה ב' פי' הא' כפשוטו והב' שצריכים לבנות החסד, ע' מזה בד\"ה ולקחתם אגודת אזוב (ך\"ז) אבל ענין המוחין נודע ממארז\"ל אלפים שנה קדמה תורה לעולם פי' ממעלת העולם, כמ\"ש מזה בכ\"מ בכ\"ד, וע\"י התפילין ממשיכים להיות הקב\"ה מניח תפילין שיומשך מוחין לז\"א כמ\"ש בד\"ה ויקחו לי תרומה הנ\"ל ובד\"ה את שבתותי תשמרו שלא נדפס שזהו המשכה גבוהה מאד, וכ\"ז כשהתפילין כשרים אבל אם נמצא פסול בהתפילין לא יש שום המשכה כלל. ועד\"ז בכל מצותי' של תורה כמו סוכה ולולב ושבת תלוי כל קיום וחיות העולמות בדקדוק א' מד\"ת, שאם חסר איזה דבר לא יש שום העלאה וכמ\"כ בהמשכה.\n<b>ולכאורה</b> הרי זהו שבח גדול ולמה נענש על זה, אך הענין הוא דהנה על התורה כתיב ראיתי והנה מגילה עפה כתובה פנים ואחור (בזכרי') שיש בה בחי' פנימיות ואחוריים, ומה שכל קיום וחיות העולמות תלוים בדקדוק א' זהו לגבי בחי' חיצוניות התורה, היינו מה שנתלבשה בדיני ההלכות כשר פסול כו', שזהו בחי' נובלות חכ' שלמעלה תורה, אבל בחי' פנימי' התורה ע\"ז נאמר לא ידע אנוש ערכה אלקי' הבין דרכה, ובידיעת עצמותו יודע את התורה, ועז\"נ ואהי' אצלו שעשועים שאינה שעשועי לב האדם כ\"א שעשועי המלך בעצמותו, וכשם שכל העולמות עליונים ותחתונים כלא חשיבי לגבי א\"ס ב\"ה דכתי' אני הוי' לא שניתי, כמו כן לגבי בחי' פנימי' התורה כל העולמות"],[2000570484,"הם כלא ממש, ולכן לגבי בחי' פנימיותה אין לשבחה במה שכל קיום וחיות העולמות הם תלוים בדקדוק אחד מד\"ת, מאחר שכל העולמות הם כלא ממש נגד פנימיותה, והיא מיוחדת לגמרי בבחי' א\"ס ב\"ה המלובש בה בתכלית היחוד כו'.\n<b>וזהו\"ע</b> שהתורה היא ממוצע בין המאציל לנאצלים, והממוצע צריך להיות כלול משניהם, וזהו בחי' פנים ואחור, וזהו\"ע עוטה אור כשלמה, שלמה בחי' כשר פסול שבתורה נובלות כו', ואור בחי' פנימיות התורה, ולכן נענש מדה כנגד מדה ונפל בשכחה, שלפ\"ז שכח מ\"ש ולבני קהת לא נתן כו' בכתף ישאו, דבר שתשב\"ר יודעין כו', ובהכרח צריך לשכוח ע\"ז דוקא דאל\"כ לא הי' אצלו שכחה, דהלוחות היו כתובים משני עבריהם וארז\"ל בירושלמי דשקלים שלא הי' בהם פנים ואחור והיו צריכים לשאת בכתף בכדי לחבר פנים ואחור ואז לא יש שכחה, וכנודע מענין ולזכרון בין עיניך הנאמר בפ' קדש, ודוד מאחר ששבח בחי' התורה בבחי' אחוריים שבה לכן נענש מדה כנגד מדה הי' צריך ליפול בשכחה שנמשך מבחי' אחוריים, לכן בהכרח הי' צריך לשכוח על חיבור בחי' פנים ואחור, דלוחות צריך לשאת בכתף דוקא כו'.\n<b>והנה</b> ב' בחי' אלו שבתורה זהו\"ע טל ומטר דתורה, שבחי' פנימי' התורה זהו בחי' טל תורה ובחי' חיצוניות מה שנתלבשה בדיני ההלכות זהו\"ע מטר, ובחי' זו הוא באתעדל\"ת אתעדל\"ע כל הקורא בתורה הקב\"ה קורא ושונה כנגדו, והנה ארז\"ל (בכתובות דקי\"א ב') כל המשתמש באור תורה אור תורה מחייהו, ובילקוט הגירסא טל תורה, וענין ההפרש בין אור לטל כי אור שנברא ביום ראשון הי' אדם מביט בו מסוף העולם ועד סופו, ראה שאין העולם כדאי עמד וגנזו לצדיקים לע\"ל, והיכן גנזו בתורה פי' מסוף העולם ועד סופו דהול\"ל מתחלת העולם ועד סופו, אלא הכוונה הוא בב' עולמות עלמא דאתכסי' ועלמא דאתגלי', ונתבאר בד\"ה כל כהן שזהו בכל כללות ההשתל', ואור זה גנוז בתורה ולכן איתא בזהר ח\"ג בהשמטות ד' ד\"ש סע\"ב על ר\"א שאמר ואנא חמינא כאלו חמינא בעיני והיינו בכח תורתו, ובחי' זו זהו גשם דתורה כי זפ\"ז הוא מ\"ט וז\"פ מ\"ט עולה שמ\"ג כמנין גשם, ונמצא כי אור ז' הימים הוא בחי' גשם דתורה, שבחי' זו באפשר להגיע ע\"י אתעדל\"ת, וכל המייגע עצמו בתורה עד שהוא משתמש באור תורה היינו בבחי' אור זה\"י שיש בתורה אז טל תורה מחייהו לפי גירסת הילקוט, דההפרש בין אור לטל כי הטל הוא מטלא דנטיף מעתיקא שעתיד להחיות בו את המתים. והנה ארז\"ל במד\"ר כל תולדות שבמקרא חסר לבר מן תרין אלה תולדות השמים ואלה תולדות פרץ, והיינו כי העולם על מילואו נברא פי' באופן שלא יהי' מיתה כלל, אך ע\"י חטא עה\"ד"],[2000570485,"נקנסה מיתה על כל באי עולם, ולע\"ל כשיהי' ואת רוח הטומאה אעביר מן הארץ יהי' בלע המות לנצח ויחיו כל המתים, אמנם הנה מנין שאינו דומה מה שלא יהי' מיתה או כשנקנסה מיתה שיחיו המתים, שבחי' תחה\"מ מוכרח להיות ממקום גבוה יותר, ובעבודה מאן דנפיל מדרגי' אקרי מת, ואינו דומה שלא יפול מדרגי' או כשכבר נפל שיתעלה, וזהו ההפרש בין אור זה\"י לבחי' הטל, וזהו כענין ההפרש בין שיורי טלא דבדולחא לבחי' טלא דנטיף מעתיקא, ששיורי טלא מטהר טומאת מת כמ\"ש באגה\"ק בד\"ה למה נסמכה, אבל אינו מחי' המת, וטלא דנטיף מעתיקא מזה יהי' תחה\"מ לע\"ל, וכל המשתמש בבחי' אור הגנוז דתורה טל תורה מחייהו בבחי' פנימי', ובחי' זו הוא בחי' מתנה, ומ\"מ גם המתנה אין נותנים כ\"א למי שראוי, דאי לאו דעביד לי' נייחא לא הי' נותנים לו, וזהו מי שיגע בתורה עד שבא לבחי' אור הגנוז דתורה טל תורה מחייהו היינו שנותנים לו המתנה, וע\"ד מי שטרח בע\"ש יאכל בשבת, וע\"ד סעודה שלישית דשבת, וע\"ד תפלת ערבית רשות לחד פירושא בזהר, וע\"ד עבודת מתנה וכהנה רבות, רק שבחי' זו דתורה גבהה מעלתה ע\"ד שכל בחי' שמלמעלה למטה גבוה מבחי' שמלמטה למעלה, וכנודע מענין ההפרש בין ג\"ע לתחה\"מ כמ\"ש בחינוך ובד\"ה ואתחנן שלא נדפס.\n<b>ועפ\"ז</b> יובן ענין התקן עצמך ללמוד תורה שאינה ירושה לך, הגם דכתיב מורשה לשון ירושה עכ\"ז צריך להיות התקן עצמך, וכמו שפרש\"י והרע\"ב שלא תאמר הואיל ואבא חכם ואבי אבא חכם כו' תורה מחזרת על אכסניא שלה שכך דרז\"ל בפ\"ו דב\"מ דפ\"ה מפסוק לא ימושו מפיך כו' ומפי זרע זרעך אמר ה' מעתה ועד עולם (בישעי' סי' נ\"ט) וקמ\"ל ר\"י דהנ\"מ כשמתקן עצמו לכך דמתקיימא בי' יותר מבזולתו, ואי לאו הכי לא (תוי\"ט) וע' במדרש שהביא שהגם שהתורה ירושה אבל אינה היא לך, כ\"א לכל ישראל ואפשר שתתקיים באחר, ולכן צריך להיות התקן כו', וע' מזה בד\"ה ויתן אל משה (דך\"ח). והענין הוא דהנה מעיקרא כי עביד אינש אדעתי' דנפשי' קעביד, פי' לתקן נפשו, ע' מזה בלק\"ת בד\"ה האזינו ובסי' בדרושי החתונה, והיינו כי"],[2000570486,"התורה היא עוז ותושי' עוז לנה\"א ותושי' לנה\"ב, כי מתיש כחו של נה\"ב, ע' מזה בד\"ה בחדש השלישי בת\"א, וזשארז\"ל בסוכה דנ\"ב ובקידושין דל\"ב תני ר\"י אם פגע בך מנוול זה משכהו לבהמ\"ד (פרש\"י מנוול יצה\"ר) אם אבן הוא נימוח, פי' בלק\"ת בד\"ה האזינו הנ\"ל סי' ה' שאפי' אם לבו מטומטם כאבן, יכולה להמחות ע\"י התורה שנמשלה למים (בישעי') כי ע\"י התורה נמשך ממים העליונים ונק' מטר ארצך, וי\"ל שקאי על דברי אגדה שבתורה (וכמשנ\"ת בד\"ה מהיכן זכו (ך\"ח) באורך) שדברי אגדה יכולים לפתוח לבו של אדם הן בענין ההעלאה להיות נגילה ונשמחה בך בעצמותך, וכן בענין ההמשכה להיות מכיר את מי שאמר והי' העולם כו'. ופי' משכהו לבהמ\"ד היינו שימשכהו בדברים שזהו אדעתא דנפשי', ועי\"ז אח\"כ מתוך שלא לשמה בא לשמה לשם התורה היינו להמשיך אא\"ס בתורה, וכענין טל תורה.\n<b>והנה</b> התורה נתלבשה בענינים גשמי' כשר ופסול כו', והיינו שזהו\"ע בירור ניצוצי' דתהו, כי ז' מלכים דתהו קדמו לתיקון שזהו\"ע לפני מלך מלך לבנ\"י ונפלו בשבה\"כ, ומה שנתברר מיד ירשו פרצופי האצי' כמ\"ש מזה בלק\"ת מהאריז\"ל בפ' נחלות ובכ\"מ, וזהו\"ע ויקם עדות ביעקב ותורה שם בישראל, עדות אינה עצם הדבר, ויקם עדות ביעקב, להיות כי ע\"י העדות הם המצות שנתלבשו בגשמי' דוקא, עי\"ז מבררי' כל דברים הגשמי' שמקבלים חיות מנוגה להיות עולים ונכללים בשרשן הראשון דתהו, ועי\"ז יתוסף תוס' אורות בכלים דתיקון, וכמ\"ש בע\"ח שכל הנימין והשערות הם מבירורי' דרפ\"ח ניצוצי', שעיקר הבירור הוא בעוה\"ז דוקא, וע' בלק\"ת סד\"ה האזינו השמים הא' שגם בבחי' יערוף כמטר נמשך הארה מבחי' הפנימי' המתלבשת בבחי' המזלות שזהו\"ע שיורי טלא דבדולחא, והיינו כי ע\"י הבירורים שמבררים ע\"י המצות נמשך בחי' האור תורה הנ\"ל בחי' שיורי טלא הנ\"ל כו', וכשהוא מתקן עצמו ללמוד תורה ע\"מ לעשות ועושה בכוונה כדבעי אז הוא משתמש באור תורה כו' ובריבוי העבודה יוכל לבוא למדרגת הראי' דאור הגנוז שיש בתורה ע\"ד ראב\"ש וכנ\"ל, וכ\"ז הוא ע\"י הבירורים שמברכים מניצוצות דתהו דוקא, ששם הי' האור בריבוי דוקא כנודע, וכמ\"ש בביאור ע\"פ בחוקותי שלא נדפס שענין הריבוי אינו שאור זה גופא הי' בריבוי כ\"א שהוא אור עליון גבוה הרבה מבחי' האור דתיקון, וכענין ההפרש בין אור שנברא ביום א' להאור שנשאר אחר המיעוט כמ\"ש במ\"א באריכות."],[2000570487,"<b>ובזה</b> יובן ג\"כ כל אריכות הגלות שהוא להוציא הניצוצות, כי עת אשר שלט האדם באדם הוא לרע לו, היינו בכדי להוציא הניצוצות שזהו\"ע ואכלת את כל העמים, שהבירור הוא דוקא מכל העמים ששרשן מתהו שקדם לתיקון, וכענין והייתם לי סגולה מכל העמים דוקא, ובחי' זו נק' ירושה שאח עשו ליעקב דוקא, משא\"כ ישראל כי שרית כו', וע' בלק\"ת מהאריז\"ל, וארז\"ל בפסחים ד\"ה תר\"י בשכר שלשה ראשון זכו לשלשה ראשון, להכרית זרעו של עמלק שנאמר ויצא הראשון אדמוני, ונמצא כי יעקב אחיו יורשו.\n<b>וזהו</b> לא יהי' בך עקר ועקרה כו', ואי' במאו\"א עקר ס\"ם עקרה נוק' שהוא שרו של עשו, וכשיבררו הכל אזי לא יהי' בך עקר ועקרה, וכמ\"ש רז\"ל בסוכה לע\"ל הקב\"ה מביאו ושוחטו לצדיקים נדמה להם כהר והיינו כשיהי' ואת רוח הטומאה אעביר ובלע המות לנצח ישחוט השר שלו וזהו לא יהי' בך עקר, וכ\"ז הוא ע\"י ולא יהי' בך עקר מן התלמידים והיינו כי ע\"י תומ\"צ יבררו זה, כי תורה עצמה הוא ג\"כ מצוה וכמ\"ש חז\"ל ות\"ת כנגד כולם.\n<b>וזהו</b> ברוך תהי' מכל העמים אם ברכך גוי ענה אחריו אמן, פי' מאחר שהוא מברכך זהו הוראה שכבר נתברר חלקו, והברכה הוא שיומשך משרשו ומקורו בבחי' התהו שקדם לתיקון, ולכן יש מעלה בברכת הגוי להיות כי שרשו גבוה, וגם שאינו מתעכב מאחר שגם הסט\"א מסכים ע\"ז וגם הגוי הוא שליח (בזח\"ג שמיני דל\"ו ול\"ז) ולכן ענה אחריו אמן להמשיך ממבועא למלכא וממלכא למטרוניתא, להיות נמשך המשכה זו בבי\"ע, ולכן עיקר הברכה הוא מכל העמים דוקא, וכענין הסגולה שהוא ג\"כ מכל העמים כמ\"ש במ\"א, וזהו אין שבחה של מטרוניתא כשהיא מתקלסת מקרובותי' כ\"א מצרותי' דוקא, והיינו כי ע\"י השבח והברכה זו נמשך תוס' וריבוי מבחי' התהו שקדם לתיקון."],[2000510067,"<h3>ויקח ה\"א את האדם</h3>\n<b></b><b>בס\"ד. (ש\"פ בראשית, ל\"א).</b>\nבראשית\n<b>ויקח</b> ה' אלקים<sup data-n=\"1\">1</sup> את האדם ויניחהו בגן עדן לעבדה ולשמרה, וארז\"ל במד\"ר ס\"פ ט\"ז ויניחהו מצות שבת מסר לו כד\"א וינח ביום השביעי, לעבדה ששת ימים תעבוד כו', ולשמרה שמור את יום השבת. וצ\"ל שהרי פי' לעבדה ולשמרה הוא ציווי, ואיך מפרש המד\"ר לעבדה הוא כמ\"ש ששת ימים תעבוד שהם רשות. ויש להקדים מ\"ש ביעקב ואני אתנהלה לאטי לרגל המלאכה<sup data-n=\"2\">2</sup> כו' עד כו' שעירה, ולא מצינו שהלך יעקב לשעיר[ednref_1_א].\n<b>והענין</b> הוא דהנה מצינו בדברי רז\"ל ששיבחו את המלאכה כמארז\"ל באבות פ\"א משנה יו\"ד שמעי' אומר אהוב את המלאכה, וכן ארז\"ל ברכות ד\"ח סע\"א גדול הנהנה מיגיעו יותר מירא שמים דאילו גבי יר\"ש כתיב אשרי איש ירא כו', ואילו גבי נהנה מיגיעו כתיב יגיע כפיך כו' וטוב לך כו', ולגבי יר\"ש וטוב לך לא כתיב בי'. וצריך להבין מהו ענין גדלות מעלת המלאכה כל כך. וגם צ\"ל מה שארז\"ל במשנה ב' פ\"ז דשבת אבות מלאכות ארבעים חסר א', וארז\"ל בשבת פ\"ד דמ\"ה ע\"ב הא דתנן אבות מלאכות כו' כנגד מי, אמר להו ר' יונתן בר\"א כך אמר ר' שמעון בר'",[["1","1","<b>ויקח ה' אלקים</b>: נמצא בבוך 1061 בכת\"י מעתיק עם תיקונים והגהות בגוכתי\"ק כ\"ק אדמו\"ר מהר\"ש. והוא ד\"ה אבות מלאכות בסה\"מ תר\"ל ע' רמט ואילך בשינוי ההתחלה עם הוספות. וראה גם שם ע' רמב ואילך. והוא מיוסד על ד\"ה ששת ימים תעבוד באוה\"ת יתרו ע' תתקנא ואילך. חלק מהמאמר (עד סוף פ\"ד) נמצא בשינויים ובתוס' התחלה בד\"ה במשנה כו' מניח אני כל אומנות בסה\"מ תרמ\"א. [וראה גם ד\"ה וכך הי' מונה תרמ\"א]. ונמצא בתוס' ביאור בד\"ה ויקח ה\"א בסה\"מ עטר\"ת ע' לח ואילך. תרח\"צ ע' עז ואילך.\nלעניני המאמר ראה: תו\"א יתרו סט, ג ואילך. אוה\"ת בראשית (כרך ב) תנז, א [ד\"ה יעבור גו' ואני אתנהלה]. שם תנח, א [ד\"ה ויהי גו' ויבוא הביתה]. ד\"ה שלש רגלים סה\"מ תרע\"ח ע' קעד."],["2","2","<b>מ\"ש ביעקב ואני אתנהלה לאטי לרגל המלאכה</b>: בסה\"מ תר\"ל נוסף: צ\"ע הלא פסוק לרגל המלאכה נמנה בל\"ט פעמים מלאכה שכנגדם נאסר ל\"ט מלאכות, כי בחי' חסר א' הוא תיבת מלאכה של והמלאכה היתה דים, או לעשות מלאכתו כמ\"ש בגמ' שבת דמ\"ט ב'.\n\n[edn_1_א] <b>ולא מצינו שהלך יעקב לשעיר</b>: בגוכי\"ק נוסף כאן: אלא שקאי על לע\"ל דכתיב ועלו מושיעים כו' לשפוט כו', מובן שהגלות נק' רגל המלאכה כו'. וצ\"ל למה נק' הגלות בשם מלאכה."]]],[2000510068,"יוסי בן לקוניא כנגד מלאכה מלאכתו ומלאכת שבתורה, שלמדו זה מארבעים פעמים מלאכה שנאמר בתורה. ולפ\"ז צ\"ל למה לא אסרו ארבעים מלאכות. וגם צ\"ל למה אמרו לשון ארבעים חסר אחת ולא אמרו ל\"ט כו'.\n<b>ויובן</b> בהקדם מ\"ש ויכל אלקים ביום השביעי מלאכתו אשר עשה וישבות כו' מכל מלאכתו כו', ואח\"כ כי בו שבת מכל מלאכתו אשר ברא כו'. ולכאורה יפלא הלא כתיב בדבר ה' שמים נעשו, ובעשרה מאמרות ברא את העולם, וכמארז\"ל לא בעמל ולא ביגיעה<sup data-n=\"3\">3</sup> כו', ואיך נק' בשם מלאכה, שהרי דבור אינה מלאכה, ואם נאמר שהדבור ג\"כ מלאכה, א\"כ צ\"ל מדוע לא נאסר הדבור בשבת מן התורה, ולא נאסר מן התורה כ\"א מעשה, אבל דבור מותר אפי' דיבור של חול, רק שמדרבנן אסור דבור ג\"כ, וסמכוהו אקרא שנאמר ממצוא חפצך ודבר דבר, שלא יהא דבורך של שבת כדבורך של חול, אבל מן התורה מותר הדבור, ולפי מה שנת' שהתהוות כל מעשה בראשית הוא מבחי' דבור לבד, שמבחי' עשרה מאמרות שבת אח\"כ ועז\"נ וישבות ביום השביעי מכל מלאכתו אשר עשה, הי' צ\"ל למטה ג\"כ הדבור אסור מן התורה, ולמה לא אסרוהו רק מדרבנן. גם צריך להבין מאחר שמן התורה מותר למה אסרוהו מדרבנן.\n<b>ולהבין</b> זה צריך להבין ההפרש בין מחשבה לדבור, שאנו רואים שהמחשבה מתאחדת יותר עם כחות הנפש, שהרי המחשבה היא לבוש הפנימי<sup data-n=\"4\">4</sup> כו', וא\"א לחשוב שום שכל בלתי מחשבה כו', משא\"כ הדבור נעשה נפרד ויוצא לחוץ, שהדבור יוצא לאויר העולם כו'. ועד\"ז יובן למעלה שורש ההפרש בין מחשבה לדבור שלכאורה הדבור הוא בחי' נפרד כבי', אך באמת א\"א לומר כן למעלה ח\"ו שהרי אין לך דבר שחוץ ממנו וכמשנ\"ת בסש\"ב<sup data-n=\"5\">5</sup>, שמאחר שאת השמים ואת הארץ אני מלא, ולית אתר פנוי מיני' א\"א לומר שהדבור הוא בחי' נפרד ח\"ו, וא\"כ כשנאמר שהדבור אינו נפרד כלל, איך נתהוו מבחי' הדבור עולמות הנפרדים כעוה\"ז הגשמי, אלא עכצ\"ל שבחי' הדבור עליון נתצמצם בכמה בחי' צמצומים צמצום אחר צמצום, עד שנתהוה בחי' דבור שיוכל להתהוות מבחי' דבור זה נבראים נפרדים דעשי' שלמטה כו'.\n<b>וזהו</b> מ\"ש נעשה אדם בצלמינו כדמותינו<sup data-n=\"6\">6</sup>, פי' וענין הדמות הוא דמיון לבד, ואינו עצם הדבר כמו שהוא, וא\"כ פי' כדמותינו שזהו רק כדמיון הדבר שלמעלה ולא כמו הדבר שלמעלה עצמו, והיינו שעלמא תתאה היא רק כגוונא דעלמא",[["3","3","<b>לא בעמל ולא ביגיעה</b>: ראה סה\"מ תרל\"ב ח\"ב ע' שפז וע' שפט."],["4","4","<b>ההפרש בין מח' לדבור. . לבוש הפנימי. . נפרד</b>: ראה ביאוה\"ז להצ\"צ (כרך ב) ע' תקפח. סה\"מ תר\"ן ע' שה-ו. סה\"מ אעת\"ר ע' מג ואילך. המשך תער\"ב ח\"ב ע' א'קעז ואילך. סה\"מ מלוקט ח\"ב ע' רצב."],["5","5","<b>הדבור. . נפרד. . א\"א לומר כן למעלה ח\"ו. . וכמשנ\"ת בסש\"ב</b>: תניא פכ\"א (כו, ב). וראה גם ד\"ה פתח אלי' תרנ\"ח ס\"ע כג-ד. ובכ\"מ."],["6","6","<b>וזהו מ\"ש נעשה אדם בצלמינו כדמותינו</b>: הבא לקמן עד סוף הפרק הובא לקמן ח\"ב ד\"ה ועשיתם עולה."]]],[2000510069,"עילאה, ולא כמו עלמא עילאה עצמה כו'. והיינו שכמו שיש ד' פנים, פני ארי' פני שור פני נשר פני אדם בבחי' המרכבה כו', כמו\"כ נתהווה למטה ג\"כ ד' פנים, אדם שלמטה שרשו מבחי' פני אדם, וארי' שלמטה שרשו מבחי' פני ארי' כו' וכן שור ונשר כו', אמנם הנה מ\"מ מה שנברא למטה הוא רק דמות לבד לגבי בחי' שרשם ומקורם בחי' ד' פנים שלמעלה. וכן אפי' המצות שלמטה שנתלבשו בדברים גשמי' הם רק כמו דמות גבי בחי' מצות שלמעלה, כמו לגבי תפילין שלמעלה היינו מה שהקב\"ה מניח תפילין ומתעטף בציצית, וכמארז\"ל במד\"ר ע\"פ מגיד כו' חוקיו ומשפטיו מה שהוא עושה אומר לישראל לעשות כו', הנה לגבי מצות אלו התפילין והציצית הגשמי' שלמטה הם רק בחי' דמות ודמיון ורמז לבד<sup data-n=\"7\">7</sup>, מאחר שהם נתלבשו בדברים גשמי'[ednref_2_ב]. ועד\"ז יובן בענין הדבור שמה שנתצמצם הדבור בכדי שיוכל להיות ע\"י בחי' הדבור המצומצם בחי' התהוות נבראים נפרדים בעלי גבול, הנה על בחי' דבור זה המצומצם כינו בכתוב בשם מלאכה, והיינו כי בבחי' הדבור יש ב' בחי', הא' כמו שהוא מאיר למעלה בלתי התלבשות כ\"כ אשר מבחי' דבור זה נתהוו עולמות עליונים אז אינו נק' מלאכה כלל, והב' הוא בחי' הדבור שנתצמצם בכמה צמצומים שיוכל להיות ע\"י בחי' דבור זה בחי' נבראים נפרדים בעלי גבול שזהו בחי' דמות לבד.\n<b>ויובן</b> דבר זה ע\"ד שמצינו בנבואה שיש בה ג\"כ ב' בחי' היינו בחי' צלם ודמות, וכמ\"ש גבי נביאים בהושע י\"ב פ' י\"א וביד הנביאים אדמה, וכמארז\"ל כל הנביאים נתנבאו בכה, אבל משה נתנבא בזה<sup data-n=\"8\">8</sup> וכמ\"ש זה הדבר, והיינו שבנבואת משה הי' מאיר בו ומתגלה הדבור כמו שהוא בלתי העלם והסתר, וז\"ע זה הדבר שהי' בבחי' זה והתגלות הוא בחי' אספקלריא המאירה כמשל אדם הרואה דרך זכוכית בהירה שאינה מסתרת כו', משא\"כ שארי הנביאים נתנבאו בכה שהוא רק בחי' דמות לבד שלא הי' מתגלה הדבור אצלם כמו שהוא בלתי צמצום כו', כ\"א הי' מתצמצם ומתעלם עד שנמשך להנביא ולכן כתיב בהם וביד הנביאים אדמה שהוא בחי' דמות לבד הוא בחי' אספקלריא שאינה מאירה כו', כמשל הרואה דרך זכוכית הנק' שפיגול שאינו רואה עצם הדבר כ\"א הדמות מהדבר כו'. ועד\"ז יובן ב'",[["7","7","<b>מצות. . שלמטה הם רק בחי' דמות ודמיון ורמז לבד</b>: ראה בארוכה מאמרי אדה\"ז תקס\"ד ע' צב. אוה\"ת בשלח ע' תעג-ד. שלח ע' תמד. בד\"ה זה בסה\"מ עטר\"ת שם ע' מא מוסיף: המצות שלמטה הן רק בחי' דמיון למצות שלמעלה וכמ\"ש הציבי לך ציונים, שהמצות הן רק בחי' ציון וסימן. וראה בארוכה רמב\"ן עה\"ת פ' אחרי יח, כה."],["8","8","<b>וביד הנביאים אדמה. . משה נתנבא בזה</b>: בהבא לקמן בפרק זה ראה תו\"א מקץ לג, א-ב. לקו\"ת נצבים מז, ג. דרושים לשמע\"צ צב, סע\"ב. שה\"ש כח, ב. סה\"מ תרל\"ב ח\"א ע' פא. וע' צט. וראה גם אוה\"ת שה\"ש ע' שמט. סה\"מ תרמ\"ט ע' קמט-קנ.\n\n[edn_2_ב] <b>מאחר שהם נתלבשו בדברים גשמי'</b>: בגוכי\"ק נוסף כאן: רק מחסד ה' עלינו נתן לנו התומ\"צ כמו שהם נתלבשו בדברים גשמיים ומרמזים לבחי' המצות שלמעלה, ועי\"ז נמשך בחי' המצות שלמעלה כו'."]]],[2000510070,"בחי' שבדבור שנעשה מקור לעולמות שיש בו ב' בחי', הא' בחי' הדבור שהוא בחי' התגלות הדבור כמו שהוא שמזה נעשו עולמות עליונים שהם בבחי' בצלמנו כו', ובחי' הדבור כמו שהוא נתצמצם ומתעלם כדי שיהיו עולמות התחתונים שהם רק כגוונא דעלמא עילאה הוא בחי' כדמותינו בחי' דמיון לבד כו'[ednref_3_ג].\nב) <b>ועפ\"ז</b> יובן מה שעשרה מאמרות נק' מילין דהדיוטא וכמ\"ש בזהר לאו אורחא דמלכא<sup data-n=\"9\">9</sup> לאשתעי במילין דהדיוטא, היינו מפני שעשרה מאמרות נעשו מקור לעולמות הנפרדים שנתצמצם הדבור בבחי' צמצום אחר צמצום כו' שזהו שכינו בכתוב בשם מלאכה שהוא בחי' ששת ימי בראשית בחי' ששת ימים עשה כו' הם ששת ימי המעשה, ולכן נק' בחי' זו מילין דהדיוטא כו'. וזהו שאנו אומרים ובטובו מחדש בכל יום תמיד מעשה בראשית, וכתיב מה רבו מעשיך ה' שבחי' דבור המתצמצם בצמצום אחר צמצום בכדי להוות ולהחיות מאין ליש בחי' העולמות בעלי גבול עד עולם העשי' הגשמי הוא הנק' בחי' מעשה למעלה שזהו בחי' מלאכה כו'. ולכן מלאכה בגימטריא אל אד', והיינו לפי ששם זה אל אד' בגימטריא צו מאיר בעשי'<sup data-n=\"10\">10</sup>, שהתהוות העשי' הוא מבחי' הדבור המצומצם שנק' בשם מלאכה כנ\"ל לכן השם שמאיר בעשי' גימ' מלאכה כו'.\n<b>ובזה</b> יובן מעלת המלאכה ששיבחו אותה רז\"ל שאמרו גדול הנהנה מיגיעו כו', והוא לפי שע\"י עבודת האדם בבחי' מלאכה שלמטה שאדם עושה עי\"ז הוא ממשיך למעלה שיומשך כביכול בבחי' צמצום הדבור שנקרא מלאכה, היינו שיומשך בחי' אותיות המצומצמים בבחי' דבר ה' הנצבים בנבראים דעשי' להחיותם ולהוותם מאין ליש כמ\"ש לעולם ה' דברך נצב בשמים, וכידוע שאם הי' מסתלק כרגע ח\"ו הי' חוזר לאין ואפס כמ\"ש בסש\"ב ח\"ב פ\"א, ובתחלת הבריאה הי' זה מצד בחי' כי חפץ חסד ועכשיו באתעדל\"ת תליא מילתא, שע\"י עבודת האדם בבחי' מלאכה עי\"ז נמשך בחי' חידוש הישינות שיומשך בחי' התחדשות החיות מאין ליש תמיד, שז\"ע מה שאנו אומרים המחדש בטובו בכל יום תמיד מעשה בראשית כו'. אך הנה כ\"ז הוא כשעושה המלאכה באמונה שאין בה ח\"ו שום נדנוד עבירה היינו גזל וגניבה ח\"ו כ\"א עושה ועוסק במלאכתו באמונה, וע\"י העסק באמונה ממשיך בחי' חידוש הישינות שיומשך בחי' הדיבור בצמצומים רבים",[["9","9","<b>וכמ\"ש בזהר לאו אורחא דמלכא</b>: ראה אוה\"ת פ' בא (כרך ז) ע' ב'תרכד בפי' מילין דהדיוטא. וראה גם לקו\"ת אחרי כה, ד."],["10","10","<b>אל אד' בגימטריא צו מאיר בעשי'</b>: ראה לקו\"ת מסעי פט, סע\"ב. סה\"מ תרל\"ב ח\"א ע' קמט. ח\"ב ע' שעה.\n\n[edn_3_ג] <b>עולמות התחתונים. . בחי' כדמותינו בחי' דמיון לבד כו'</b>: בגוכ\"ק נוסף כאן: ובאדם דכתיב בי' בצלמנו כדמותינו צריך לומר שיש בו מב' הבחי', ולכן יכול להמשיך גילוי אלקות ע\"י התורה ומצות בחי' בצלמנו בעולמות הנבראים ובע\"ג שהם בחי' כדמותינו."]]],[2000510071,"שנק' מלאכה להחיות ולהוות עולמות הנפרדים שזהו בחי' מלאכה כמשנ\"ת לעיל, וכמ\"ש ביונה ששאלו לו מה מלאכתך, ופירשו המפרשים ששאלו לו אם עסק באמונה.\n<b>ועפ\"ז</b> יובן ג\"כ מה שארז\"ל במד\"ר ס\"פ ויצא פע\"ד ר' ירמי' אמר חביבה היא המלאכה מזכות אבות כו'<sup data-n=\"11\">11</sup>, שהרי יעקב אמר את עניי ואת יגיע כפי ראה אלקי' ויוכח אמש, שבזה הזכיר מלאכה ולא הזכיר זכות אבות, והיינו לפי שע\"י מלאכה ממשיכים בחי' ובטובו מחדש בכל יום תמיד מעשה בראשית, בחי' אוא\"ס שיומשך הדבור בצמצומים רבים שנקרא בשם מלאכה כו', שעי\"ז הוא קיום[ednref_4_ד] העולמות כו'<sup data-n=\"12\">12</sup>. וזהו מ\"ש אחר ויניחהו כו' לעבדה כו' ויצו ה' אלקי' על האדם מכל עץ הגן אכול תאכל, והיינו שע\"י העבודה בבחי' לעבדה ולשמרה עי\"ז ציוה לו לאכול אח\"כ, כי העבודה היא בחי' גבוה. ובזה יובן ג\"כ מ\"ש בפ' שני' דק\"ש ואספת דגנך, שלכאו' מה\"ע ואספת דגנך לק\"ש, אך לפי משנ\"ת לעיל שע\"י המלאכה ממשיכים בחי' חידוש הישינות לכן נאמר זה בק\"ש, אמנם צ\"ל ואספת דגנך שצריך לאסוף ולקבץ כל הבחי' דגנך ותירושך ויצהריך אל בחי' אחד בחי' ביטול, והיינו ע\"י שיהי' אצלינו תורתינו קבע ומלאכתינו עראי<sup data-n=\"13\">13</sup> שהעיקר יהי' בחי' תורה כו' רק שצריך ג\"כ לעשות מלאכה, כי כל תורה שאין עמה מלאכה סופה בטילה כו' וגם כמשנ\"ת לעיל מעלת המלאכה שע\"י מלאכה באמונה ממשיכים חיות העולמות כו'.\n<b>ועוי\"ל</b> טעם מה שגדולה מלאכה, ע\"פ מה שידוע שיש ל\"ט אבות מלאכות, ושורש ענין ל\"ט מלאכות הם כנגד ל\"ט קללות<sup data-n=\"14\">14</sup> שנתקללו נחש וחוה[ednref_5_ה]",[["11","11","<b>חביבה היא המלאכה מזכות אבות כו'</b>: בד\"ה אבות מלאכות בסה\"מ תר\"ל שם נוסף כאן בגוכי\"ק: זכות אבות הצילה ממון, מלאכה הצילה נפשות."],["12","12","<b>שע\"י מלאכה ממשיכים. . שיומשך הדבור בצמצומים רבים. . העולמות כו'</b>: בסה\"מ תר\"ל שם נוסף כאן: והמעלה בזה הוא לפי שנעוץ סופן בתחלתן כו'."],["13","13","<b>ואספת דגנך. . תורתינו קבע ומלאכתינו עראי</b>: ראה בארוכה סה\"מ תרכ\"ו ע' קסט. קעא."],["14","14","<b>ענין ל\"ט מלאכות הם כנגד ל\"ט קללות</b>: ראה בכ\"ז אוה\"ת יתרו שם ע' תתקנד.\n\n[edn_4_ד] <b>שעי\"ז הוא קיום העולמות כו'</b>: בגוכי\"ק נוסף כאן: וצ\"ל לפי שבחי' מל' בחי' שכינתא תתאה נעוץ סופן בתחלתן, לכן חביבה מלאכה מזכות אבות כו', ויש ג\"כ אור חוזר אספקלריא דלא נהרא כמ\"ש בלקו\"ת בשה\"ש ע\"פ הראיני את מראיך [דף יז, ב-ג. יט, א. כ, ב-ג], היינו ההעלאה מבחי' מלאכה כו'.\n\n[edn_5_ה] <b>ל\"ט קללות שנתקללו נחש וחוה</b>: בגוכי\"ק נוסף כאן: ע' ברע\"מ פ' תצא דר\"פ ע\"ב שחשיב ארבעים חסר אחת, כי חשיב תשעה לארץ. ובמד\"ר פ' במדבר פ\"ה ובפ' קרח כ' ארבעים יכנו כנגד מ' קללות, ופחתו חכמים אחת משום לא יוסיף. וע' בזהר פ' נח דס\"א סע\"א [אוצ\"ל: סע\"ב] ארבעים לקבל ד' סטרי עלמא לכל חד עשרה."]]],[2000510072,"ואדם והארץ, וע\"י העבודה באמונה בל\"ט מלאכות מתקנים את בחי' הל\"ט קללות שנתקללו עבור האכילה שלא כהוגן[ednref_6_ו].\nג) <b>אך</b> הנה כ\"ז הוא בחול, שבששת ימי החול העבודה היא בל\"ט מלאכות לתקן כנ\"ל וכמ\"ש רז\"ל לעשות לתקן, וע\"י העבודה באמונה ממשיכי' בחי' חידוש הישינות כנ\"ל. אמנם בשבת נאמר כי בו שבת מכל מלאכתו והיינו שבשבת הוא עליות העולמות שבשבת מאיר הדבור כמו שהוא למעלה בלתי צמצומים והתלבשות כו', בחי' בצלמנו כו', וגם מאיר בשבת מלמעלה מבחי' הדבור, והיינו שהעולמות מקבלים חיות מבחי' המחשבה כו'. אך לפ\"ז צ\"ל מ\"ש זכור את יום השבת<sup data-n=\"15\">15</sup> לקדשו, הלא שבת מקדשא וקיימא, שהרי זהו מטעם כי בו שבת כו' בחי' עליות העולמות כו' ומהו לקדשו כו'. אך הענין הוא דהנה שבת הוא בחי' שבת בראשית, ויש ראשית וראשון, שראשית הוא לשון נוק' שמקבל מבחי' ראשון<sup data-n=\"16\">16</sup> כו' וזהו ע\"י נש\"י שנש\"י ממשיכים בבחי' שבת, וכמארז\"ל במד\"ר בראשית ס\"פ י\"א אמרה שבת לפני הקב\"ה לכולם יש בן זוג ולי אין בן זוג, א\"ל הקב\"ה כנס\"י יהי' בן זוגך. שנש\"י ממשיכים בבחי' שבת, והיינו כי ישראל הם בחי' לי ראש, שממשיכים בבחי' ראשית, דהנה ראש הוא אותיות אשר בחי' תענוג עליון, שממשיכים בחי' התענוג עליון בבחי' שבת שהיא בחי' ראשית חכ', וכמ\"ש וקראת לשבת ענג שממשיכים בחי' ענג עליון בבחי' שבת. וז\"ע שתי שבתות כהלכתן שהם בחי' שבת עילאה ושבת תתאה<sup data-n=\"17\">17</sup>, שבת תתאה היא בחי' שבת בעצם שהוא בחי' שבת בראשית שהעלי' היא מצד עצמו בחי' כי בו שבת כו' שהוא בחי' שביתה מבחי' הדבור דעשרה מאמרות, שהדבור מתעלה למקורו ושרשו, וידוע ששורש הדבור הוא מבחי' חכמה כנודע מענין אבא יסד ברתא, לכן העלי' של הדבור הוא עד בחי' חכמה ראשית ההשתלשלות כו' כמ\"ש במ\"א<sup data-n=\"18\">18</sup>. אמנם בחי' שבת עילאה הוא בחי' שבתא דיומא זהו מה שנש\"י ממשיכים בשבת, שהוא בחי' עלי' היותר גבוה ונעלה וכמ\"ש עולת שבת בשבתו בחי' שבתו של שבת, ששבת גופא עולה למעלה יותר כו'. ודרך כלל יש ג' סעודות ג' בחי' בשבת, וסעודה השלישית הוא בחי' עלי'",[["15","15","<b>אך לפ\"ז צ\"ל מ\"ש זכור את יום השבת</b>: בהבא לקמן עד סוף הפיסקא ראה תו\"א יתרו שם סט, ג ואילך."],["16","16","<b>ויש ראשית וראשון שראשית. . נוק' שמקבל מבחי' ראשון</b>: ראה תו\"א יתרו שם ע, א."],["17","17","<b>וז\"ע שתי שבתות כהלכתן. . שבת עילאה ושבת תתאה</b>: בהבא לקמן עד סוף הפיסקא ראה בארוכה לקו\"ת בהר מא, א. מב, ג ואילך. מג, ד ואילך."],["18","18","<b>ששורש הדבור הוא מבחי' חכ'. . העלי'. . עד בחי' חכ'. . כמ\"ש במ\"א</b>: ראה לקו\"ת במדבר ז, ב.\n\n[edn_6_ו] <b>מתקנים את בחי' הל\"ט קללות. . כהוגן</b>: בגוכי\"ק נוסף כאן: וזהו ג\"כ ענין מה שהי' ל\"ט מלקות, שהם ג\"כ לתקן את בחי' ל\"ט קללות, דע\"י איזה עבירה נעשה לט בחי' לטותא שהוא מבחי' ל\"ט קללות כו', וע\"י המלקות שהיו מכים את החוטא עי\"ז מתקנים את הל\"ט קללות. וכמו\"כ יובן שע\"י היגיעה בזיעת אפיך בבחי' העבודה בל\"ט מלאכות כשהוא עוסק באמונה עי\"ז מתקן את בחי' הל\"ט קללות הנ\"ל כו'."]]],[2000510073,"היותר עליונה שהוא בחי' רעוא דכל רעוין, שז\"ע בחי' מתנה טובה שיש לי בבית גנזי ושבת שמה כו'.\n<b>והנה</b> מה שנש\"י ממשיכים בבחי' שבת זהו ע\"י ששת ימים תעבוד, שמי שטרח בע\"ש יאכל בשבת, והיינו ע\"י שעסק באמונה בששת ימי החול שעי\"ז ממשיך למעלה שיתצמצם בחי' הדבור שנק' בשם מלאכה כנ\"ל שז\"ע בחי' ירידה והמשכה להוות ולהחיות כל מעשה בראשית מאין ליש, הנה ע\"י ירידה זו נעשה אח\"כ העלי' בשבת, כי ירידה זו היא צורך עלי', שע\"י הירידה דחול נעשה העלי' בשבת. וזהו שהמד\"ר מפרש לעבדה הוא בחי' ששת ימים תעבוד, והיינו לפי שששת ימים תעבוד הוא ג\"כ ציווי כמו לעבדה ולשמרה, כי ע\"י ששת ימים תעבוד כו' נעשה אח\"כ בחי' שבת, בחי' כי בו שבת כו'. וז\"ע ג\"כ מ\"ש סולם מוצב ארצה וראשו מגיע השמימה שכמו ע\"י הסולם יש בחי' ירידה ועלי', כמו\"כ בחי' ששת ימים תעבוד הוא בחי' הירידה, ואח\"כ בחי' שבת הוא בחי' העלי' כו'.\nד) <b>אמנם</b> לפי משנ\"ת שגדולה מלאכה שעי\"ז נמשך בחי' חידוש הישינות שיומשך חידוש חיות העולמות כו', א\"כ צלה\"ב מי שאינו יכול לעסוק במלאכה אלא הוא עוסק בתורה, ומאין יומשך על ידו בחי' המשכת חיות העולמות הוא בחי' חידוש הישינות מה שבטובו מחדש בכל יום תמיד מעשה בראשית כו'. אך הענין הוא דהנה תורה נק' ג\"כ מלאכה דכתיב (משלי ך\"ד ך\"ז) הכן בחוץ מלאכתך ועתדה בשדה לך אחר ובנית ביתך, וארז\"ל בסוטה דמ\"ד ע\"א הכן בחוץ מלאכתך זה מקרא, ועתדה בשדה לך זה משנה, אחר ובנית ביתך זה גמרא, נמצא שהתורה נק' ג\"כ בחי' מלאכה. וזהו שהתורה נק' לחם וכמ\"ש לכו לחמו בלחמי, וכמו שהלחם גשמי צריך מתחלה י\"א מלאכות כדחשיב במשנה הזורע והחורש כו' ותנא סדורא דפת נקיט, כמו\"כ יש בחי' אלו בלחם רוחני דתורה כמשנ\"ת במ\"א, ע' בלק\"ת בפ' בהר בד\"ה כי תבואו<sup data-n=\"19\">19</sup> כו' ושבתה פ\"ב ופ\"ג. וענין בחי' העבודה בלחם רוחני דתורה הוא כמארז\"ל ע\"פ ושבתם וראיתם כו' בין עובד אלקי' לאשר לא עבדו, אינו דומה שונה פרקו מאה פעמים לשונה פרקו מאה פעמים ואחד<sup data-n=\"20\">20</sup>, וע' בסש\"ב פט\"ו, שע\"י ששונה פרקו מאה פעמים ואחד שהוא בחי' אתכפיא, נק' עובד אלקים שז\"ע בחי' העבודה, וע\"י בחי' מלאכה זו שבתורה עי\"ז ממשיך למעלה ג\"כ בחי' מלאכה שיומשך בחי' חיות העולמות כו'. ועוד נוסף הוא על בחי' עבודה באמונה, שע\"י בחי' העבודה בחי' מלאכה שבתורה ממשיך מלמעלה הרבה מכמו שנמשך ע\"י סתם מלאכה, דהנה ההמשכה שע\"י בחי' הל\"ט מלאכות עי\"ז ממשיך שיהי' בבחי' העלם והסתר, והיינו שיתצמצם הדבור שזהו נק' מלאכה בכדי להוות ולהחיות עולמות הנפרדים כו'. אמנם ע\"י בחי' מלאכה שבתורה עי\"ז ממשיך בחי' גילוי אוא\"ס ב\"ה",[["19","19","<b>כמשנ\"ת במ\"א, ע' בלק\"ת בפ' בהר בד\"ה כי תבואו</b>: דף מ, ב ואילך. וראה גם סה\"מ תרל\"ג ח\"א ע' רפז ואילך."],["20","20","<b>כמארז\"ל ע\"פ ושבתם וראיתם. . מאה פעמים ואחד</b>: ראה בכ\"ז בארוכה (נוסף לתניא פט\"ו) סה\"מ תרל\"ב ח\"ב ע' תקצז. וראה גם אוה\"ת נ\"ך ע' תקלב-ג."]]],[2000510074,"הוא בחי' זה הדבר כנ\"ל גבי משה נתנבא בזה. וע\"ד כמו מלאכת המשכן, שבמשכן הי' כל הל\"ט מלאכות, כי כל המלאכות נלמד ממלאכת המשכן, ובמלאכת המשכן הי' השראת השכינה כמ\"ש ושכנתי בתוכם, וכן משה אמר ויהי נועם כו' יהי רצון שתשרה שכינה במעשה ידיכם. ועד\"ז יובן בענין בחי' מלאכה שבתורה שהיא גבוה יותר מבחי' מלאכה דששת ימי החול כו' שע\"י מלאכה שבתורה נמשך גילוי אלקות כו' בחי' זה הדבר כו'. ולכן אמרז\"ל משחרב בהמ\"ק אין להקב\"ה בעולמו אלא ד' אמות של הלכה, וזהו שאמרו במשנה סוף קדושין ר' נהוראי אומר מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה, והיינו הגם שהמלאכה היא בחי' גדולה וכמו שא' שמעי' אהוב את המלאכה, מ\"מ איני מלמד את בני אלא תורה, מפני כי מלאכתו של תורה הוא יותר נעלה הרבה משארי מלאכות גם כשהם באמונה ובכשרות כו', והוא מטעם הנ\"ל שע\"י מלאכה שבתורה נמשך בחי' גילוי אלקות להיות בבחי' זה הדבר כו'<sup data-n=\"21\">21</sup>.\nה) <b>ומעתה</b> יובן ג\"כ ענין מה שארז\"ל במשנה אבות כו' ארבעים חסר א'<sup data-n=\"22\">22</sup> ולא אמרו ל\"ט מלאכות, וגם מפני מה לא נאסרו ארבעים מלאכות שהרי יש ארבעים פעמים מלאכה בתורה כו'. והענין הוא דהגם שיש מ\"ם פעמים מלאכה בתורה מ\"מ לא נאסרו כ\"א ל\"ט, כי מלאכה אחת יש שמותרת בשבת, וכמארז\"ל במד\"ר בראשית ס\"פ י\"א כי בו שבת מכל מלאכתו, ממלאכת עולמו שבת, אבל לא שבת לא ממלאכת הצדיקים<sup data-n=\"23\">23</sup> ולא כו' אלא פועל עם אלו ועם אלו כו' ומנין ששכרן של צדיקים קרוי' מלאכה שנאמר מה רב טובך אשר צפנת ליריאך פעלת לחוסים בך כו'. נמצא שיש מלאכה שמותרת גם בשבת, והיינו ע\"ד שהאכילה מותרת בשבת, הגם שהאכילה היא ג\"כ בירור, מ\"מ מותרת האכילה בשבת מפני שהיא ע\"ד צדיק אוכל לשובע נפשו<sup data-n=\"24\">24</sup>, והמאכל מתעלה ע\"ד אתהפכא, ע' מזה בד\"ה וידבר כו' ראשי המטות (למ\"ד<sup data-n=\"25\">25</sup>). ועד\"ז יובן ענין המלאכה שמותרת בשבת שהוא בחי' שכר הצדיקים פעלת לחוסים בך, שהוא בחי' עדן בחי' עין לא ראתה כו' יעשה למחכה לו, שזהו ג\"כ בחי' מעשה, בחי' מלאכה, אך מלאכה זו מותרת בשבת שלא שבת ממנה כו'. וזהו שאמרו במשנה ארבעים מלאכות לפי שבאמת יש ארבעים מלאכות, אך מ\"מ חסר אחת היינו בחי' מלאכה אחת שלא נאסרה מטעם הנ\"ל, וזהו חסר אחת היינו",[["21","21","<b>זה הדבר כו'</b>: בגוכי\"ק נרשם כאן בצידי הגליון: ”עד כאן\" — וכנראה ר\"ל שעד כאן נמצא בד\"ה במשנה כו' מניח אני כל אומנות בסה\"מ תרמ\"א."],["22","22","<b>ומעתה יובן. . אבות כו' ארבעים חסר א'</b>: בהבא לקמן ראה אוה\"ת בראשית שם תנח, א. ויקהל ע' ב'פט-צ. סה\"מ עת\"ר ע' רב. ס' השיחות תשמ\"ט ח\"א ע' 318. ח\"ב ע' 566 ואילך. תש\"נ ח\"ב ע' 644."],["23","23","<b>וכמארז\"ל במד\"ר. . לא שבת לא ממלאכת הצדיקים</b>: בהבא לקמן ראה גם יהל אור לתהלים ע' קטז."],["24","24","<b>האכילה בשבת. . ע\"ד צדיק אוכל לשובע נפשו</b>: ראה בארוכה תו\"א חיי שרה טו, ג-ד. סידור עם דא\"ח רג, א ואילך. סה\"מ תקס\"ה ע' קנ. דרך מצותיך צ, א. צ, ב ואילך. המשך תרס\"ו ע' קנד."],["25","25","<b>בד\"ה וידבר כו' ראשי המטות (למ\"ד)</b>: סה\"מ תר\"ל ע' רכ. וע' רכו."]]],[2000510075,"בחי' אחת היא יונתי<sup data-n=\"26\">26</sup> היא כנס\"י בן זוג דשבת כנ\"ל שנש\"י ממשיכים בבחי' שבת בראשית מבחי' ראשון כו' שמלאכה זו מותרת בשבת, שז\"ע מ\"ש וקראת לשבת עונג<sup data-n=\"27\">27</sup> המשכת בחי' עדן בחי' תענוג בשבת כו', ולמעלה ג\"כ לא שבת מזו, כ\"א פועל עם אלו כו' שז\"ע פעלת לחוסים בך ונמשך מבחי' צפנת בגימ' כתר<sup data-n=\"28\">28</sup> כו'.\nוא\"ו) <b>ועפ\"ז</b> יובן ג\"כ מה שלא נאסר מן התורה כ\"א מלאכה ממש ולא דבור, רק מדרבנן אסור דבור ג\"כ, שלכאורה הלא בדבר ה' שמים נעשו כנ\"ל. אך הענין דהן אמת שבדבר ה' ובעשרה מאמרות נברא העולם, אך זהו כמו שנתצמצם הדבור בריבוי צמצומים בצמצום אחר צמצום שבחי' זו נק' בכתוב בשם מלאכה, וביום השביעי שבת מכל מלאכתו לכן נאסר למטה מלאכה ולא דבור כי מבחי' הדבור כמו שהוא למעלה לא שבת מזה כלל כ\"א מבחי' הדבור המצומצם כו'. ולכן מן התורה מותר דבור האדם ואינו אסור רק מלאכה, אך מדרבנן אסרו ג\"כ הדבור של האדם, מפני שמ\"מ מבחי' הדבור כמו שהוא למעלה בבחי' הצמצום שבת ממנו[ednref_7_ז], והגם שכינו אותו בכתוב בשם מלאכה ועשי' מ\"מ הוא בחי' דבור כו', לכן אסרו גם דבור האדם שלמטה ג\"כ כו'[ednref_8_ח].\n<b>ובזה</b> יובן ג\"כ מ\"ש ואני אתנהלה<sup data-n=\"29\">29</sup> לאטי כו' כי הנה לאט הוא בגימ' ארבעים, וכתי' את מי השילוח ההולכים לאט, ולמדו מזה שמי מקוה הם ארבעים סאה<sup data-n=\"30\">30</sup>, ואיתא במשנה סוף יומא מקוה ישראל ה' מה מקוה מטהר את הטמאים כך הקב\"ה מטהר את ישראל, ועיקר הטהרה היא ביוהכ\"פ כמ\"ש כי ביום הזה כו' לפני ה' תטהרו, ויוהכ\"פ הוא יום הארבעים מחדש אלול, שהם מ\"ם ימים ימי רצון שהי' משה בהר לקבל לוחות האחרונות כמארז\"ל מה הראשונים ברצון כו', ולכן יוהכ\"פ מטהר",[["26","26","<b>וזהו חסר אחת היינו בחי' אחת היא יונתי</b>: ראה אוה\"ת בראשית שם תנח, סע\"א."],["27","27","<b>וקראת לשבת עונג</b>: ראה לקו\"ת שמע\"צ כג, ד. דרך מצותיך צ, א שם."],["28","28","<b>צפנת בגימ' כתר</b>: ראה גם יהל אור לתהלים שם. סה\"מ קונטרסים ח\"ג ע' לב. וש\"נ."],["29","29","<b>ובזה יובן ג\"כ מ\"ש ואני אתנהלה</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת בראשית שם תנז, א."],["30","30","<b>מי השילוח ההולכים לאט ולמדו מזה שמי מקוה הם ארבעים סאה</b>: ראה במדב\"ר פי\"ח, כא הובא באוה\"ת בראשית שם.\n\n[edn_7_ז] <b>מדרבנן אסרו ג\"כ הדבור. . הדבור. . למעלה בבחי' הצמצום שבת ממנו</b>: בצידי הגליון נרשם בגוכי\"ק: גם שורש דבור המצומצם הוא מבחי' דבור כמו שהוא למעלה בלתי צמצום ששם נק' דבור ולא מלאכה, ולכן גם מהאי טעמא שייך גזירה דרבנן לאסור דבור האדם.\n\n[edn_8_ח] <b>לכן אסור גם דבור האדם שלמטה ג\"כ כו'</b>: בגוכי\"ק נוסף כאן הגה\"ה: וי\"ל שהדבור של האדם נלקח מב' בחי' בצלמנו כדמותנו, כדמותנו הוא בחי' דבור המצומצם ששבת מבחי' זו, ובצלמנו הוא בחי' הדבור כמו שהוא למעלה שלא שבת מזה. לכן מן התורה מותר הדבור של האדם מפני כי יש בו ג\"כ בחי' בצלמנו כו'. אבל מדרבנן אסרוהו מפני בחי' כדמותנו שבדבור האדם שנלקח גם מבחי' דבור המצומצם כו', ובפרט בדורות האחרונים כו', וצ\"ע."]]],[2000510076,"שהוא יום הארבעים כמו מי מקוה ארבעים סאה מטהרים כו' כמו\"כ יוהכ\"פ מטהר. אך הנה כמו שבשבת צ\"ל מי שטרח מע\"ש, שדוקא מי שטרח בע\"ש יאכל בשבת שז\"ע בחי' ששת ימים תעבוד בחי' העבודה בל\"ט מלאכות לעשות לתקן כו', כמו\"כ ביוהכ\"פ שהוא בחי' שבת שבתון צ\"ל ג\"כ ל\"ט ימים קודם, שז\"ע ל\"ט ימים שמר\"ח אלול עד יוהכ\"פ ע\"ד ל\"ט מלאכות, ועי\"ז אח\"כ יוהכ\"פ יום הארבעים הוא בחי' רגל המלאכה היא בחי' המלאכה שמותרת בשבת, שמותרת גם ביוהכ\"פ בחי' שבת שבתון כו' שזהו בחי' החסר אחת שאמרו במשנה כו'. ולכן מר\"ח אלול מתחילין לבקש את בחי' האחת, שזהו מה שמתחילין לאמר מר\"ח אלול אחת שאלתי כו', עד שביוהכ\"פ מאיר ומתגלה בחי' האחת, ולכן המנינים דיוהכ\"פ מתחילין באחת כמו שאנו אומרים ביוהכ\"פ וכך הי' מונה אחת, אחת ואחת, אחת כו', והיינו שביוהכ\"פ בחי' שבת שבתון מאיר בחי' המלאכה שחסר אחת שמותרת בשבת מארת ביוהכ\"פ בגילוי להיותו בחי' שבת שבתון כו', וזהו לאטי לרגל המלאכה, לאט הוא בחי' יוהכ\"פ יום הארבעים בחי' גילוי מלאכה אחת כו', וזהו עד אשר אבוא כו' שעירה, פי' שעירה קאי על השעיר המשתלח שהוא גמר הכפרה וכמארז\"ל בפ\"א דשבועות ועל שאר עבירות שבתורה הקלות והחמורות הזדונות והשגגות כו' שעיר המשתלח מכפר[ednref_9_ט].\nבגוכתי\"ק נרשם בשולי העמוד:\n<b>לאטי</b> עולה חמשים י\"ל מן הפסח עד חג השבועות קבלת התורה מדריגת צדיקים לוחות ראשונות, וכשחטאו ניתן לוחות אחרונות ביוהכ\"פ, יום הארבעים מר\"ח אלול, לאט מקוה לטהר, עצומו של יום מכפר, והגם כי לוחות אחרונות הם כפליים שיש בהם מדרש הלכות והגדות, מ\"מ אלמלא לא נשתברו הלוחות לא הי' שכחה שנמשך מבחי' אחוריים כ\"א הי' מאיר מוח הזכרון שהוא חכ' כמ\"ש בפ' קדש ולזכרון בין כו', וזהו לאטי בתוס' יו\"ד על לאט.",[["","","[edn_9_ט] <b>שעיר המשתלח מכפר</b>: בכת\"י ממשיך כאן עוד קטע [ואח\"כ נרשם ע\"ז בגוכתי\"ק שא\"צ להעתיקו]:\nועד\"ז יש לפרש שקאי על לע\"ל כי לע\"ל יהי' יום שכולו שבת כו' בחי' אלף השביעי, שנק' יום שכולו שבת ומנוחה לחיי העולמים, וכדי להגיע לבחי' יום שכולו שבת כו' זהו ע\"י אתנהלה לאטי לרגל המלאכה שהוא בחי' זמן הגלות, שאז הוא זמן הבירור של ל\"ט מלאכות בבחי' הבירורי' דרפ\"ח ניצוצין שנפלו בשבה\"כ, וע\"י הבירור דרפ\"ח ניצוצין דתהו יהי' אח\"כ בחי' גילוי שבת בחי' אלף השביעי הוא בחי' עדן, מה שעין לא ראתה כו' יעשה למחכה לו בחי' המלאכה שמותרת בשבת שזהו מה שנמנה במשנה בבחי' חסר אחת כו', ונמצא כי יש ג' בחי' בענין האחת שחסר, היינו שבשבת מאיר הארה מבחי' אחת היא יונתי שממשיכים בחי' עונג בשבת, ועי\"ז נמשך שפועל עם הצדיקים שנמשך הארה מבחי' צפנת בחי' הכתר בשבת וי\"ל שז\"ע המתנה טובה כו', וביוהכ\"פ שהוא שבת שבתון מאיר יותר שלכן מונין אחת ואחת כו' ועיקר הגילוי יהי' לע\"ל שיהי' יום שכולו שבת ומנוחה לחיי העולמים."]]],[2000510077,"<h3>והי' הנשאר בציון כו'</h3>\n<b>בס\"ד. (ש\"פ נח, ל\"א).</b>\n<b>והי'</b> הנשאר בציון<sup data-n=\"31\">1</sup> והנותר בירושלים קדוש יאמר לו, וארז\"ל עתידין צדיקים שיאמרו לפניהם קדוש, ויש להבין מ\"ש והי' הנשאר בציון והנותר בירושלים, הלא רוב ישראל הם בחו\"ל ואיך נאמר הנשאר בציון דוקא.\n<b>אך</b> הנה יובן בהקדים ענין חטא דור הפלגה שבנו העיר והמגדל שנאמר ע\"ז וירד ה' לראות את העיר ואת המגדל אשר בנו בני האדם, מה הי' ענין המגדל, ולמה גדלה חטאתם עד מאד עד שאין להם חלק לעוה\"ב כמשי\"ת. אך הנה מתחלה כתיב ויהי כל הארץ שפה אחת ודברים אחדים וארז\"ל במד\"ר פל\"ח ודברים אחדים שאמרו דברים חדים על שני אחדים על הוי' אחד ועל אחד הי' אברהם. וצ\"ל מהו ענין השייכות מה שדברו דברים חדים על ב' אחדים להעיר ומגדל אשר בנו. אך הענין הוא דהנה ידוע שכל ההמשכות הנמשכות בקדושה למטה שיהי' דירה בתחתונים הוא ע\"י בחי' עיר ומגדל שזהו מ\"ש גדול הוי' ומהולל מאד בעיר אלקינו, והיינו שהעיר היא בחי' ירושלים שנק' עיר אלקינו והמגדל היא בחי' בהמ\"ק וכמ\"ש כמגדל דוד צוארך שקאי על בהמ\"ק<sup data-n=\"32\">2</sup>. ובדרך פרט הנה המגדל הוא בחי' ציון בחי' קדה\"ק שזהו מ\"ש בישעי' כרם הי' לידידי בקרן בן שמן כו' ויבן מגדל בתוכו וגם יקב חצב בו, ויבן מגדל בתוכו הוא בחי' קדה\"ק, וגם יקב חצב בו קאי על השיתין שהיו מנסכים את היין, והיינו שבבהמ\"ק הי' נמשך בחי' המשכת גילוי אלקות דירה בתחתונים, ובהמ\"ק נק' מגדל, הנה נת' שההמשכה שבקדושה הוא ע\"י עיר ומגדל. וז\"ש מגדל עוז שם הוי' בו ירוץ צדיק ונשגב, וז\"ש בילקוט תהלים רמז תש\"ג בשם מדרש תנחומא שאמר להם אברהם כשבנו את המגדל הנחתם מגדל עוז שם ה' ואתם בונים המגדל. אך הנה בחי' עיר ומגדל זה נמשך ע\"י בחי' ביטול דוקא וכמשי\"ת. אכן דור הפלגה לא רצו בזה כלל שרצו לילך בשרירות לבם הרע וכמ\"ש ויאמרו לאל סור ממנו ודעת דרכיך לא חפצנו, שקאי על דור המבול ודור הפלגה (שהם בחי' א' כמ\"ש במ\"א)<sup data-n=\"33\">3</sup>, ואעפי\"כ רצו שיומשך להם ההשפעה בגשמיות, לזה בנו את העיר ואת המגדל שהוא לעומת העיר והמגדל דקדושה, ולזה גדלה חטאתם עד מאד כי רצו להרוס את הבנין דקדושה ולהוסיף כח בסט\"א, וזהו בד\"כ חטא של דור הפלגה.",[["31","1","<b>והי' הנשאר בציון</b>: מאמר זה מיוסד על ד\"ה ויהי כל הארץ באוה\"ת נח (כרך ג) תרנד, סע\"א ואילך. ובשינויים בכת\"י 1063 טז, א. המאמר (דתרל\"א) נדפס גם באוה\"ת נ\"ך (כרך ג) ע' א'קצו.\nחלק מהמאמר (פרקים א-ד) נמצא עם שינויים והוספות לקמן ד\"ה במד\"ר כו' ויראו את אלקי ישראל ע' קעב ואילך. [וראה בהנסמן שם]. ונמצא בתוס' ביאור בד\"ה והי' הנשאר תרצ\"א בסה\"מ קונטרסים ח\"א קלט, ב ואילך. התחלת המאמר נמצא בתוס' הגהות בסה\"מ תרס\"ב ע' רמא [ד\"ה ויהי כל הארץ]. ובשלימות שם בהוספות ע' שעא.\nלעניני המאמר ראה אוה\"ת נח שם תרסח, א-ב [ד\"ה הבה נרדה]. נ\"ך (כרך ב) ע' א'טז [ד\"ה מגדל עוז]. סה\"מ תר\"ל ע' ד ואילך. תרמ\"ג ע' ג ואילך. תרפ\"ו ע' פז. — להתחלת וסיום המאמר ראה ד\"ה והי' הנשאר באוה\"ת נ\"ך (כרך ב) ע' תשסא ואילך."],["32","2","<b>כמגדל דוד צוארך שקאי על ביהמ\"ק</b>: ראה בארוכה סה\"מ תר\"ל ע' כד ואילך."],["33","3","<b>דור המבול ודור הפלגה (שהם בחי' א' כמ\"ש במ\"א)</b>: ראה אוה\"ת נח (כרך ג) תרסא, א."]]],[2000510078,"<b>וביאור</b> הענין הוא דהנה כתיב גדול הוי' כו' בעיר אלקינו<sup data-n=\"34\">4</sup>, פי' עיר אלקינו כי נודע ממ\"ש בס\"י שתי אבנים בונות<sup data-n=\"35\">5</sup> שתי בתים שלשה אבנים בונות ששה בתים כו' מכאן ואילך צא וחשוב עד אין שיעור, והיינו שכמו שמקיבוץ אבנים הרבה נעשה ונבנה הבית ובהקבץ הרבה בתים נעשה עיר, ככה יובן למעלה שהאבנים הם בחי' אותיות המחיים ומהווים את כל העולמות הנבראים כי בדבר ה' שמים נעשו שכל הנבראים עליונים ותחתונים נבראו מבחי' דבר ה' וכמשארז\"ל בעשרה מאמרות נברא העולם. והנה אנו רואים שיש למטה בדצח\"מ הרבה נבראים עד אין קץ ושיעור<sup data-n=\"36\">6</sup>, ופעם כתי' מה רבו מעשיך ה' שיש ריבוי התהוות נבראים עד אין שיעור ופעם כתי' מה גדלו<sup data-n=\"37\">7</sup> מעשיך ה', פי' מה גדלו קאי על נבראים גדולים כמו מלאכים, כי המלאכי' נבראו ג\"כ מבחי' הדבור, ויש ריבוי בחי' מלאכים שזהו שאמר הכתוב אלף אלפי' ישמשוני' ורבוא רבבן קדמוהי יקומון, וארז\"ל שכ\"ז מספר גדוד א' אבל לגדודיו אין מספר, וכולם מקבלים חיותם מבחי' דבר הוי'<sup data-n=\"38\">8</sup> המחי' אותם, וזהו בחי' עיר אלקינו שפי' עיר הוא בחי' כללות עולם הדבור, שכמו שהעיר הוא מכמה בתים ובית הוא מקיבוץ הרבה אבנים כמו\"כ בבחי' עיר אלקינו שהוא כללות עולם הדבור יש הרבה צירופי אותיות שעי\"ז נמשך החיות לכל נברא להחיותו כי כל נברא יש לו צירוף בפ\"ע המחי' אותו. וזהו בחי' עיר אלקינו ששרש בחי' האותיות נמשך מבחי' שם אלקי', וזהו שאלקי' נק' ל' רבים והיינו לפי שמשם אלקי' נמשך בחי' הריבוי וההתחלקות בבחי' הרבה צירופי אותיות כו'. והמגדל הוא בחי' גדול הוי' ומהולל מאד בעיר אלקינו שזה מ\"ש כולם בחכ' עשית כי הוי' בחכ', והנה הוי' נק' ה' אחד שאין שם בחי' ריבוי והתחלקות כלל, רק כשנמשך שם הוי' בבחי' שם אלקים אז נעשה הריבוי וההתחלקות, וכמו שאנו רואין למטה ששכל א' שהוא רק בחי' נקודה א', וכשנמשך השכל למטה בבחי' צירופי אותיות נעשה מזה הרבה צירופי אותיות כו', וכך הוי' אחד כו' אך כשנמשך בבחי' שם אלקי' נעשה בחי' ריבוי והתחלקות. אך הנה כתי' כי הוי' הוא האלקי' שכולא חד שהריבוי וההתחלקות נמשך משם הוי' שהוא אחדות פשוטה ממש וכנ\"ל, וזהו ענין עיר ומגדל דקדושה.\nב) <b>אך</b> הנה איך ימשיכו בחי' עיר ומגדל זה, זהו ע\"י שיש בנפש ג\"כ בחי' עיר ומגדל, דהנה כתי' ואשים דברי בפיך ובצל ידי כסיתיך לנטוע שמים",[["34","4","<b>והמגדל הוא בחי' גדול הוי'. . בעיר אלקינו</b>: ראה אוה\"ת נח שם תרנה, א: ההמשכה להחיות העולמות זהו\"ע העיר שנק' עיר אלקינו, והמשכה הפנימית בהעיר זהו\"ע המגדל שנק' כן ע\"ש גדול הוי' כו' בעיר אלקינו."],["35","5","<b>פי' עיר אלקינו. . שתי אבנים בונות</b>: ראה בכ\"ז תו\"א ויצא כא, ב. וארא נו, סע\"ב."],["36","6","<b>בדצח\"מ הרבה נבראים עד אין קץ ושיעור</b>: ראה בארוכה סה\"מ תרכ\"ז (הוצאת תש\"ס) ע' תטז ואילך."],["37","7","<b>כתי' מה רבו. . ופעם כתי' מה גדלו</b>: בהבא לקמן ראה תו\"א וארא שם נו, ב. סה\"מ תרכ\"ו ע' קה. ועוד."],["38","8","<b>וביאור הענין הוא דהנה כתי' גדול הוי'</b>: בהבא לקמן (עד פיסקא: וזהו והי' הנשאר בציון) ראה אוה\"ת נח שם תרנה, א-ב. וראה גם שם תרסג, ב. שם (כרך ו) תתרע, א-ב. שם (כרך ז) תתשעה, ב ואילך. נ\"ך (כרך א) ע' קמה ואילך."]]],[2000510079,"וליסוד ארץ ולאמר לציון עמי אתה<sup data-n=\"39\">9</sup>, וארז\"ל בירושלמי חזרנו על כל המקרא ולא מצינו שנק' ישראל בשם ציון אלא בפסוק זה, והיינו כי בפסוק זה נאמר תחלה ואשים דברי בפיך ובצל ידי כסיתיך כו', ואשים דברי בפיך הוא בחי' תורה שהוא בחי' דבר הוי' וכמ\"ש ודברי אשר שמתי בפיך, ופי' דברי בפיך היינו שהתורה נמשכה בבחי' פנימיות ממש וכמ\"ש ותורתך בתוך מעי. ובצל ידי כסיתיך הוא בחי' מצות ועי\"ז נמשך מקיפים עליונים וכמ\"ש ה' צילך על יד ימינך, על יד ימינך הוא בחי' מצות, ועי\"ז נמשך ה' צילך בחי' מקיפים שהוא בחי' צילא דמהימנותא, וזהו\"ע צל סוכה<sup data-n=\"40\">10</sup> וכמ\"ש וסוכה תהי' לצל יומם כו', ועד\"ז בשאר כל המצות. לנטוע שמים וליסוד ארץ הוא בחי' עבודת הקרבנות וכמשארז\"ל אלמלא מעמדות לא נתקיימו שמים וארץ<sup data-n=\"41\">11</sup>, ומפני כי בפסוק זה נאמר ג' דברים שהם בחי' תורה ועבודה וגמ\"ח שהם בחי' ג' קוין, לכן נק' אז כנס\"י בשם ציון, כי פי' ציון הוא מלשון ציון וסימן שהוא בחי' בצלמנו כדמותנו<sup data-n=\"42\">12</sup> בצלם אלקים עשה את האדם, והיינו כי על הכסא דמות כמראה אדם, פי' בחי' אדם הוא בחי' רמ\"ח פקודין רמ\"ח אברים דמלכא שהוא בחי' מצות, וכן תורה נק' אדם וכמ\"ש זאת התורה אדם, וכשישראל מקיימין תורה ומצות שהם הג' קוין שנת' בפסוק זה היינו תורה ועבודה וגמ\"ח, אזי נק' בשם ציון שהוא בחי' מגדל שיש בנפש, ועי\"ז הם ממשיכים בחי' ציון שהוא בחי' מגדל הנ\"ל. וזהו שארז\"ל נשבע הקב\"ה שלא יכנס בירושלים של מעלה עד שיכנס בירושלים של מטה כו', כי ע\"י בחי' ירושלים של מטה עושים בחי' ירושלים של מעלה.\n<b>וזהו</b> והי' הנשאר בציון, פי' הגם שהוא בחוץ לארץ עכ\"ז הוא אוחז בציון, דהיינו שמקיים תורה ומצות בחי' ואשים דברי בפיך כו' כנ\"ל, ועי\"ז הוא ממשיך בחי' ציון, וכן הנותר בירושלים שהיא בחי' יראה שלם כו' קדוש יאמר לו, והיינו שכמו שאומרים המלאכים לפני הוי' קדוש דהיינו איך שהוא מובדל כך יאמרו לפני הצדיקים קדוש, לפי שהם בחי' ציון וסימן לאדם העליון בצלמנו כו' שזהו בחי' שם הוי', וכמ\"ש ועל הכסא דמות כמראה אדם הוא מראה כבוד הוי' כו'.\n<b>אמנם</b> הנה דור הפלגה לא רצו<sup data-n=\"43\">13</sup> בקיום המצות, ולא רצו לילך בדרכי השי\"ת כ\"א לילך בשרירות לבם הרע, שזהו שא' הכתוב ויאמרו לאל סור ממנו ודעת דרכיך שהם דרכי הוי' בחי' תומ\"צ, לא חפצנו, והיינו מפני כי לקיום המצות צ\"ל בחי' ביטול והם לא רצו בבחי' ביטול כ\"א שיהי' בבחי' נפרד, אכן הנה ידעו",[["39","9","<b>דהנה כתי' ואשים דברי בפיך. . ולאמר לציון עמי אתה</b>: בהבא לקמן ראה בארוכה אוה\"ת ויצא ריג, ב ואילך. דברים ע' לו ואילך. שם (כרך ו) ע' ב'תקצז ואילך. נ\"ך (כרך ג) ע' א'קפז ואילך."],["40","10","<b>בחי' מקיפים. . צילא דמהימנותא וזהו\"ע צל סוכה</b>: ראה מאמרי אדה\"ז הקצרים ע' תקטו. נביאים ע' פא. סה\"מ תרל\"ב ח\"ב ע' תקכו. וש\"נ."],["41","11","<b>וכמשארז\"ל אלמלא מעמדות לא נתקיימו שמים וארץ</b>: ראה בארוכה לקמן ח\"ב ד\"ה אלמלא מעמדות דש\"פ פנחס תרל\"א."],["42","12","<b>מלשון ציון וסימן שהוא בחי' בצלמנו כדמותנו</b>: ראה לעיל ד\"ה ויקח ה' אלקים פ\"א."],["43","13","<b>אמנם הנה דור הפלגה לא רצו</b>: בהבא לקמן (עד סופ\"ג) ראה אוה\"ת נח שם תרנז, א-ב. וראה גם שם תרסב, ב ואילך. שם (כרך ו) תתרסו, ב ואילך. סה\"מ תרכ\"ו ע' קיח."]]],[2000510080,"שהמשכות והשפעות בקדושה נמשך ע\"י עיר ומגדל דוקא, כי היו חכמים להרע, לכן בנו העיר והמגדל דלעו\"ז ורצו להרוס בנין העיר ומגדל דקדושה. וזהו וימצאו בקעה בארץ שנער, הנה בקעה זה הוא לעומת א\"י שכתי' בה לה' הארץ ומלואה, לכן הי' בהמ\"ק בא\"י דוקא, אבל בחי' בקעה זו הוא בחי' ההיפוך ממש בחי' סט\"א מל' דקליפה, והוא כמו שמדבר הוא לעו\"ז נגד א\"י שנק' מדבר העמים, כמו\"כ בחי' בקעה זו הוא היפך מבחי' א\"י. וזהו וימצאו בקעה שמצאו מקום הנפרד כו' ובנו שם העיר ומגדל. ותהי להם הלבינה לאבן, כי הנה ארז\"ל וכי יש אבנים בבבל כי אבנים הם בא\"י דוקא וכמ\"ש ארץ אשר אבניה ברזל, משא\"כ בבבל שאין שם אבנים, וזהו ותהי להם הלבינה לאבן והיינו כי בחי' אבן הוא מדרגה גבוה שהאבן היא בריאה בידי שמים ולכך האבנים הם חזקי' מאד, משא\"כ לבינה שהיא בריאה בידי אדם, וזהו מ\"ש משם רועה אבן ישראל, אבן דוקא, ונק' אבן בוחן כו', והיינו כי אבן הוא בחי' אותיות אל\"ף ב\"ן<sup data-n=\"44\">14</sup>, שזהו ענין אדם ובהמה, כי ב\"ן בגימ' בהמה, ואל\"ף הוא בחי' אדם, והיינו שיש בחי' ביטול האל\"ף שהוא בחי' ביטול דאדם שהוא בחי' מ\"ה, ויש בחי' ב\"ן שהוא בחי' ביטול דמלאכים שנק' בשם בהמות וחיות שהוא בחי' ביטול היש. והנה יש מעלה בביטול האדם נגד הבהמה ויש מעלה בביטול דבהמה<sup data-n=\"45\">15</sup> נגד האדם, והיינו כי ביטול דאדם הוא עפ\"י השגה וטו\"ד משא\"כ ביטול דבהמה, אכן יש מעלה בביטול הבהמה שהוא בחוזק יותר, לכן כתי' אדם ובהמה תושיע ה' וארז\"ל אלו בנ\"א שהם ערומי' בדעת כאדם ומשימים עצמן כבהמה ואז תושיע הוי', והיינו לפי שאז יש בהם ב' המעלות, וז\"ש ואני תמיד עמך בהמות הייתי עמך, שעמך הוא בחי' בהמות דוקא בחי' ביטול שלמעלה מטו\"ד<sup data-n=\"46\">16</sup> והשגה שעי\"ז דוקא הוא אני תמיד עמך כו', וזהו בחי' אבן שהוא בחי' הביטול דאדם ובהמה.\nג) <b>אך</b> דור הפלגה לא רצו בבחי' ביטול כנ\"ל, וזהו ותהי להם הלבינה לאבן שתמורת האבן שהוא מל' דקדושה עשו הלבינה שהיא בחי' מל' דקליפה, וזשארז\"ל זקף לבינה והשתחווה לה. וביאור ענין ותהי להם הלבינה לאבן, הנה נודע שבקדושה עשר ולא תשע עשר ולא אחד עשר, אך הנה בקליפות הם אחד עשר שזהו אחד עשר סממני הקטורת שהיו במקדש כנגד אחד עשר כתרין דמסאבותא<sup data-n=\"47\">17</sup>, והיינו מפני כי בע\"ס דקדושה הנה האור והחיות הנמשך מאא\"ס ב\"ה להע\"ס הוא מאיר בתוך הע\"ס ומתלבש בהם בבחי' פנימי' ממש ולכן הם עשר ולא יותר כי האור נתאחד עם הכלי ממש כו', אך בקליפות הם י\"א והיינו כי החיות",[["44","14","<b>וזהו מ\"ש משם רועה אבן ישראל. . אותיות אל\"ף ב\"ן</b>: ראה לקו\"ת ראה כז, ב. לקמן ד\"ה במד\"ר כו' ויראו את אלקי ישראל."],["45","15","<b>יש מעלה בביטול האדם. . ויש מעלה בביטול דבהמה</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשלג ואילך. סה\"מ תרל\"ב ח\"ב ע' תמח ואילך. וע' תקסא ואילך."],["46","16","<b>וז\"ש ואני תמיד עמך בהמות הייתי עמך. . שלמעלה מטו\"ד</b>: ראה בכ\"ז תניא פמ\"ו (סו, סע\"א)."],["47","17","<b>נודע שבקדושה עשר ולא תשע. . אחד עשר סממני הקטורת. . כנגד. . כתרין דמסאבותא</b>: בהבא לקמן ראה בארוכה תו\"א תולדות כ, סע\"ב ואילך. וראה גם סה\"מ מלוקט ח\"ב ע' קכג ואילך. ח\"ד ע' סד ואילך."]]],[2000510081,"שנמשך להם מהקדושה אינו מתלבש בהם בבחי' פנימי' כ\"א ע\"י מקיף להחיותם, וע\"כ הם אחד עשר כי הם שני דברים, שהאור והחיות הנמשך להם הוא בחי' בפ\"ע לפי שאינו מתלבש בהם כלל, וזהו\"ע המקיף דלבונה, וזהו ותהי להם הלבינה לאבן היינו שרצו לקבל חיות רק מבחי' מקיף דלבונה, כי לקבל חיות מהקדושה שנמשך בבחי' פנימי' א\"א לקבל כ\"א ע\"י ביטול, לכך רצו יותר לקבל רק מבחי' מקיף דלבונה, שהמקיף יכול להחיות גם לקליפות שהם נפרדים כו'. וזהו ע\"ד שאנו רואים באותיות, שיש בחי' אותיות שהם נמשכים בבחי' פנימי' ממש להחיותם וכמו בדבר ה' שמים נעשו שהאותיות מתלבשים בבחי' אור פנימי ממש, ויש בחי' אותיות שאינם מתלבשים בבחי' פנימיות כ\"א רק בבחי' מקיף לבד ואעפ\"כ הם מחיים ומהווים, כמו עד\"מ שמוש השמות והשבעת האותיות שהיו יכולים בדורות הקודמים להשביע השמות שמשביע בשם פלוני ומלאך פלוני שיהי' הדבר ההוא והי' נעשה כך תיכף ומיד<sup data-n=\"48\">18</sup>, ואעפ\"י שאינו יודע ומשיג כלל את השם, שאותיות אלו הם רק בבחי' מקיף ואעפ\"כ הי' פועל כו'. וזהו שרצו לקבל חיות מהמקיף דהיינו ע\"י שמוש השמות<sup data-n=\"49\">19</sup> וכמ\"ש בלק\"ת מהאריז\"ל, וזהו ותהי להם הלבינה לאבן, שבחרו בלבינה מל' דקליפה שמקבלת רק מבחי' לבונה זכה שהוא רק מבחי' אור מקיף שמחי' קליפות כו', תמורת האבן מל' דקדושה, ורצו להרוס בנין העיר והמגדל דקדושה, וזהו כמ\"ש ושפחה כי תירש גבירתה כו', אמלאה החרבה כו', ולזה גדלה חטאתם עד מאד. וז\"ש הבה נבנה לנו עיר ומגדל וראשו בשמים, פי' וראשו בשמים, הנה כתי' דרך הנשר בשמים, אם תגביהי כנשר<sup data-n=\"50\">20</sup> משם אורידך נאום הוי', והיינו כי שם הוי' מתחיל ביו\"ד והיינו כי כדי שיומשך בבחי' שם הוי' שהוא בחי' חכ' זהו ע\"י יו\"ד דוקא שהוא בחי' צמצום, והיינו לפי שבחכ' נמשך אא\"ס בבחי' גילוי ממש[ednref_10_י], וכדי שיומשך אא\"ס בבחי' גילוי זהו ע\"י צמצום דוקא, כי עצמות אא\"ס אינו יכול להיות נמשך בגילוי כ\"א ע\"י צמצום, והנה נודע שכדי שיומשך בבחי' צמצום זה, זהו ג\"כ ע\"י צמצום שיש בנפש שזהו\"ע יעקב יו\"ד עקב שהוא בחי' ביטול וצמצום, וע\"י בחי' ביטול וצמצום שיש בנפש עי\"ז נתצמצם אא\"ס שיומשך בבחי' חכ' בבחי' גילוי ממש, אך דור הפלגה שלא רצו בבחי' ביטול כו', ולזה אמרו הבה נבנה לנו עיר כו' וראשו בשמים, דהיינו שרצו לקבל מבחי' מקיפים עליונים שלמעלה מבחי' הצמצום שנתצמצם בע\"ס דקדושה ששם אם צדקת כו' וכחשיכא",[["48","18","<b>שהיו יכולים בדורות הקודמים להשביע השמות. ֿ. והי' נעשה כך תיכף ומיד</b>: ראה רשימות חוברת קעט ע' 13-14 (משיחות כ\"ק אדמו\"ר מהוריי\"צ בחורף תרצ\"ה בווין) אודות השבעת השמות ע\"י כ\"ק אדמו\"ר הצ\"צ ואדמו\"ר מהר\"ש."],["49","19","<b>שרצו לקבל חיות מהמקיף דהיינו ע\"י שמוש השמות</b>: ראה בכ\"ז אוה\"ת נח שם. וראה גם תו\"א נח י, ב. מאמרי אדהאמ\"צ שמות ח\"א ע' כה-ז. אוה\"ת נח תרסד, א. וארא (כרך ז) ע' ב'תקנב-ג. ב'תקנז. מטות ע' א'רפט."],["50","20","<b>הנה כתיב דרך הנשר בשמים אם תגביהי כנשר</b>: בהבא לקמן עד סוף הפרק ראה הוספות לתו\"א ויחי קב סע\"ב-ג. סה\"מ תרל\"ב ח\"א ע' נג ואילך. וש\"נ. שם ע' רכה ואילך.\n\n[edn_10_י] <b>שיש בחי' אותיות שהם נמשכים בבחי' פנימיות ממש</b>: בשולי הגליון נרשם בגוכי\"ק: גילוי דבר נבואה לנביא, הגם שזהו ג\"כ רק אותיות, מ\"מ היה מתגלה לו בפנימיות."]]],[2000510082,"כאורה שוין לפניו ואין הביטול תופס מקום כלל, ע\"ד חנם בלא מצות כי שממית בידים תתפש והיא בהיכלי מלך, וזהו וראשו בשמים. אך הנה כתי' משם אורידך נאום הוי' דהיינו כשנמשך בבחי' שם הוי' אין להם יניקה ואחיזה כלל, כי משם הוי' א\"א לקבל כ\"א ע\"י ביטול דוקא, ולכן נא' וירד הוי' לראות את העיר כו'.\nד) <b>וזהו</b> מ\"ש ברבות ודברים אחדים שדברו דברים חדים על שני אחדים על הוי' אחד ועל אחד הי' אברהם כו'. פי' שדברו על ה' אחד, דהנה כתיב ביום ההוא יהי' ה' אחד, והקושיא ידוע אטו האידנא לאו אחד הוא. אך הענין הוא דהנה אנו אומרים בק\"ש הוי' אחד, ולכאורה אינו מובן למה אין אומרים ה' יחיד<sup data-n=\"51\">21</sup> שיחיד הוא למעלה מאחד וכנודע. אך הנה התירוץ ע\"ז דאחד מורה איך שהוא אחד בז' רקיעים וארץ וד' רוחות העולם, והיינו אף כשנברא העולם בז' רקיעים וארץ כו', שיש בחי' ו' קצוות גשמיים ו' קצוות רוחניים שהוא ענין בחי' ז' מדות לך ה' הגדולה, ואעפ\"כ כולם בטלים ממש לאלקות, כי הנה אומות העולם אומרים רם על כל גוים הוי' על השמים כבודו שהוא בחי' ירידה לפניו להשפיל בבחי' ארץ, כ\"א עזב ה' את הארץ ביד המזלות, ורק על השמים כבודו, שהוא בחי' יחיד לבד, אבל למטה נעשה בחי' יש ודבר נפרד ממש. אבל הנה באמת הוא כמו שאנו אומרים המגביהי לשבת המשפילי לראות בשמים ובארץ, לפי שהוא מגביהי לשבת ע\"כ המשפילי לראות בשמים ובארץ בשוה ממש, שכמו שהארץ השפלה לפניו ית' כמו\"כ השמים היא ג\"כ השפלה לפניו, וכמו שיכול להשפיל בשמים כמו\"כ יכול להשפיל בארץ. וזהו ה' אחד, שהוא אחד בז' רקיעים וארץ וד' רוחות העולם והם בתכלית הביטול לאלקות ואינם בחי' נפרד כלל, שזה רבותא יותר מבחי' הוי' יחיד שאין זה רבותא שהכל מודים שהוא יחיד, רק שזהו הרבותא שאפי' בז' רקיעים וארץ כו' הוא ג\"כ אחד. וזה שאנו אומרים ביום ההוא יהי' הוי' אחד, דהיינו שלע\"ל יומשך זה בבחי' גילוי ממש שהכל יהיו רואים בראי' חושית ממש איך שהוא אחד ואין העולם תופס מקום כלל, משא\"כ עתה אין זה בבחי' גילוי ממש כי החשך יכסה ארץ כו'. והנה כדי שיומשך בחי' ה' אחד זהו ע\"י בחי' ביטול, שע\"י ביטול נפש האדם לאלקות עי\"ז נמשך בחי' גילוי אלקות בעולמות, דהיינו שנמשך בחי' אל\"ף אלופו של עולם בז' רקיעים וארץ כו' ועי\"ז נעשה אחד.\n<b>והנה</b> הם לא רצו בבחי' ביטול<sup data-n=\"52\">22</sup> ולא רצו לקבל מבחי' הוי' אחד דהיינו מבחי' המשכת אא\"ס שנמשך בבחי' פנימי' כו' כ\"א מבחי' מקיף לבד. וזהו שדברו על ה' אחד ועל אחד הי' אברהם, היינו כי אברהם נק' אחד לפי שאברהם הי' כלי לבחי' אחד והי' ממשיך בחי' ה' אחד שיהי' המשכת גילוי אלקות בעולמות ממש,",[["51","21","<b>הוי' אחד. . למה אין אומרים ה' יחיד</b>: בהבא לקמן בפיסקא זו ראה תו\"א וארא נה, ב ואילך. לקו\"ת תזריע כג, ג. בלק ע, א. אמרי בינה שער הק\"ש פ\"ח. דרך מצותיך קכד, א-ב. סה\"מ תרכ\"ו ע' קצג-ד. תרכ\"ט ע' לא ואילך. ועוד."],["52","22","<b>והנה הם לא רצו בבחי' ביטול</b>: בהבא לקמן בפיסקא זו ראה תו\"א נח יא, א-ב. מאמרי אדה\"ז פרשיות ע' עב ואילך. תו\"ח נח עד, ב ואילך. אוה\"ת נח (כרך ו) תתרסט, ב ואילך."]]],[2000510083,"כי אברהם הי' בבחי' ביטול והי' מרכבה לבחי' הוי' אחד, כי אברהם הוא אבר מ\"ה כו', וכמ\"ש ויסע אברם הלוך ונסוע הנגבה שתמיד הי' בבחי' ביטול ורצוא ושוב כו', והם לא רצו בזה. וזהו שדברו על אברהם, והיינו שבזה גופא שבנו את העיר והמגדל בזה דברו דברים חדים על שני אחדים לפי שהעיר והמגדל שלהם הוא היפך ממש משני אחדים הנ\"ל. וזהו ששייך דברים אחדים שדברו להעיר ומגדל כו'. אך הכח הזה שהי' להם להמשיך העיר והמגדל להמשיך כח בסט\"א ולהרוס הבנין דקדושה וכמו שאמר הכתוב וזה החלם לעשות ועתה לא יבצר מהם, זהו ע\"י ויהי כל הארץ שפה אחת ודברים אחדים, פי' שהם היו באחדות<sup data-n=\"53\">23</sup>, וע\"ד שמצינו בדברי רז\"ל על דורו של דוד שהיו צדיקים ואעפ\"כ היו יורדים למלחמה ונופלים, ודורו של אחאב שהיו עוע\"ז היו יורדים במלחמה ונוצחים, והיינו לפי שהי' בהם אחדות וכמ\"ש חבור עצבים אפרים הנח לו, משא\"כ דורו של דוד שהי' בהם דלטורי' כו', והיינו כי אחדות היא מדרגה גבוה מאד ולכן לא הי' כח במדה\"ד לשלוט בהם, וגם שהיו שפה אחת שדברו כולם בלה\"ק וכל השבעות ושמושי שמות הם בלה\"ק דוקא, ולכן היו יכולים לפעול הכל כרצונם ע\"י שמושי שמות. ולכן נאמר הבה נרדה ונבלה שם שפתם, והיינו שבלבל לשונם ומחמת זה נתפרדה האחדות, ואז הי' כח במדה\"ד לשלוט עליהם ואז ויפץ ה' אותם כו'.\nה) <b>ומעתה</b> י\"ל ענין מגדל עוז שם הוי'<sup data-n=\"54\">24</sup>, כי הנה ארז\"ל הצדיקים שמם קודם להן דומים לבוראן שנאמר ושמי הוי' לא נודעתי להם, כך הצדיקים שמם קודם להן שנאמר ושמו מרדכי ושמו בועז, אבל הרשעים הן קודמין לשמן גלית שמו נבל שמו כו'. והענין הוא דהנה כתיב ומי כעמך כישראל גוי אחד בארץ אשר הלכו אלקים לפדות לו לעם ולשום לו שם (בש\"ב ז' ך\"ג), וארז\"ל ע\"ז במדרש מצינו שהלך הקב\"ה מהלך ת\"ק שנה לעשות לו שם<sup data-n=\"55\">25</sup> שנאמר ותעש לך שם כהיום הזה[ednref_11_יא], בנחמי' ט' יו\"ד. ולהבין מהו ענין לעשות לו שם, הענין הוא דהנה מבואר למעלה שיש שני בחי', בחי' עיר אלקינו ובחי' מגדל, והנה עיר אלקינו הוא בחי' צירופי אותיות הדבור מבחי' דבר הוי' להחיות הנבראים, שהוא בחי' המשכת בחי' המחדש בטובו בכל יום מעשה בראשית שבכל יום נתחדש הבריאה מאין ליש, שע\"ז נאמר שאו מרום עיניכם וראו מי ברא אלה, המוציא במספר צבאם, שכל אחד ואחד מהלך בשבילו המתוקן לו שאלמלא הי' מעורב כוכב א' בחבירו הי' נחרב העולם, ועל זה נאמר בהבראם כיום הבראם ממש, שבכל יום נמשך המשכת חיות חדש להחיות את העולמות כו'. אך הוא רק חידוש הישנות לבד שאין בזה שום תוס' וגרעון כו' שהוא רק בחי' המשכת הטבע לבד, עוד כל ימי הארץ זרע וקציר כו'. אך יש בחי' המשכה שלמעלה מן הטבע כמו יציאת מצרים וקרי\"ס שהוא היפוך הטבע ממש, הפך ים ליבשה שהיא בחי' המשכה שלמעלה מן הטבע,",[["53","23","<b>פי' שהם היו באחדות</b>: ראה תו\"א נח שם יא, ב. ובמקומות שנסמנו בהע' שלפנ\"ז."],["54","24","<b>ומעתה י\"ל ענין מגדל עוז שם הוי'</b>: בהבא לקמן (בפיסקא זו ושלאחרי') ראה אוה\"ת נח שם תרנו, א. נ\"ך (כרך ב) שם ע' א'יז-יח."],["55","25","<b>וארז\"ל. . שהלך הקב\"ה מהלך ת\"ק שנה לעשות לו שם</b>: ראה בארוכה סה\"מ תר\"ל ע' סז ואילך. וע' צז ואילך.\n\n[edn_11_יא] <b>ועד\"ז הוא פי' מ\"ש ותעש לך שם כהיום הזה</b>: בשולי הגליון נרשמה הגה\"ה בגוכי\"ק [ואח\"כ נרשם ע\"ז: ”הג\"ה זו אצ\"ל\" אין צריך להעתיק]: הנה רש\"י<sup data-n=\"1613\">57</sup> פי' בנחמי' ט' יו\"ד ע\"פ ותעש לך שם, שם רצון בלע\"ז. וא\"כ י\"ל פי' ותעש לך שם שיתגלה בחי' רצון הוא בחי' שם שמקור לבחי' הוי', היינו בחי' שמו שקדם להוי' הוא בחי' עד שלא נברא העולם הי' הוא ושמו בלבד (וזהו כענין מ\"ש במ\"א בפי' חנון ורחום הוי'<sup data-n=\"1614\">59</sup> שהוא ית' חנון ורחום שיומשך בחי' שם הוי') בחי' השם כמו שהוא כלול בעצמותו. וצריך לומר שע\"י העבודה דעכשיו בתומ\"צ ויראה עי\"ז יומשך לע\"ל גילוי בחי' שם שקדם להוי'. וזהו ותעש לך שם הוא בחי' רצון בחי' כתר גלגלתא, שיהי' כהיום הזה שיאיר בגילוי כמו משה נתנבא בזה. אך מ\"ש ברש\"י בלע\"ז א\"י פירושו."],["1613","57","<b>רש\"י פי'. . ע\"פ ותעש לך שם שם רצון בלע\"ז. . אך מ\"ש ברש\"י בלע\"ז א\"י פירושו</b>: כ\"ה בפרש\"י בדפוסי הנ\"ך שלפנינו: ”שם, רצון בלע\"ז\". וראה ס' אוצר לעזי רש\"י (תל אביב, תנש\"א) שמביא עוד גירסא: ”שם, ריטם בלע\"ז\", אך גם לזה אין משמעות בלע\"ז, ומביא שם שבחלק מכת\"י רש\"י נכתב: ”שם, רינון בלע\"ז\", שפירושו בל' צרפת הוא ”תהילה\".\nמש\"כ כאן: ”שם הוא בחי' רצון בחי' כתר\", ראה לקו\"ת פקודי ז, רע\"ד: בס' הקבלה הראשונים כ' שמו גימטריא רצון. וראה גם לקו\"ת בהר מג, א. מסעי צא, ד. מאמרי אדה\"ז הקצרים ע' תקמג. אוה\"ת פנחס ע' א'פד. ובכ\"מ [וראה הקדמה לס' ”שארית ישראל\" (מאנסי, תשנ\"ח) ע' 26, אודות מנהגם של כמה מגדולי ישראל (כמו הרה\"ק הרי\"ד מווילעדניק והרה\"ק הר\"מ מטשערנאביל, ועוד) לפרש את תיבות הלע\"ז שבפירש\"י ומשמעותם בלה\"ק]."],["1614","59","<b>כענין מ\"ש במ\"א בפי' חנון ורחום הוי'</b>: ראה לקו\"ת ואתחנן ג, א. מאמרי אדה\"ז תקס\"ד ע' רב. מאמרי אדהאמ\"צ נ\"ך ע' תקפא ואילך. יהל אור להצ\"צ ע' תרעז. אוה\"ת תשא ע' ב'מו. ואתחנן ע' נד. וע' ס. סה\"מ תרל\"ג ח\"ב ע' תכו."]]],[2000510084,"וזהו שהלך הקב\"ה מהלך ת\"ק שנה לעשות לו שם, דהיינו מה שנמשך גילוי בחי' המשכה שלמעלה מן הטבע נק' בחי' שם וכמ\"ש טוב שם טוב משמן הטוב ששם הטוב הולך מסוף העולם עד סופו, וכן כל זית שיש לו שם בשדה, והיינו מה שהוא דבר הפלא הוא בחי' שם, וכך למעלה שענין גילוי בחי' שם הוי' שלמעלה מן הטבע נק' בחי' שם כו'.\n<b>ובזה</b> יובן הפי' מה ששמו קודם לשם הוי' ושמי הוי' לא נודעתי להם, לפי שכדי שיוכל להיות בחי' גילוי שם הוי' זהו מצד שנמשך המשכה עליונה יותר שלמעלה משם הוי' בבחי' שם הוי', וכמ\"ש מה גדלו מעשיך ה' מאד עמקו מחשבותיך וכתיב לעושה נפלאות גדולות לבדו כו', שבחי' פלא נמשך מבחי' לבדו כו' בחי' ולגדולתו אין חקר, והיינו שיש שני בחי', מה רבו מעשיך ה' ובחי' מה גדלו מעשיך כו', בחי' מה רבו מעשיך היא בחי' המשכה שנמשך בכל יום לחדש את הישנות וכמש\"א בברכת יוצר ובטובו מחדש בכל יום תמיד מעשה בראשית, וכתיב אח\"כ מה רבו מעשיך ה', אך בחי' מה גדלו מעשיך היא בחי' המשכה שלמעלה מן הטבע כמו נס דיציאת מצרים וקרי\"ס שזה נמשך מבחי' ולגדולתו אין חקר, בחי' עמקו מחשבותיך, עומק המח' בחי' כ\"ע כו'. וזה ששמו קודם לשם הוי', והיינו לפי שהוא המשכה בשם הוי' מבחי' העצמי' עד שלא נברא העולם הי' הוא ושמו בלבד. וזהו שהלך לעשות לו שם כו' שנאמר ותעש לך שם כהיום הזה כו', ופי' כהיום הזה היינו ע\"ד שאומרים בק\"ש ויציב כו' הדבר הזה שיהי' הדבר בבחי' זה בחי' גילוי, וכמשארז\"ל כל הנביאים נתנבאו בכה ומשה נתנבא בזה בחי' גילוי אספקלריא המאירה<sup data-n=\"56\">26</sup>, וזהו הדבר הזה, שיהי' מאיר בדבר בחי' זה, ושיתגלה כן למטה. ועד\"ז הוא פי' מ\"ש ותעש לך שם כהיום הזה שיהי' גילוי בחי' זה ויהי'",[["56","26","<b>וכמשארז\"ל. . ומשה נתנבא בזה בחי' גילוי אספקלריא המאירה</b>: ראה לעיל ד\"ה ויקח ה\"א. וש\"נ."]]],[2000510085,"גילוי בחי' שם כמו שהוא למעלה יתגלה למטה, וכמ\"ש ונגלה כבוד הוי' כו' וראו כל בשר כי פי ה' דיבר כו'. והנה בחי' שם זה הוא בחי' המגדל דקדושה, כי מגדל הוא לשון גדול בחי' ולגדולתו אין חקר כו'. וזהו מגדל עוז שם הוי' שהמגדל הוא בחי' גילוי שם הוי' שהשם קדם להוי' דהיינו בחי' שם טוב כו', בו ירוץ צדיק ונשגב, והיינו שצדיקים ממשיכים את בחי' המגדל בחי' שמו קודם להוי' ולכך גם הצדיקים שמם קודם להן כו'. והנה מ\"ש בו ירוץ צדיק קאי על כללות נש\"י שכולם נק' צדיקים וכמ\"ש ועמך כולם צדיקים והוא כמ\"ש בזהר מאן דנטיר ברית אקרי צדיק כו'. ובזה יובן ג\"כ ההפרש מה שבחול אומרים מגדיל ישועות מלכו, בפתח, ובשבת מגדול, בחיריק<sup data-n=\"57\">27</sup>, והיינו לפי שבחי' מגדיל בפתח מורה על בחי' גדול הוי' ומהולל מאד בעיר אלקינו שהוא רק המשכה<sup data-n=\"58\">28</sup> מבחי' עיר אלקינו בחי' צירופי אותיות הדבור לבד כו' בחי' מה רבו מעשיך הוי', אך בשבת הוא בחי' התגלות מבחי' מגדול בחיריק שהוא בחי' מה גדלו מעשיך הוי' בחי' ולגדולתו אין חקר, ולזה אנו אומרים מגדול.\n<b>וזהו</b> והי' הנשאר בציון, פי' נשאר ע\"ד והי' שארית<sup data-n=\"59\">29</sup> יעקב שמשים את עצמו כשיריים שהוא בחי' חיריק נקודה התחתונה של סגול שמברר את השני נקודות העליונות שהוא בחי' עשו וישמעאל, עי\"ז נמשך בחי' ציון שהוא בחי' מגדל, כי ציון הוא קדש הקדשים וכמש\"א ציון המצויינת קדש הקדשים שהוא ג\"כ בחי' מגדל וכנ\"ל שהמגדל הוא קדש הקדשים, והיינו שעי\"ז שהוא בחי' שארית בחי' נקודה לבד חיריק עי\"ז נמשך בחי' מגדול ג\"כ בחיריק, שהוא ע\"ד שאנו אומרים בשבת בחי' מגדול בחיריק, קדוש יאמר לו שיאמרו המלאכים לפניהם קדוש לפי שיומשך למטה גילוי אלקות ממש מבחי' קדש הקדשים ולכך יאמרו לפניהם קדוש כו' וכנ\"ל.",[["57","27","<b>מגדיל. . בפתח. . מגדול בחיריק</b>: ראה אוה\"ת נ\"ך ע' מז. שם (כרך ב) ס\"ע א'יט-כ."],["58","28","<b>מגדיל בפתח. . שהוא רק המשכה</b>: ראה אוה\"ת ואתחנן ע' שפב: הפתח במבטא שיפתחו השפתיים היפך הקמץ, לכך למעלה מורה כו' שנפתח המקור כו' בבחי' גילוי דוקא. וראה גם שם ע' שעט-פ."],["59","29","<b>וזהו והי' הנשאר בציון. . ע\"ד והי' שארית</b>: בהבא לקמן ראה ד\"ה והי' הנשאר בציון באוה\"ת נ\"ך שם (כרך ב) ע' תשסב."]]],[2000510086,"<h3>ויאמר גו' לך לך (א)</h3>\n<b>בס\"ד. ש\"פ לך, לתא\"ר.</b>\n<b>ויאמר</b> ה' אל אברם לך לך<sup data-n=\"60\">1</sup> מארצך כו' אל הארץ אשר אראך, ואיתא בספרים[ednref_12_יב] ששורש נש\"י הם מעולם האחדות (הכוונה היא על עולם האצי', והגם שרוב נשמות הם מבי\"ע, מ\"מ שורש כולם הוא מאצי' כמ\"ש בלק\"ת בשה\"ש בביאור השני שע\"פ יונתי<sup data-n=\"61\">2</sup> בחגוי הסלע, וז\"ע מה שאנו אומרים נשמה שנתת בי טהורה היא רק שירדה בבחי' בראת יצרת נפחת בי\"ע), וידוע שדבר שבקדושה אינו נעקר ממקומו לגמרי לכן עיקר הנשמה נשארה למעלה (ע' בלק\"ת בד\"ה יונתי בחגוי הנ\"ל ובד\"ה האזינו<sup data-n=\"62\">3</sup> בענין והרוח תשוב, וז\"ע מה שארז\"ל אע\"ג דאיהו לא חזי מזלייהו חזי, פי' מזלייהו הוא שורש הנשמה שנשארה למעלה שהיא העיקר והשורש לבחי' הנשמה המלובשת בגוף כו'), ולכן אמר הקב\"ה לאברם לך לך לשרשך ומקורך שורש הנשמה, וזהו ע\"י הארץ אשר אראך דוקא, משא\"כ בהיותו באור כשדים כו' לא הי' יכול להתדבק בשרשו[ednref_13_יג] באלקי' חיים כ\"א ע\"י הארץ דוקא. ולכאורה צ\"ל דא\"כ הנשמות שבחוץ לארץ האם נאמר שאין להם דביקות ח\"ו בשורש נשמתן הדבוק למעלה, ואם גם נשמות אלו יש להם דבקות בשרשן מה ענין שאמר לו לך לך.\n<b>ויובן</b> זה ע\"פ משארז\"ל ברבות רות[ednref_14_יד] ע\"פ ישלם ה' פעלך כו' אשר באת לחסות תחת כנפיו<sup data-n=\"63\">4</sup>, שמענו שיש כנפי' לארץ[ednref_15_טו] וכנפים לשמש וכנפים לחיות וכנפים",[["60","1","<b>ויאמר ה' אל אברם לך לך</b>: מאמר זה הוא מהדורא קמא מהמאמר. ולאח\"ז נרשם עוה\"פ בגוכי\"ק במהדורא בתרא עם הוספות ושינויים ונדפס לקמן לאחרי מאמר זה. [ולאידך ישנם כאן כו\"כ ענינים שלא הובאו במהדו\"ב].\nלכללות המאמר ראה לקמן בד\"ה ויאמר גו' לך לך הב', ושם נסמנו גם המ\"מ והציונים להמאמר ולא נכפלו כאן (רוב) המ\"מ והציונים."],["61","2","<b>בלק\"ת בשה\"ש בביאור השני שע\"פ יונתי</b>: דף יט, ג."],["62","3","<b>בלק\"ת בד\"ה יונתי בחגוי ובד\"ה האזינו</b>: לקו\"ת שה\"ש שם טז, ד. האזינו עא, ד."],["63","4","<b>משארז\"ל ברבות רות. . לחסות תחת כנפיו</b>: קאי על המשך לשון האלשיך שם שהנשמות שרשן למעלה הוא ”תחת כנפי השכינה\", וע\"ז מביא כאן את דברי המדרש אודות הלשון תחת כנפיו [הובא גם באוה\"ת לך לך] — הבא לקמן בפיסקא זו מדברי המדרש (והביאור ע\"ז לקמן פרק ו) לא הובאו בהמאמר שלאח\"ז.\n\n[edn_12_יב] <b>ואיתא בספרים</b>: בגוכי\"ק נוסף כאן [ואח\"כ נרשם ע\"ז שא\"צ להעתיקו]: מהרמ\"א<sup data-n=\"1615\">64</sup> ובס' פנים יפות.\n\n[edn_13_יג] <b>באור כשדים כו' לא היה יכול להתדבק בשרשו. ֿ. כ\"א ע\"י הארץ</b>: בשולי הגליון נרשם בגוכי\"ק: לענין שאברהם ע\"י ארץ, שזה היה קודם מתן תורה. ועל ידי תורה ומצות ועבודה שבלב גם בחו\"ל מתדבקים שז\"ע הסולם מלמעלמ\"ט ומלמטלמ\"ע.\n\n[edn_14_יד] <b>משארז\"ל ברבות רות</b>: בגוכי\"ק נוסף כאן [ואח\"כ נרשם ע\"ז: אצ\"ל]: דף ז' ע\"ג בדפוס שקלאוו.\n\n[edn_15_טו] <b>שמענו שיש כנפים לארץ. . וכנפים לשרפים</b>: בגוכי\"ק נוסף כאן: ומביא פסוקים."],["1615","64","<b>מהרמ\"א</b>: מו\"ה ר' משה אלשיך. הבא לקמן (עד התיבות: כ\"א ע\"י הארץ דוקא) הוא תוכן דברי האלשיך שם עם הוספות בין חצאי עיגול."]]],[2000510087,"לכרובים וכנפים לשרפים, בא וראה כמה גדול כוחן של צדיקים וכמה גדול כחה של צדקה[ednref_16_טז] וכמה גדול כוחן של גומלי חסדים שאין חסין לא בצל שחר ולא בצל כנפי הארץ ולא בצל כנפי כרובים ולא בצל כנפי שמש ולא בצל כנפי שרפים, אלא בצל מי שאמר והי' העולם שנאמר מה יקר חסדך אלקים ובני אדם בצל כנפיך יחסיון[ednref_17_יז] (תילים ל\"ו ט'). וצ\"ל מהו ענין ובני אדם בצל כנפיך יחסיון.\n<b>והענין</b> הוא דהנה ידוע אשר מל' דאצי'[ednref_18_יח] לעולם לא תרד למטה ליצי' ועשי' להתלבש בע\"ש, כ\"א היא למעלה באצי' או בבריאה, ורק בחי' מל' דיצי' ועשי' מתלבשת בע\"ש להשפיע להם השפע הראוי להם, וזהו שארז\"ל גלו כו' שכינה עמהם, פי' שכאשר מצטרך להשפיע השפע לישראל בזה\"ג בהיותם תחת ע' שרים אזי מוכרחת השכינה היינו בחי' מל' דיצי' ועשי' להתלבש בהשרים ההם שישראל שרוים על אדמתן, ודרך בו תעבור השפע כו', וז\"ע שכינה עמהם, וזה ענין כשושנה בין החוחים. אמנם הנה כ\"ז הוא בחי' מל' דיצי' ועשי' ולא מל' דאצי' שעז\"נ וכבודי לאחר לא אתן. והטעם מה שמל' דיצי' ועשי' מתלבשים דוקא בע' שרים ולא מל' דאצי' (וזהו לפי קבלת האריז\"ל ולא לפמ\"ש בס' אור נערב שס' מאצי' יש הארה) (וגם מל' דבריאה רק לפרקים לבד תתלבש בהם ולא בתמידות),",[["","","[edn_16_טז] <b>וכמה גדול כחה של צדקה וכמה גדול כוחן של גומלי חסדים. . בצל מי שאמר והיה העולם</b>: בשולי הגליון נרשם בגוכי\"ק: לענין צדקה יש להעיר מענין והחמישית לפרעה. לענין בצל מי שאמר, יש להעיר מענין בצל אל היית וידעת, ל' ידע את.\nלענין חסד יש להעיר מענין כי חסד חפצתי ולא זבח, ולכן אברהם ע\"י שתיקן שחרית שעיון תפלה בכלל גמ\"ח, הוא יותר טוב מזבח. אך זהו ע\"י הארץ, כי גם עכשיו והתפללו דרך ארצם דוקא. אך זה היה קודם מתן תורה, אבל ע\"י מתן תורה כל העוסק בתורת עולה כו' גם בחוץ לארץ יכול לדבוק בשורש נשמתו, וגדול המצווה ועושה. וע\"י צדקה ממשיכים בחי' והחמישית בחי' כתר, וכל המצות נקראו בשם צדקה, כי מצות המלך הם כלים להשראות האור מבחי' תרי\"ג ארחין דגלגלתא בחי' רצון. וזהו ג\"כ ענין ארץ ל' רצוא בנש\"י שנק' ארץ חפץ. אך הכח הזה הוא מעשה אבות סימן לבנים, גם המתנה שלזרעך נתתי את הארץ בחי' ארץ העליונה, והכריתות ברית דמשה שגם בהיותם כו' לא מאסתים שיומשך המשכת אוא\"ס ע\"י תומ\"צ ועבודה שבלב זו תפלה.\n\n[edn_17_יז] <b>וצ\"ל מהו ענין ובני אדם בצל כנפיך יחסיון</b>: בגוכי\"ק נוסף כאן: אך הענין הוא כמ\"ש טוב לחסות בהוי' מבטוח באדם [ואח\"כ נרשם ע\"ז: יתיר, כי אינו לכאן. — וכנראה שהי' בדעתו הק' לבאר זה, אך לפועל לא נרשם בגוכי\"ק. וראה לקו\"ת דרושים לשמע\"צ צ, ד. צא, א ואילך. מאמרי אדה\"ז תקס\"ד ע' רלז ואילך].\n\n[edn_18_יח] <b>והענין הוא דהנה ידוע אשר מל' דאצי'</b>: בגוכי\"ק נרשם כאן [ואח\"כ נרשם ע\"ז: אצ\"ל]: ע' בביאור ע\"פ ואני אראה בשונאי בסוף ספר תקס\"ד<sup data-n=\"1616\">68</sup>."],["1616","68","<b>בביאור ע\"פ ואני אראה. . בסוף ספר תקס\"ד</b>: מאמרי אדה\"ז תקס\"ד ע' רמה. ובתוס' הגהות באוה\"ת לך לך תרעה, א ואילך. דרושים לשמע\"צ ע' א'תתכח-ט. — והבא לקמן עד סוף הפיסקא מיוסד על ביאור הנ\"ל."]]],[2000510088,"הנה איתא בע\"ח שבבריאה רובו טוב ומיעוטו רע, וביצי' מחצה על מחצה שחצי' טוב כו', ובעשי' רובו רע ע\"כ התחלת מדור החיצונים הוא מיצי' ואילך מאחר ששם מחצה על מחצה אבל לא בבריאה מאחר שרובו טוב, ולכך עיקר המתלבשים בע' שרים בתמידות הם המל' דיצי' ועשי' דוקא עכ\"ל. ועוד יש לומר טעם אחר כי חכמה מאיר באצי' ובינה מקננא בבריאה ושית ספירין מקננא ביצי', וידוע כי יניקת החיצונים היא רק מז' תחתונות לבד, משא\"כ בחו\"ב אפי' חו\"ב שבמדות כמ\"ש בסידור סד\"ה הללוי' הללי נפשי<sup data-n=\"64\">5</sup> את הוי', וע' בת\"א פ' וישלח בד\"ה ויאבק<sup data-n=\"65\">6</sup> איש עמו, ע\"כ התחלת מדורם הוא מיצירה, ובבריאה כיון דבינה מקננא בבריאה אין משם יניקה כלל (אך צ\"ל מה שלפעמי' תתלבש).\n<b>ובזה</b> יובן בכלל מה שא\"ל לך מארצך כי בהיותו באור כשדים שהיא חו\"ל ששם מאיר רק מל' דיצי' ועשי', א\"כ לא נתגלה ממקור שורש נשמתו רק כמו שהוא במל' דיצי' בחי' שושנה בין החוחים לבד, אבל ע\"י עלייתו אל הארץ אשר אראך שמכוון נגד מל' דאצי' ובריאה יאיר בו בחי' שורש נשמתו כמו שהוא במל' דאצי', ומכ\"ש לפי מה שנת' שבאצי' ובריאה מאיר בחי' י\"ה שזהו בחי' ג\"ר, ולכן דוקא ע\"י הארץ יכול לבוא לבחי' שורש נשמתו, ונודע שהנבואה היא מאצי'.\nב) <b>ולהבין</b> שורש ענין הארץ הנה ארז\"ל במד\"ר בראשית פ\"ה למה נק' שמה ארץ שרצתה לעשות רצון קונה, ופי' ארץ היא מל' רצוא ומלשון רצון, והיינו מפני כי נעוץ תחלתן בסופן וסופן בתחלתן, ולכן הארץ היא מל' רצון, ויש לה רצוא ותשוקה ליכלל ולבטל באוא\"ס ב\"ה התחילה<sup data-n=\"66\">7</sup>, וכמ\"ש למען יזמרך כבוד כו' נהורא תתאה קארי תדיר לנהורא עילאה ולא שכיך, לפי שבה כוונת נעיצת התחילה יותר כי במחשבה ארץ קדמה כו'. ולהבין זה צ\"ל מארז\"ל חגיגה די\"ב ב' תניא ר' יוסי אומר אוי להם לבריות שרואות ואינן יודעות מה הן רואות, עומדות ואין יודעות על מה הן עומדות, הארץ על מה עומדת על העמודים שנאמר המרגיז ארץ ממקומה ועמודיה יתפלצון (איוב ט' וא\"ו), עמודי' על המים שנאמר לרוקע כו', מים על ההרים שנאמר על הרים יעמדו מים, הרים ברוח שנאמר כי הנה יוצר הרים ובורא רוח (עמוס ד'), רוח בסערה שנאמר רוח סערה עושה דברו, סערה תלוי' בזרועו של הקב\"ה שנאמר מתחת זרועות עולם (בפ' הברכה ל\"ג). ופי' הערוך הכול תלוי בגבורה של הקב\"ה והגבורה היא זרועו כדכתיב לך זרוע עם גבורה.\n<b>והנה</b> בזח\"א פ' לך לך דע\"ז א' איתא ג\"כ מאמר זה שאמר ר' יוסי עצמו זה ע\"פ מה ידידות משכנותיך ה' צבאות (תילים פ\"ד) כמה אית לון לב\"נ לאסתכלא בפולחנא דקוב\"ה, דהא כל ב\"נ לא ידעין על מה קאים עלמא ועל מה אינון קיימין,",[["64","5","<b>בסידור סד\"ה הללוי' הללי נפשי</b>: דף נו, ג."],["65","6","<b>בת\"א פ' וישלח בד\"ה ויאבק</b>: דף כו, ב."],["66","7","<b>ליכלל ולבטל באוא\"ס ב\"ה התחילה</b>: כ\"ה בגוכי\"ק, — ור\"ל שאוא\"ס הוא בחי' התחילה, וספי' המל' היא סופא דכל דרגין, ונעוץ תחילתן בסופן וסופן בתחילתן."]]],[2000510089,"ומפרש שכד עביד קוב\"ה עלמא עבד שמיא מאש וממיא מתערבין כחדא ולא הוו גלדי, ולבתר אתגלידו וקיימו ברוחא עילאה ומתמן שתיל עלמא לקיימא על סמכין, וסמכין לא קיימין אלא בההוא רוחא, ובשעתא דרוחא אסתלק כולהו מרפפין וזעין ועלמא מרתת הה\"ד המרגיז ארץ ממקומה ועמודי' כו' וכולא קאים על אורייתא דכד ישראל משתדלי באורייתא מתקיים עלמא. והיינו כמ\"ש במד\"ר פ' ויקהל פ' מ\"ח ע\"פ ואל מי תדמיוני ואשוה יאמר קדוש, אלה תולדות השמים כו' אלה בזכות מי נבראו ובזכות מי הם עומדים בזכות ואלה שמות בני ישראל, ואלה בזכות מי כו' בזכות אלה העדות החוקים והמשפטים, שכל מכוון הבריאה הי' בשביל זה. וכמארז\"ל בבראשית רבה פ\"א בענין האל\"ף שקרא תגר שהוא ראשון של אותיות, א\"ל הקב\"ה העולם ומלואה לא נברא אלא בזכות התורה שנאמר ה' בחכמה יסד ארץ (משלי ך\"ו), וכ\"ש שע\"י עסק התורה קאי' עלמא, וכמארז\"ל במשנה דאבות על ג' דברים העולם עומד על התורה כו', והעיקר הוא התורה שבה נכללים גם עבודה וגמילות חסדים שהכל נאמר בתורה, וכל העוסק בתורת עולה כאילו הקריב עולה גם עכשיו שאין לנו בית המקדש וכלי המקדש ושלא במקומו ושלא בזמנו כמ\"ש הטעם במ\"א, ע' בלק\"ת פ' במדבר בד\"ה בשעה שהקדימו<sup data-n=\"67\">8</sup>, ולכן אמר וכולא קאים על אורייתא, כד ישראל משתדלי באורייתא מתקיים עלמא.\n<b>וביאור</b> הענין יובן בהקדם הבנת דבריו שאמר דשמיא עביד מאש וממיא, וכ\"ה ברבות בראשית ספ\"ד נטל הקב\"ה אש ומים ופתכן (פי' הערוך ערבן ובלבלן) זה בזה ומהם נעשו שמים, ולכן בתיבת שמים יש שי\"ן מאש ותיבת מים [והאל\"ף שבתי' אש יוצא מהקמץ שבשי\"ן של שמים כנודע שקמץ מוצא אל\"ף, והוא מהאותיות שמשלימים אותיות התורה לס' רבוא אותיות, כמ\"ש מזה בהגהות לד\"ה את שבתותי שבלק\"ת<sup data-n=\"68\">9</sup> (ובהגהות לד\"ה והנה אנחנו מאלמים<sup data-n=\"69\">10</sup> שבת\"א)], שהם בחי' חו\"ג, וכדכתי' כי אמרתי עולם חסד יבנה, אמנם אם הי' ע\"י בחי' חסד לבד לא הי' יכול להיות קיום העולם, וכמו שאנו רואים במלכותא דארעא שא\"א להיות ע\"פ החסד לבד כ\"א גם ע\"פ הדין והמשפט וכמ\"ש מלך במשפט יעמיד ארץ, שהנהגת המלוכה צ\"ל גם ע\"פ דין ומשפט ובלא זה א\"א להיות הנהגת המלוכה וכמארז\"ל אלמלא מוראו כו', וכך יובן למעלה שהתהוות העולם א\"א להיות ע\"פ החסד לבד, שהגם דכתי' והוכן בחסד כסא מ\"מ א\"א ע\"י בחי' החסד לבד שהי' חטאין סגיאין וגם לא הי' מתקיים כלל, כ\"א ע\"י התכללות חו\"ג דוקא שהם אש ומים. והנה אש ומים הם שני הפכים בטבעם שמים מכבין אש, לזה הוא ענין הרוח הוא בחי' ת\"ת מחבר אותם, והיינו מפני כי הרוח שרשו גבוה מאד [כמ\"ש המק\"מ על מאה\"ז פקודי דרל\"ח ע\"ב רוחא דלגו באמצעיתא (נ\"ב ת\"ת) דאקרי רוח חכמה ובינה, נ\"ב שהת\"ת נמשך מהחכ' ובינה] ושורש שרשו הוא מבחי' אויר אור יו\"ד לכן יכול",[["67","8","<b>כמ\"ש הטעם במ\"א ע' בלק\"ת פ' במדבר בד\"ה בשעה שהקדימו</b>: דף יג, סע\"א. וראה גם סה\"מ תרכ\"ז ע' שלו (בשוה\"ג)."],["68","9","<b>בהגהות לד\"ה את שבתותי שבלק\"ת</b>: ראה לקו\"ת בהר מא, ב. והגהות ע\"ז באוה\"ת בהר (כרך ג) ע' תתקא."],["69","10","<b>ובהגהות לד\"ה והנה אנחנו מאלמים</b>: אוה\"ת וישב רעג, א. שם (כרך ו) תתרפב, ב."]]],[2000510090,"לחבר ב' בחי' חו\"ג וכמ\"ש המשל ופחד עמו עושה שלום במרומיו, שע\"י שהמשל ופחד עמו גילוי הארה מלמעלה כו' עי\"ז עושה שלום במרומיו מיכאל שר של מים וגבריאל שר של אש ואין מכבין זא\"ז, ולכן נק' הקב\"ה שלמה מלך שהשלום שלו פי' שמחבר ב' בחי' חו\"ג כו' ע\"י גילוי הארה היותר עליונה משניהם, וזהו בחי' ת\"ת מדתו של יעקב בריח התיכון, ולכן באברהם ויצחק נאמר אלקי, וביעקב נאמר ואלקי יעקב בתוס' וא\"ו, וכן הגדול הגבור בלא וא\"ו, והנורא הוא בוא\"ו ושרשו מבחי' אל עליון כו'. וז\"ע שא' דקיימא ברוחא עילאה שבחי' הרוח מחבר אש ומים, וזהו בחי' התיקון בחי' התכללות ע\"י שנמשך הארה מבחי' כח מ\"ה הוא בחי' הביטול אשר זהו כלי להשראת אוא\"ס דלאו מכל אינון מדות איהו כלל, וע\"י גילוי הארה זו מתכללי' ב' המדות חו\"ג.\n<b>וזהו</b> שאמר בס\"י ג' אמות אמ\"ש שהוא ר\"ת אויר מים אש, שהאויר מחבר המים עם האש, שהאויר הוא גבוה יותר מבחי' המים והאש וכמו שאנו רואים שהאש מורגש בחוש הראות, והמים אפשר להרגיש גם בחוש המישוש, אבל האויר לעוצם דקותו א\"א להרגיש אותו בחושים הגשמיים, אשר מזה מובן שהאויר הוא גבוה יותר ממים ואש, לכן ביכולתו לחבר אש ומים כו'. וזש\"א דמתחלה לא הוו גלדי ולבתר אגלידו וקיימו ברוחא עילאה, שע\"י בחי' הרוח אגלידו המים, פי' שנקרשו המים ונעשו כמו גלד וקרח, והיינו כי המים בעת שהולכים הולכים בחוזק וכמ\"ש (ביחזקאל א' ך\"ד) ואשמע את קול כנפיהם כקול מים רבים, והרי הם אז בבחי' יש, אבל כשנגלדים המים ע\"י רוח צפונית המנשבת בהם בתוקף ובקרירות גדולה נעשה מהמים גליד וקרח שהוא ביטול הילוכם ומהותם הקודם, והרי הם עומדים על בחי' א'. וכך יובן בנמשל למעלה שע\"י בחי' רוחא עילאה אגלידו מיא ונתבטלו ממהותם והילוכם הקדום, שטבע המים להיות נמשכים מלמעלה למטה, והאש מלמטה למעלה, כ\"א אגלידו וקמו כמו גליד וקרח, והיינו מחמת עוצם הביטול כמו השרים לפני המלך, וכנ\"ל בענין עושה שלום במרומיו כו', וקרח אותי' חרק, כמו החיריק שהיא רק נקודה חדא בחי' ביטול בהעדר ההתפשטות מחמת הביטול, וכמו שנת' במ\"א גבי קרי\"ס שקמו המים כמו נד כי איידי דטריד למיבלע לא פליט<sup data-n=\"70\">11</sup>, וכאן זהו מחמת בחי' רוחא עילאה המנשב בהם נתבטלו ממציאותם הקדום ונגלדו. וזהו ענין שמתחלה עביד שמי' מאש וממיא מתערבין כחדא ולא הוו גלדי, ולבתר אתגלידו וקיימו ברוחא עילאה. וכן אמרו ברבות בראשית פ\"ג ע\"פ יהי רקיע, לחים היו בראשון ובשני קרשו, פי' הגם דכתיב בראשית כו' את השמים, מ\"מ לחים היו וכמ\"ש בזהר דלא הוו קיימי ובשני קרשו דאתגלידו וקרשו כו', והיינו ע\"י הרוח כו'.\nג) <b>והנה</b> קיום בחי' הרוח הוא ע\"י התורה, וז\"ש וכולא קאים על אורייתא כד ישראל משתדלי באורייתא מתקיים עלמא, והיינו לפי שאורייתא מחכמה",[["70","11","<b>שנת' במ\"א גבי קרי\"ס שקמו המים. . איידי דטריד למיבלע לא פליט</b>: ראה בארוכה ביאוה\"ז לאדהאמ\"צ מה, ב ואילך."]]],[2000510091,"נפקת ובחכמה שורה אוא\"ס שהחכמה היא בחי' כח מ\"ה בחי' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה, ולכן ע\"י קול התורה נמשך התכללות המדות. והענין הוא דהנה הקול הוא ג\"כ מורכב מג' יסודות אש מים רוח, כי יסוד האש הוא בלב, והריאה מרחפת על הלב להשקיט החום שזהו מבחי' יסוד המים, וכנודע שהריאה ממשכת כל מיני משקה, וע\"י אמצעות הקנה יוצא הקול מורכב מג' יסודות אש מים רוח, ולכן אנו רואים שכאשר מתגבר באדם יסוד האש עד\"מ משתנה הקול כו'. ועפ\"ז יובן שע\"י הקול דתורה שמורכב מג' יסודות אש מים רוח עי\"ז נמשך קיום העולם שיתכלל חו\"ג להיות כחדא בבחי' קיום וחיזוק, כי אורייתא מחכ' נפקת ובחכמה השראת אוא\"ס כנ\"ל, וע\"י הארת אוא\"ס ב\"ה דלאו מכל אינון מדות איהו כלל מתבטלים המדות חו\"ג ונכללים כחדא כו'.\n<b>ומ\"ש</b> בזהר ומתמן שתיל עלמא לקיימא על סמכין וסמכין לא קיימין אלא ברוחא, ובל' הגמרא נק' עמודים, והיינו הך, היינו שמפרש ענין קיום הארץ, דהנה כתי' כגבוה שמים מארץ, כי שמים הוא בחי' ז\"א דאצי' (וגם חו\"ב הוא בחי' שמים וארץ), ובכלל אצי' נק' שמים כמ\"ש בבה\"ז בתוס' דבשלח<sup data-n=\"71\">12</sup>, שהוא בחי' ע\"ס דאצי' אשר שם איהו וחיוהי חד, אבל הארץ הוא מקור לבי\"ע עולמות הנפרדים נבראים בעלי גבול, ולזה מפרש דכמו קיום שמים חו\"ג דאצי' הוא ע\"י בחי' רוחא עילאה שעי\"ז מתכללים חג\"ת, כמו\"כ קיום הארץ הוא ע\"י סמכין הם בחי' נה\"י דז\"א, ע' במק\"מ, ובחי' נה\"י ז\"ע שארז\"ל כליות יועצות, והיינו שז\"ע בחי' העצה איך שיומשך המשכת אלקות לבי\"ע עולמות הנבראים ונפרדים, כמו שכאשר האדם צריך להשפיע שכל לזולתו אזי צריך לייעץ בעצמו איך להשפיע, כמו\"כ יובן ענין בחי' נה\"י שהו\"ע בחי' כליות יועצות איך שיומשך בבחי' ארץ מקור דבי\"ע בחי' השפעת והמשכת אלקות. וההתכללות דנה\"י זהו ג\"כ ע\"י התומ\"צ וכמ\"ש במחוקק במשענותם, במחוקק הוא בחי' אותיות החקיקה שבתורה, במשענותם הוא בחי' המצות שנק' תמכין בחי' משענת כמ\"ש בלק\"ת בסוף הביאור ע\"פ אז ישיר<sup data-n=\"72\">13</sup> עלי באר. וזהו בחי' העמודים שבגמ' והסמכין שבזהר, שע\"י בחי' התומ\"צ מתקיימין שמים וארץ. ולכן מסיים בזהר וכולא קאים על אורייתא דכד ישראל משתדלין באורייתא מתקיים עלמא, שקיום השמים בחי' חו\"ג הוא ע\"י רוחא עילאה, וכן קיום הארץ הוא ע\"י הסמכין נה\"י, וכולא ע\"י אורייתא לפי שאורייתא מחכ' נפקת בחי' כח מ\"ה שבחכמה שבה השראת אוא\"ס דלאו מכל אינון מידות איהו כלל, ולכן בה וע\"י נמשך קיום העולם וגם נמשך תוס' אורות כו'.\n<b>אך</b> צ\"ל מפני מה בגמ' לא אמר ר' יוסי זה ע\"פ דמה ידידות ובזהר אמר זה ע\"פ דמה ידידות, הוא לפי שבזהר מקדים זה לפסוק לך לך כו' אל הארץ, וע\"כ צ\"ל שפסוק מה ידידות שייך לענין אברהם ולענין הארץ. אך הענין הוא דענין ידידות הוא בחי' תוקף האהבה, וע\"ד שארז\"ל ברבות פ' וישלח פ\"פ שמפרשיתו של",[["71","12","<b>כמ\"ש בבה\"ז בתוס' דבשלח</b>: ביאוה\"ז לאדהאמ\"צ שם דף מה, א."],["72","13","<b>בלק\"ת בסוף הביאור ע\"פ אז ישיר</b>: פ' חוקת דף סד, סע\"ב-ג."]]],[2000510092,"אותו רשע אנו למידי' תוקף האהבות דדביקה חשיקה חפיצה, שה\"ע פנימיות האהבה, ונשתבחו ישראל בג' לשונות אלו שהרי אמר ר\"ל שם שבג' לשונות של חיבה חיבב הקב\"ה את ישראל בדביקה שנאמר ואתם הדבקים בה' אלקיכם, ובחשיקה לא מרובכם מכל העמים חשק ה' בכם, ובחפיצה ואשרו אתכם כל הגוים כי תהיו אתם ארץ חפץ (במלאכי ג' י\"ב). והענין הוא כי הנה בהשתלשלות חיות אלקות בעולמות יש שני בחי', הא' בחי' חידוש הישנות שזהו מה שבטובו מחדש בכל יום תמיד מעשה בראשית, שבכ\"י מתחדש הבריאה מאין ליש, ולכן בכל יום מאפיל ונעשה לילה וכאור בקר מאיר היום וחדשי' לבקרים מתחדשים כל הברואים, שזהו כברייתו של עולם ברישא חשוכא כו' כמ\"ש ויהי ערב ויהי בקר, וע\"ז נאמר לעולם ה' דברך נצב בשמים שבחי' דבר ה' המחי' שמים עד\"מ עומד תמיד בשמים להחיותו ע\"י שבכל יום תמיד מחדש מאין ליש מעשה בראשית, ואם הי' מסתלק כרגע האותיות מעשרה מאמרות המחיים את השמים הי' נעשה מהם אין ואפס. אמנם הגם כי האור האלקי הלזה מחי' ומהוה תמיד התחדשות העולמות מאין ליש, מ\"מ ה\"ז בבחי' העלם והסתר אלקות, וכנודע שענין בריאה יש מאין א\"א להיות כ\"א בדרך העלם והסתר הבורא מהנברא וכמשנ\"ת ביאור ד\"ז במ\"א בד\"ה מהיכן זכו, ובד\"ה מי כמוכה<sup data-n=\"73\">14</sup> באלי', ולכן מזה נמשך עולמים ל' העלם והסתר כו'. אך הנה יש עוד בחי' גבוה מזה והו\"ע המשכת תוס' אורות שבא לפרקי', וזה הוא העיקר שיתגלה בחי' תוס' וריבוי אורות אשר תוספתו של הקב\"ה מרובה על העיקר. וז\"ע אור חדש על ציון תאיר שהוא בחי' תוס' אור חדש שיאיר בחי' פנימיות אלקותו ית', שבחי' זו נק' ידידות בחי' תוקף האהבה שמזה נמשך בחי' אור חדש כו'. ויובן זה ממארז\"ל צמצם שכינתו בין שני בדי ארון, וכתיב כי בענן אראה, ונועדתי לך (אותיות ונודעתי), ולכאורה הלא כתיב מלא כל הארץ כבודו, וכתיב את השמים ואת הארץ אני מלא, ומהו הרבותא והחידוש מה שצמצם שכינתו בין שני בדי הארון והשראת השכינה שבבית המקדש, אלא שמה שמלא כל הארץ כבודו זהו רק בבחי' העלם, אבל ענין צמצם שכינתו בין שני בדי הארון שהי' מתגלה אורו ית' בין בדי הארון, כמ\"ש בלק\"ת בפ' אמור בביאור ע\"פ ונקדשתי<sup data-n=\"74\">15</sup> פ\"ב בשם הה\"מ נ\"ע. ועד\"ז יובן ענין התוס' אור שאור חדש על ציון תאיר להיות מאיר גילוי אלקותו, וכענין שכתיב ונגלה כבוד ה' וראו כל בשר כו'.\n<b>וזהו</b> מה שמסיים בזהר שם בשעתא דרוחא דכל רוחין ארים בסימא דנשמתא, פי' וענין רוחא דכל רוחין הוא ב' בחי' הנ\"ל, היינו בחי' החיות הנמשך תמיד להחיות עולמות, ובחי' תוס' אורות הוא בחי' אור חדש, כי רוחא הוא בחי' הרוח המחבר אש ומים הנ\"ל, שבלא הרוח לא הוי גלדי וע\"י הרוח אתגלידו ונעשו בבחי' ביטול, כמו הקרח אותיות חרק שהיא נקודא חדא בחי' ביטול, ועי\"ז נתקיימו שמים ובלשון המדרש נקרשו, והרי עי\"ז נעשה קיום העולם, שז\"ע בחי' חיות אלקי המחי'",[["73","14","<b>וכמשנ\"ת ביאור ד\"ז במ\"א בד\"ה מהיכן זכו ובד\"ה מי כמוכה</b>: סה\"מ תרכ\"ז ע' שפח (ד\"ה מהיכן זכו). תרכ\"ט ע' קסא-ב (ד\"ה מי כמוכה)."],["74","15","<b>בלק\"ת בפ' אמור בביאור ע\"פ ונקדשתי</b>: דף לד, ב. וראה גם לקו\"ת בלק עג, ב."]]],[2000510093,"ומהוה תמיד הוא בחי' ובטובו מחדש בכל יום תמיד מעשה בראשית, וכמ\"ש בזהר דבשעתא דההוא רוחא אסתלק כולהו מרפפין וזעין ועלמא מרתת הה\"ד המרגיז כו' ועמודי' יתפלצון, ונמצא כי צ\"ל הרוח תמיד בכדי שיהי' קיום העולם, שזהו ממש בחי' חידוש הישנות בכל יום תמיד אך זהו בבחי' העלם והסתר כנ\"ל. אבל ענין רוחא דכל רוחין הוא גילוי תוס' אורות עליונים, ונק' בחי' נשמה בזהר (או אפשר נכלל בזה גם בחי' נשמתא לנשמתא)<sup data-n=\"75\">16</sup>, וכמו למשל למטה נמצאים ד' בחי' דצח\"ם, הנה הדומם הוא בחי' האחרונה ובו החיות מועט מכל הד' יסודות, ולמעלה ממנו הוא בחי' צומח שיש בו נפש הצומחת ומקבל חיות משרשו שהרי אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר גדל, ולמעלה ממנו הוא בחי' חי שיש בו גם חיות רוח חיים וכמ\"ש תוצא הארץ נפש חי'. אך מ\"מ כל הג' בחי' אלו דצ\"ח אינם בערך המדבר, שהוא יותר גבוה מכולם ומובדל הוא בערך מהם, שהרי יש בו הדבור ונפש השכליות להשכיל השכלות כו', רק שנפש השכלית שבמדבר הוא רק להשכיל השכלות גשמי', אמנם למעלה בחי' זו היא הנק' בחי' תוס' אורות בחי' אור חדש הנ\"ל נק' בשם נשמה ע\"ד שאמר הכתוב נשמת שדי תבינם, וכמ\"ש אם ישים אליו לבו רוחו ונשמתו אליו יאסוף דהיינו בחי' רוחא ונשמתו שלמעלה שהוא בחי' גבוה מאד נעלה, ואז ארים בסימא דנשמתא, בסימו הוא בחי' המתקת הדינים לשון מתיקות ותענוג, שנמשך אור חדש מלמעלה, ולכן מתמן נפיק קלא דקלא, פי' קלא דקלא כי יש חיצוניות הקול ופנימיות הקול[ednref_19_יט], וע\"י גילוי בחי' רוחא דכל רוחין בסימא דנשמתא עי\"ז מתגלה בחי' קלא פנימאה (וז\"ש קול דודי<sup data-n=\"76\">17</sup> הנה זה בא מדלג על ההרים, וצ\"ע שלכאורה זה קאי על התורה, וקלא פנימאה הוא עומקא דליבא דתפילה כמ\"ש בסידור בד\"ה הקול קול<sup data-n=\"77\">18</sup>).\nד) <b>ובזה</b> יובן ענין שייכות הקדמת מאמר ר' יוסי ע\"פ מה ידידות לפ' לך לך, שהרי עלה קאי. והענין הוא דהנה אברהם נק' ידיד כמשארז\"ל במנחות דנ\"ג יבוא ידיד בן ידיד ויבנה ידיד לידיד בחלקו של ידיד ויתכפרו בו ידידים, בן ידיד זה אברהם שנאמר מה לידידי, ויבנה ידיד זה בית המקדש שנאמר מה ידידות",[["75","16","<b>ונק' בחי' נשמה בזהר (או אפשר נכלל בזה גם בחי' נשמתא לנשמתא)</b>: ראה סה\"מ תרל\"ג ח\"א ע' קצה: ובזהר כוללם בבחי' אחת בשם נשמתא לנשמתא [וראה בהנסמן שם]. וראה גם שם ח\"ב ע' שכח. וש\"נ."],["76","17","<b>קול דודי. . וצ\"ע שלכאו' זה קאי על התורה</b>: ראה לקו\"ת שה\"ש מא, סע\"ג. סה\"מ תרל\"ב ח\"ב ר\"ע שצה."],["77","18","<b>בסידור בד\"ה הקל קול</b>: דף יט, ג-ד.\n\n[edn_19_יט] <b>כי יש חיצוניות הקול ופנימיות הקול</b>: בשולי הגליון נרשם בגוכי\"ק: להעיר לענין פנימיות וחיצונית הקול מפנימיות וחיצוניות הלב, שמוציא הקול מהבל הלב, וא\"כ י\"ל פנימיות הקול יוצא מפנימיות הלב, שהרי גם הרוחא שמחבר חו\"ג מפרש ר\"י על התורה, וי\"ל פנימיות הקול היא תשובה שע\"י התורה מלמעלה למטה או פנימיות התורה, או לימוד התורה שאחר הקדמת התשובה, וכענין לוחות אחרונות שביום הכיפורים בע\"ת, יש בהם כפליים לתושי', והוי' יגי' חשכי."]]],[2000510094,"משכנותיך, לידיד זה הקב\"ה שנאמר אשירה נא לידידי, בחלקו של ידיד זה בנימין שנאמר לבנימין אמר ידיד ה', ויתכפרו בו ידידים אלו ישראל שנאמר נתתי את ידידות נפשי (ירמי' י\"ב). והיינו כי אברהם נק' ידיד ע\"ש שמסר נפשו ומאודו שהי' לו אהבה בידידות להקב\"ה, וכל עבודתו הי' להודיע אלקותו ית' בעולם ולהמשיך בחי' ש' הוי' וכמ\"ש ויקרא בשם ה' אל עולם. [דוגמא כמו שבית המקדש שנקרא ידידות משכנותיך ע\"ש היחוד ש' הוי' ואלקים או אד' שהי' בבית המקדש כמ\"ש והוי' בהיכל קדשו היכל בגימ' אד' שהוא בחי' היכל לש' הוי', ולכן במקדש היו קורין את השם ככתבו, ונועדתי לך שם, ונועדתי אותיות ונודעתי, ל' והאדם ידע בחי' המשכת ש' הוי']<sup data-n=\"78\">19</sup>. ולכן א\"ל ה' לך לך מארצך כו', והיינו כי הנה נת' לעיל שענין הידידות הוא בחי' תוקף האהבה, וע\"י בחי' תוקף האהבה שהי' לו לאברהם לאלקות עי\"ז רוח אמשיך רוח ואייתי רוח כמ\"ש בזח\"ב תרומה דקס\"ב ב' ע\"פ רוחו ונשמתו אליו יאסוף, שז\"ע בשעתא דרוחא דכל רוחין ארים בסימא דנשמתא שהוא בחי' המתקת הדינים (המעכבים) שיתגלה בחי' התענוג עליון ובחי' המתיקות שבשורש נשמתן למעלה בחי' מזל שבנשמה, שנש\"י עלו במחשבה וארז\"ל במד\"ר פ\"א דבראשית שמחשבתן של ישראל קדמו לכל דבר. וענין המחשבה שלמעלה הוא בחי' גבוה מאד נעלה שע\"ז נאמר כי לא מחשבותי מחשבותיכם<sup data-n=\"79\">20</sup>, שלכאורה צ\"ל מפני מה אמר כי לא מחשבותי מחשבותיכם, ולא אמר בבחי' אחרת מלבושי הנפש או מדות הנפש. והיינו מפני כי במחשבה ניכר יותר ההפרש, כי ממחשבת האדם הגם כשיחשוב כל היום לא יתהווה מזה כלום, אפילו אם יחשוב כמה, כ\"א ע\"י דיבור שיצוה לזולתו לעשות או ע\"י מעשה שיעשה בעצמו יכול לעשות איזה דבר כו' וג\"ז רק יש מיש כמ\"ש במ\"א<sup data-n=\"80\">21</sup>, אבל ע\"י מחשבת האדם לא יתהווה כלום. אבל למעלה לא מחשבותי מחשבותיכם כי במח' אחת נבראו כל העולמות כמ\"ש בזהר ואפילו עולם התחי' הכל היו כלולים במחשבה א', וענין מה שנפרט הכל בעשרה מאמרות זהו בכדי שיוכל להיות בחי' נבראים נפרדים בעלי גבול, שמבחי' המחשבה נתהוו עלמין סתימין דלא אתגליין, וע\"י שנפרטו בדבור בעשרה מאמרות עי\"ז נעשה בחי' עלמין דאתגליין עד שנברא העוה\"ז הגשמי והנבראים הגשמיים, אבל באמת נבראו הכל ע\"י מחשבה א' הכוללת כל הנבראים שנבראו בפרט אח\"כ ע\"י הדיבור, ואין בפרט אלא מה שבכלל בבחי' מחשבה אחת שבה נבראו כל העולמות שנתגלו אח\"כ ע\"י הדיבור. והנה מחשבתן של ישראל קדמו לכל דבר, היינו בבחי' מח' זו הכוללת הכל שמשם שורש ומקור הנשמה, ועל בחי' זו שבנשמה ארז\"ל אע\"ג דאיהו לא חזי מזלייהו חזי, שהוא בחי' שורש ומקור הנשמה כמו שהיא למעלה שנק' בחי' מזל ע\"ש ונוזלים מן לבנון, משא\"כ בחי' הנשמה המלובשת בגוף היא בחי' אחרונה שבנשמה, וירדה ע\"י ד' מדריגות טהורה בראת יצרת נפחת, בכדי שתוכל להתלבש בגוף האדם כו'.",[["78","19","<b>[דוגמא כמו. . ש' הוי']</b>: הגה\"ה זו נרשמה בגוכי\"ק בשולי הגליון, וכנראה שייכת לכאן."],["79","20","<b>שע\"ז נאמר כי לא מחשבותי מחשבותיכם</b>: בהבא לקמן ראה בארוכה לקו\"ת שה\"ש יז, סע\"ג ואילך. וראה גם לקו\"ת ואתחנן ב, ב. סה\"מ תרל\"ד ע' רמ. ועוד."],["80","21","<b>ע\"י מעשה שיעשה בעצמו. . רק יש מיש כמ\"ש במ\"א</b>: ראה שעהיוה\"א פ\"ב."]]],[2000510095,"<b>וזהו</b> שאמר ה' לאברם לך לך היינו לשורש נשמתך כמו שהיא למעלה שיתגלה בו שורש נשמתו שזהו בחי' גבוה מאד, וכמ\"ש בכתהאריז\"ל שגילוי שורש הנשמה גבוה יותר מבחי' גילוי אלי' ורוח הקודש (שזהו בחי' רוח לבד משא\"כ בחי' נשמה גבוה יותר הרבה, וכ\"ש לפי מה שבזהר לא חשיב רק ד' בחי' נר\"נ ונשמתא לנשמתא, שבחי' נשמתא לנשמתא כוללת בחי' חי' יחידה, שי\"ל שבגילוי בחי' נשמה כוללת נשמה חי' יחידה). ולכן אמר ב\"פ לך, שאם הי' הכוונה רק שיצא מארצו הי' צ\"ל פ\"א לך, ומהו שא' ב\"פ לך, אלא שפי' לך לך שילך עד לך בחי' שורש נשמתו. והב' כפי\"ן שבב' פעמים לך, י\"ל כנגד ב' כתרים דנעשה ונשמע שכתרו לבניו במ\"ת, כי כתר מחבר אוא\"ס ב\"ה עם האצי' או עם עולמות דבי\"ע, כל כתר של כל עולם מחבר אוא\"ס בעולם ההוא, ושני כתרים הם מלמעלה למטה ומלמטה למעלה כ\"ע דאיהו כתר מל' נעוץ תחלתן בסופן וסופן בתחלתן. אך כדי שיוכל לבוא לשורש נשמתו זהו ע\"י הארץ אשר אראך דוקא, וז\"ע שארז\"ל למה נק' שמה ארץ שרצתה לעשות רצון קונה שהוא ל' רצוא ול' רצון, פי' שכדי להיות בבחי' רצוא ותשוקה כ\"כ שיוכל להגיע ע\"י הרצוא שלו לבחי' רצון העליון ב\"ה בחי' התחילה זהו ע\"י הארץ דוקא שבה נעוץ כח התחילה, שלמעלה מבחי' ראש המתפשט כמשנ\"ת במ\"א (בד\"ה ועמדו רגליו)<sup data-n=\"81\">22</sup>, ולכן בכדי שיבוא אברהם לבחי' שורש נשמתו בבחי' ונוזלים מן לבנון הי' צריך לצאת מארצו, אל הארץ כו' שבה נעוץ כח התחילה, ושם יבוא לשורש נשמתו בבחי' ונוזלים מן לבנון כו', וגם הי' צריך לצאת מארצך וממולדתך, כמשנ\"ת לעיל שבחו\"ל נמשך ההשפעה ע\"י ע' שרים שדרך בם נמשך רק מבחי' מל' דעשי' ויצי' לבד לא יותר, וכדי שיגיע לשורש נשמתו הוצרך לעלות לארץ בחי' אשריך ארץ שמלכך בן חורין ששם מאיר מל' דבריאה ומל' דאצי'.\n<b>וזהו</b> ששייך מאה\"ז שאמר ר' יוסי ע\"פ מה ידידות ושבגמ' חגיגה די\"ב הנ\"ל ללך לך, כי ענין רוחא ורוחא דכל רוחין זהו ב' ההמשכות, רוחא הוא בחי' המחדש בטובו בכל יום תמיד מעשה בראשית בחי' חידוש הישנות, ורוחא דכל רוחין הוא בחי' תוס' אורות כענין גילוי שבבית המקדש שנק' ידידות כמארז\"ל במנחות הנ\"ל שזהו בחי' יחוד עליון גילוי פנימיות אלקות, ואברהם שנק' ג\"כ ידיד ע\"ש פנימיות אהבתו להקב\"ה אמר לו לך לך שיתגלה לו שורש נשמתו בחי' בסימו דנשמתא שזהו מבחי' רוחא דכל רוחין בחי' תוס' אורות, וזהו ע\"י הארץ דוקא.\n[ה)] <b>ועדיין</b> צריך להבין מפני מה בגמ' האריך בסיפור שהארץ עומדת על עמודי' ועמודי' על המים והמים על ההרים וההרים על הרוח והרוח בסערה וסערה בזרוע של הקב\"ה, ובזהר הזכיר רק הסמכין והרוח. והענין הוא דהנה בזהר התחיל מלמעלה למטה, והתחיל בשמים שעשוי מאש וממים ואמר דקיימא ברוחא,",[["81","22","<b>כמשנ\"ת במ\"א (בד\"ה ועמדו רגליו)</b>: סה\"מ תר\"ל ע' שכ. וראה גם מאמרי אדה\"ז תקע\"א ע' ס. נביאים ע' רסה. אוה\"ת בראשית (כרך ו) תתרכו, ב. סה\"מ תרל\"ב ח\"א ע' קז. תרל\"ב ח\"ב ע' שסז. תרל\"ג ח\"א ע' קטז."]]],[2000510096,"וקיום העולם שכוונתו על הארץ כנ\"ל אמר דקיומו על סמכין שהם העמודים שבגמרא, שנתבאר לעיל שז\"ע בחי' נה\"י כליות יועצות כו'. וסיים בשעתא דרוחא דכל רוחין, י\"ל שזהו כוונתו על הסערה שהזכיר בגמ'. ויש לבאר זה ע\"פ מה שארז\"ל ברבות ס\"פ עקב ע\"פ ה' בסופה ובסערה דרכו (נחום א' ב' בפסוק כתיב ובשערה בשי\"ן שמאלית), בסופה זה משה שנאמר ותשם בסוף על שפת היאור, ובסערה זה אלי' שנאמר ויעל אלי' בסערה השמי' (מ\"ב ב') אותה שעה הוא בא, ע\"ש דקאי על תחה\"מ, וא\"כ י\"ל שזהו בחי' רוחא דכל רוחין שבזהר שזהו בחי' אויר אור יו\"ד, מקור בחי' הרוח דאלי'. וע' בזהר פקודי דרל\"ח ב' בענין העולה קודש קדשים ברזא דרוח עילאה, בגין דתלת רוחין קשורים כחדא, רוח הקדש מל', רוח דלגו באמצעיתא דאקרי רוח חכמה ובינה, והיינו ת\"ת<sup data-n=\"82\">23</sup>, רוח עילאה דאיהו סתים בחשאי, פי' רוח דבינה, דבי' קיימין כל רוחין קדישין, שעל ידו חיים כמ\"ש המק\"מ בשם נ\"ב. וי\"ל שנק' קודש קדשים ע\"ש התגלות עתיק שבבינה, שז\"ע אוירא אור יו\"ד, וע' מענין אוירא דכיא בתוספתא דבשלח ד\"ן בבה\"ז פ' בשלח. וענין ארים בסימא דנשמתא הוא המתקת הנשמה, י\"ל שזהו בחי' נשמות חדשות שנמשכות מהבינה, שי\"ל שזהו ע\"ד נשמה יתירה שפי' בפרד\"ס בעה\"כ בשם רע\"מ שהיא מהכתר, מ\"מ י\"ל שנמשכת מבינה שנק' נשמה, שז\"ע נשמתא לנשמתא ואז נפקי קלא דקלין הוא בחי' קלא פנימאה קלא דבחשאי[ednref_20_כ] הנ\"ל שהוא מבחי' רוח דעולה שהיא קדש הקדשים. והגם שבזהר שא' בשעתא דרוחא דכל רוחין ארים בסימא כו' כוונתו על חצות לילה שאז משתעשע הקב\"ה עם הצדיקים בג\"ע, י\"ל שהארה מבחי' רוח זה מאיר בהגנים שבבי\"ע, ולע\"ל כשיהי' גילוי הבינה יאיר מבחי' רוח דכל רוחין ששרשו מבחי' אוירא דכיא, וזהו מ\"ש ונתתי רוחי בכם וחייתם, שהוא בתחה\"מ. ובגמ' דחגיגה[ednref_21_כא] להיות כי התחיל מלמטה למעלה שהתחיל בארץ שהוא סוף דכל דרגין בבחי' יושר לזה ביאר בה כוונת תחילת הנעיצה יותר,",[["82","23","<b>רוח דלגו באמצעיתא דאקרי רוח חכ' ובינה והיינו ת\"ת</b>: ראה בהגהות מהרח\"ו לזח\"ב שם: שהת\"ת נמשך מחכ' ובינה. וראה אוה\"ת לך לך תרעח, ב: הת\"ת שנק' רוח חו\"ב לפי שנמשך מחו\"ב.\n\n[edn_20_כ] <b>בחי' קלא פנימאה קלא דבחשאי</b>: בשולי הגליון נרשם בגוכי\"ק: בסידור אין אמר<sup data-n=\"1617\">88</sup>, קלא דאשתמע וקלא דלא אשתמע, פנימיות הקול מבינה חיצוניות הקול ז\"א, בקול מה שבקול.\n\n[edn_21_כא] <b>ובגמ' דחגיגה. . התחיל מלמטלמ\"ע. . לזה ביאר בה כוונת תחילת הנעיצה יותר</b>: בגוכי\"ק מעיר ע\"ז: י\"ל שלענין נעיצת התחילה ג\"כ אינו דומה העלאת אברהם להמשכת נש\"י ע\"י התומ\"צ, שאברהם ע\"י שהי' ע\"י עובדות לזאת גם בארץ לא בא רק לשורשו שבאצי', ולכן ר\"י כשהקדים בזהר פסוק מה ידידות ודרש מאמר זה עצמו שבגמ', לא הזכיר רק בחי' רוחא עילאה שמקיים שמים שמאש וממים, ושורש רוח זה הוא מחו\"ב כמ\"ש המק\"מ בויקהל דרל\"ח בשם נ\"ב, ואח\"כ הזכיר רוחא דכל רוחין ג\"כ, והגם שזהו אינו שייך כ\"כ להקדמת לך לך כו' מ\"מ יש לומר שמ\"מ שייך זה לנעיצת התחילה שהגיע אברם ע\"י הארץ, וכנ\"ל שי\"ל שז\"ע הסערה ע\"פ המד\"ר הנ\"ל. אך ע\"י התומ\"צ שעושים גם בחו\"ל שהתורה היא למעלה מזמן, וגם במצות י\"ל כן, הגם שהם בזמן ומקום, מ\"מ הרי כתיב וזאת המצוה כו' לעשות בארץ ואח\"כ נאמר שמע ישראל שהיא חובת הגוף ונוהגת גם בחו\"ל, ומ\"מ כתיב בארץ, וע' בלק\"ת בפ' ואתחנן<sup data-n=\"1618\">92</sup> ע\"פ זה שתירץ שג\"ע נק' ארץ, וע\"י המצות תוס' אורות בג\"ע, ומ\"מ זהו ע\"י התורה שהחכ' תחי' בעלי', וא\"כ י\"ל כן במל' דאצי' שמאיר בבריאה ג\"ע העליון, שע\"י המצות הגם שעושים אותם בחו\"ל נק' ג\"כ בארץ, ומכ\"ש לפי מה שנת' לעיל שהארץ ניתן במתנה ברוחניות, (רק שי\"ל שזהו כמו תפילה שצ\"ל דרך ארצם כמו\"כ מצות דוקא בזמן ומקום, והתלויות במקום אין עושים עכשיו) (ואברהם הגם שהי' בארץ וכתי' ג\"כ לך אתננה מ\"מ לא נצטוה בקיום המצות) הנה ע\"י קיום התומ\"צ מגיעים לבחי' נעיצת התחילה יותר ולכן בגמ' הזכיר גם בחי' זרועו של הקב\"ה סובב הכללי לפי ששם אינו שייך להקדמת יציאת אברם מחוץ לארץ, כ\"א ביאר מעלת הארץ בעצמה לכן ביאר כוונת נעיצת התחילה יותר."],["1617","88","<b>בסידור אין אמר</b>: סידור עם דא\"ח (ד\"ה אין אומר ואין דברים) קפא, ב."],["1618","92","<b>וע' בלק\"ת בפ' ואתחנן</b>: דף ט, א."]]],[2000510097,"והיינו מה שאמר שהארץ עומדת על העמודים הם נה\"י דז\"א שמנה\"י דז\"א נמשכין מוחין לנוק', ואח\"כ אמר מים והרים ורוח כוונתו על חג\"ת, שע\"י רוח דת\"ת מתקיים שמים הם בחי' חו\"ג שהם בחי' מים חסד, והרים אלו האבות כמ\"ש בתקונים ע\"פ שמעו הרים את ריב ה' הרים אלו אבהן, חג\"ת<sup data-n=\"83\">24</sup>, וע' בפרד\"ס בערך הר שכ' ולשון הר מורה על ענין גבוה, ולכן מורה על האבות כי הם גבוהים ועליונים, וע' בלק\"ת בפ' תצא בד\"ה כי ההרים<sup data-n=\"84\">25</sup> ימושו שפי' כן גם ברבות בחוקתי ס\"פ ל\"ו, וי\"ל שעיקר הר הוא בחי' יצחק שנעקד ע\"ג הר המורי', ומפני כי אברהם עקדו ויעקב עדיין לא נולד א\"כ הי' כלול בו, לכן נק' כל האבות הרים. ורוח בסערה י\"ל שהסערה בקדושה הוא בחי' רוחא דכל רוחין, ששרשו מבחי' אוירא דכיא שפי' בבה\"ז בתוס' דבשלח<sup data-n=\"85\">26</sup> שזהו בחי' חכ' דא\"ק, סערה בזרוע של הקב\"ה שנאמר ומתחת זרועות עולם הכוונה על סוכ\"ע דכלליות שכוללת וסובבת כל הד' עולמות אבי\"ע בשווה (ולפי מה שפי' הערוך שזהו ע\"ש הפסוק דלך זרוע עם גבורה, י\"ל שענין הגבורה הוא בחי' הצמצום ומקום פנוי, אך לכאורה אינו ענין לכאן), וי\"ל שז\"ע נעוץ תחלתן בסופן וסופן בתחלתן.\n[ו)] <b>אמנם</b> עדיין צ\"ל האם נאמר שישראל שבחו\"ל אין להם דביקות בשרשן ח\"ו. אך הענין הוא דהנה קיים אברהם כל התורה כולה, אך הוא קיים אותה ברוחניות ע\"י עובדות שלו, לכן בכדי שיגיע לשורש נשמתו א\"א כ\"א ע\"י הארץ המכוונת נגד בחי' הארץ העליונה, אבל ע\"י שנכנס בברית עם הקב\"ה נתן לו הארץ העליונה במתנה שז\"ע מ\"ש לזרעך נתתי את הארץ, ולכן נק' ישראל ארץ",[["83","24","<b>גג\"ת</b>: גדולה גבורה תפארת. — ראה בארוכה ע\"ז לקו\"ת עקב יז, ג. אוה\"ת וירא צ א ואילך. ואתחנן (כרך ו) ע' ב'רכו. עקב ע' תרכט-ל. סה\"מ תרכ\"ז ע' קצח. וש\"נ."],["84","25","<b>בלק\"ת בפ' תצא בד\"ה כי ההרים</b>: דף מ, א."],["85","26","<b>שפי' בבה\"ז בתוס' דבשלח</b>: ביאוה\"ז לאדהאמ\"צ שם דף מד, א."]]],[2000510098,"חפץ כמ\"ש ואשרו כו' כי תהיו אתם ארץ חפץ, והתומ\"צ שניתן לנו זהו בחי' אור זרוע לצדיק כמ\"ש במד\"ר פ' שלח לך ס\"פ י\"ז זרע הקב\"ה התורה והמצות להנחילם לישראל לע\"ל ולא הניח דבר שלא עשה בו מצוה, ולכן ע\"י התומ\"צ שנתן לנו יכולים לבוא לבחי' שורש נשמתו גם בחו\"ל, ואם כי בודאי גדלה מעלת הארץ המכוונת לארץ העליונה, מ\"מ גם בחו\"ל ע\"י תורה ועבודה וגמ\"ח יכולים להגיע לשורש הנשמה שבבחי' ונוזלים מן לבנון.\n<b>וזהו</b> שאמר ברבות רות הנ\"ל כמה גדול כוחה של צדקה וגמ\"ח שאין חסים לא בצל כו' כ\"א בצל מי שאמר והי' העולם שאברהם ע\"י שהרבה חסד בעולם, כמ\"ש ויטע אשל בבאר שבע, אש\"ל ר\"ת אכילה שתי' לוי', שהי' מאכיל ומשקה ומלוה אותם שז\"ע השפעת החסד, וכתיב באברהם והאמין בה' ויחשבי' לו צדקה, עי\"ז בצל כנפיך יחסיון שאינו חס לא בצל כו' עד לא בצל כנפי חיות שהם מרכבה דבריאה, בהיות ידוע כי אברם ע\"י העקידה נתעלה בבחי' אצי' כמשנ\"ת בד\"ה הנה אנכי כורת ברית<sup data-n=\"86\">27</sup>, לכן זהו למעלה מבחי' כנפי החיות דבריאה כ\"א בצל כנפיך בצל מי שאמר והי' העולם.\n<b>אמנם</b> כ\"ז הי' ע\"י הארץ, כי בהיותו בחו\"ל לא האיר בנפשו רק מבחי' מל' דיצי' לא יותר, ולכן כשבא לארץ אז אמר ואנכי עפר ואפר פי' שבא לבחי' הביטול דמרכבתא עילאה דחסד דאצי' שאז הרגיש בנפשו שהוא בבחי' עפר ואפר לגבי שרשו חסד שבאצי'[ednref_22_כב] כמ\"ש בסש\"ב באגה\"ק<sup data-n=\"87\">28</sup>, כי ע\"י הארץ האיר בו מבחי' מל' דאצי', וע\"י החסד שהרבה שאמרה מדת החסד כל ימי היות אברם בארץ לא הוצרכתי אני לעשות מלאכתי שהרי אברהם עומד שם במקומי וישמר משמרתי כמ\"ש הפרד\"ס בשער הכינוי' פ\"ד בשם ס' הבהיר, דקדק לאמר בארץ להיות כי ע\"י הארץ בא לבחי' זו, וזכה ג\"כ להיות בצל כנפיך, כי בלא הארץ לא הי' יכול לבוא לבחי' זו. אבל ע\"י מ\"ת וע\"י שלזרעך נתתי את הארץ העליונה וגם בהיותם בארץ כו' לא מאסתים בגלות בבל כו', שז\"ע הכריתות ברית דמשה[ednref_23_כג] כו' כמשנ\"ת בד\"ה הנה אנכי כורת ברית הנ\"ל<sup data-n=\"88\">29</sup>, עי\"ז יכולים להגיע לשורש הנשמה גם בחו\"ל",[["86","27","<b>כמשנ\"ת בד\"ה הנה אנכי כורת ברית</b>: סה\"מ תר\"ל ע' קו."],["87","28","<b>כמ\"ש בסש\"ב באגה\"ק</b>: סי' טו (קכא, א ואילך). וראה גם סה\"מ תר\"ל ס\"ע נו-נז."],["88","29","<b>כמשנ\"ת בד\"ה הנה אנכי כורת ברית הנ\"ל</b>: סה\"מ תר\"ל שם ע' קה ואילך.\n\n[edn_22_כב] <b>הרגיש בנפשו שהוא בבחי' עפר ואפר לגבי שרשו חסד שבאצי'</b>: על הגליון נרשם בגוכי\"ק: בד\"ה דוד זמירות קרית להו. — וכנראה הכוונה למ\"ש בקו\"א לתניא שם (קס, ב): שבריבוי העולמות וכל צבאם כו' כולם בטלים במציאות לגבי דקדוק א' מדקדוקי תורה שהוא עומק מחשבה עליונה וחכמתו ית'.\n\n[edn_23_כג] <b>וגם בהיותם בארץ כו' לא מאסתים. . שז\"ע הכריתות ברית דמשה</b>: בגוכי\"ק מעיר ע\"ז: לענין מה שנת\"ל שהכריתת ברית דמשה הי' שגם בהיותם כו' לא מאסתים בבבל, לכן גם בחו\"ל יכולים לידבק בשורש נשמתם ע\"י תומ\"צ, צ\"ע דעיקר הכריתות ברית דמשה שנאמר בפ' כי תשא זהו על תשובה דוקא, שעי\"ז גם מבחי' פלא יומשך שיהי' ונפלינו אני ועמך דוקא, כמשנ\"ת בד\"ה הנה אנכי כורת ברית. לכן י\"ל שז\"ע הכריתות ברית שנאמר בפ' משפטים שקרא לפניהם דברי הברית וחלק הדם, וחצי הדם נתן באגנות וזרק על העם, וחצי הדם זרק על המזבח, שי\"ל שזהו כריתות ברית דתורה ותפילה, כמ\"ש תחלה ועבדתם ועבודה שבלב זו תפלה, שבכל מקום שיהיו יוכלו להגיע ע\"י תומ\"צ ותפילה לשורש נשמתם."]]],[2000510099,"ע\"י תורה ועבודה וגמ\"ח כו', ועכשיו תפלה במקום קרבנות, שז\"ע הסולם שמלמטה למעלה, וע\"י תורה מלמעלה למטה.\n<b>גם</b> י\"ל שענין החסד דאברהם זהו כמ\"ש כי חסד חפצתי ולא זבח שבחי' זו גבוה יותר מקרבנות<sup data-n=\"89\">30</sup>, אך כ\"ז הוא ע\"י הארץ שאז הי' יכול להיות מרכבה לחסד דז\"א דאצי' שהיא בחי' כלי לבחי' רב חסד דא\"א ולכן חסד חפצתי (וי\"ל חסד שבבחי' חפץ היינו בחי' רצון, בחי' כתר בכלל, דאין לחלק פה בין חפץ לרצון כו'), ולא זבח בחי' קרבנות. אך ע\"י מ\"ת שניתנה לנו תורה ומצות[ednref_24_כד] שהם בחי' המשכות אלקות כמארז\"ל ע\"פ שמן תורק שמך כל המצות שעשו האבות ריחות היו אבל אנו שמן כו' דבר שמריקין כו' פי' ריח הוא רק הארה בעלמא, אבל אנו שמן תורק דבר שמריקים שהוא בחי' המשכה עצמיות, שמצות המלך הם בחי' כלים להשראת האור וע\"י הפתילה נאחז האור בחי' כי ה' אלקיך אש אוכלה הוא, ושרשו מבחי' צור בחי' גבורה דעת\"י שורש קו המדה בוצינא דקרדוניתא שורש כל המדידות שיומשך אורות בכלים, ועי\"ז שמן תורק שנמשך המשכת המוחין בכלים בט\"ס דז\"א שנק' רמ\"ח פקודין רמ\"ח איברין כו', וכנודע שהאבר ממשיך חיות הנפש, ואינו דומה לכלי סתם כו'. וגם י\"ל שהשמן הוא בחי' ח\"ס, שמן משחת קדש, שמושח את הקדש כו' והארץ ניתן ברוחניות לכן גם בחו\"ל אפשר להגיע לשורש הנשמה. ומ\"מ ע\"י הסולם דתפילה צ\"ל דרך ארצם דוקא, לא מבעיא למ\"ד תפלות אבות תקנום ודאי מה שצ\"ל דרך ארצם שהרי אברהם[ednref_25_כט] עצמו הגיע לזה ע\"י הארץ דוקא, [אלא] אפי' למ\"ד כנגד תמידים תקנו, ג\"כ צ\"ל דרך ארצם כי התמידים היו בארץ. והטעם י\"ל כי בבחי' שהיא מלמטלמ\"ע הדקדוק יותר כנודע<sup data-n=\"90\">31</sup> ממ\"ש במ\"א מי יעלה בהר ה' נקי כפים דוקא כו', משא\"כ ע\"י התורה שמלמעלה למטה אין מונע כלל,",[["89","30","<b>כי חסד חפצתי ולא זבח שבחי' זו גבוה יותר מקרבנות</b>: ראה בארוכה סה\"מ תרכ\"ז ע' קלד ואילך [ובהנסמן שם בתחילת המאמר]. תרכ\"ט ע' סט ואילך. וש\"נ."],["90","31","<b>מלמטלמ\"ע הדקדוק יותר כנודע ממ\"ש במ\"א. . נקי כפים דוקא</b>: ראה מאמרי אדה\"ז הנחות הר\"פ ע' קנח. תקס\"ט ע' קלא. קמא ואילך. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשפו-ז. תתלה ואילך. אמרי בינה שער הק\"ש עא, ד. עג, ד ואילך. סה\"מ תרל\"ג ח\"ב ע' תכא. ועוד.\n\n[edn_24_כד] <b>ולא זבח בחי' קרבנות אך ע\"י מ\"ת. . תורה ומצות</b>: בשולי הגליון נרשם בגוכי\"ק: והענין מענין עולת תמיד שני<sup data-n=\"1619\">98</sup> מקריבין אותה שערבה לו כך העשוי' בהר סיני דוקא ולא הקרבנות דנח, ולכן לא זבח י\"ל הקרבנות דנח, אבל ע\"י מ\"ת שערבה יותר.\n\n[edn_25_כט] <b>למ\"ד תפלות אבות תקנום. . שהרי אברהם</b>: בשולי הגליון נרשם בגוכי\"ק: ע' בס' יוחסין שאברהם תיקן כל הג' תפלות, ומ\"ש יצחק תיקן מנחה שהי' זהיר בה יותר."],["1619","98","<b>עולת תמיד שני</b>: כ\"ה בגוכי\"ק."]]],[2000510100,"והעיקר כי ע\"י התורה כל העוסק בתורת עולה כאילו הקריב עולה גם עכשיו שאינו בזמן הראוי ומקום הראוי כי התורה היא למעלה מזמן ומקום כו', לכן ע\"י ממשיכים גם עכשיו שיודבק בשורש נשמתו בחי' מזלייהו חזי שורש ומקור הנשמה כו', שבחי' זו גבוה יותר מרוח הקודש וגילוי אלי' שעי\"ז נמשך מבחי' רוחא דכל רוחין העולה קדש קדשים כו'."],[2000510101,"<h3>ויאמר גו' לך לך (ב)</h3>\n<b>בס\"ד</b>\n<b>ויאמר</b> כו' לך לך<sup data-n=\"91\">1</sup> מארצך כו' אל הארץ כו'. ואיתא בספרים<sup data-n=\"92\">2</sup> ששורש נש\"י מעולם האחדות (הכוונה על עולם האצי', הגם שרוב נשמות הם מבי\"ע וכ\"ש נשמות שבדורותינו אלו בעקבות כו' מ\"מ שורש כולם מאצי'<sup data-n=\"93\">3</sup>, וזהו נשמה שנתת כו', רק שבכדי שתתלבש בגוף ירדה בבחי' בראת כו' בי\"ע עד ואתה נפחת ויפח באפיו כו'), וידוע כי דבר שבקדושה אינו נעקר ממקומו לגמרי<sup data-n=\"94\">4</sup> לכן עיקר הנשמה נשארה למעלה (כי מה שירדה להתלבש בגוף זהו רק הארה ומקצת מהנשמה, שהרי המלאך בשליש העולם עומד<sup data-n=\"95\">5</sup> כ\"ש נשמה שגבוה יותר כו', לכן עיקרה היא למעלה, ועל בחי' זו אמרו אע\"ג דאיהו לא חזי מזלייהו חזי כו'), וזהו שאמר לאברם לך לך שבכדי שידבק בשרש נשמתו שלמעלה זהו ע\"י הארץ אשר אראך דוקא, כי בהיותו בעבר הנהר או באור כשדים לא הי' יכול לידבק בשורש נשמתו.",[["91","1","<b>ויאמר כו' לך לך</b>: המאמר מיוסד על ד\"ה זה באוה\"ת לך לך (כרך ד) תערה, א ואילך. חלק מהמאמר (פרקים ב-ה) מיוסד על ד\"ה בזוה\"ק כו' ר' יוסי פתח מה ידידות להצ\"צ הנדפס לקמן בהוספות. מאמר הצ\"צ מיוסד על ביאוה\"ז לאדהאמ\"צ ח, ג ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ע' נא ואילך. לפרק א' מהמאמר ראה ד\"ה ויאמר גו' לך לך תשכ\"ה (נדפס בקונ' בפ\"ע — קה\"ת תשס\"א).\nמאמר זה נרשם בגוכי\"ק בעפרון לאחרי המאמר שלפנ\"ז, והוא (כנראה) מהדורא בתרא מהמאמר. ונעתק עוה\"פ בכת\"י הר\"ש סופר עם הוספות בגוכי\"ק. [במאמר שלפנ\"ז (מהדו\"ק) ישנם כו\"כ ענינים שלא הובאו במאמר דידן, אך לאידך נוספו כאן כו\"כ ענינים שלא הובאו שם]."],["92","2","<b>ואיתא בספרים</b>: ס' תורת משה להר\"מ אלשיך, וס' פנים יפות להרה\"ק ר' פנחס הורביץ בעמח\"ס ההפלאה. הובאו באוה\"ת לך לך שם, ובמאמר שלפנ\"ז בשוה\"ג, והבא לקמן (עד התיבות: בשורש נשמתו) הוא תוכן דברי האלשיך שם עם הוספות בין חצאי עיגול."],["93","3","<b>נשמות. . שורש כולם מאצי'</b>: ראה לקו\"ת שה\"ש יט, ג."],["94","4","<b>כי דבר שבקדושה אינו נעקר ממקומו לגמרי</b>: כ\"ה באלשיך שם הובא באוה\"ת לך לך שם תרעה, א. וראה גם אגה\"ק ביאור לסי' כז (קמז, א). סה\"מ תרכ\"ט ע' פב. תרל\"ד ע' לט. וע' קעה. המשך מים רבים תרל\"ו פי\"ג (ע' יט). סה\"מ תר\"פ ע' י. לקו\"ש חל\"ב ע' 24. סה\"ש תשמ\"ז ח\"א ע' 376. [והוא ע\"פ ע\"ח של\"ד פ\"ג. של\"ה פ\"א. שמ\"ז פ\"ו. פרדס שי\"ד פ\"א. לקו\"א להה\"מ סו\"ס קלט (לג, ד)]."],["95","5","<b>עיקר הנשמה נשארה למעלה. . המלאך בשליש העולם עומד</b>: ראה בכ\"ז לקו\"ת שה\"ש טז, ד. וראה גם לקו\"ת האזינו עא, ד."]]],[2000510102,"<b>וצ\"ל</b> הלא רוב ישראל הם בחו\"ל האם נאמר שאין להם ח\"ו דביקות בשרש נשמתן שא\"א לומר כן, ואם נאמר שגם בחו\"ל אפשר לידבק בשורש נשמתו למה הוצרך אברם לצאת מארצו אל הארץ כו'.\n<b>ויובן</b> בהקדם מ\"ש כשושנה בין החוחים כן רעייתי בין הבנות, רעייתי קאי על נש\"י, ובזמן שרעייתי בין הבנות אז כבי' שושנה בין החוחים, כי גלו לבבל שכינה עמהם, אמנם הנה נודע כי מל' דאצי'<sup data-n=\"96\">6</sup> מעולם לא ירדה להתלבש בע' שרים, ורק מל' דעשי' ויצי'<sup data-n=\"97\">7</sup>, וע\"ז אמרו שכינה עמהם להשפיע להם ולאגנא עלייהו, שבזמן שהם תחת השר מקבלים ההשפעה דרך בו ולכן בהכרח שתתלבש מבחי' השוכן אתם כו'. אמנם כ\"ז הוא רק מבחי' מל' דעשי' ומל' דיצי' לא יותר, כי על מל' דאצי' נאמר וכבודי לאחר לא אתן כו' (זהו ע\"פ קבלת האריז\"ל ולא כמ\"ש בס' אור נערב<sup data-n=\"98\">8</sup>). והטעם בזה יובן ע\"פ מ\"ש בע\"ח שבאצי' לא יגורך רע, ובבריאה רובו טוב וביצי' מחצה על מחצה ובעשי' רובו רע, ולכן מדור הקליפות הם ביצי', ונמצא כי ממילא מובן שרק ממל' דיצי' יכול להתלבש בתמידות בע' שרים בכדי להשפיע לישראל, אבל לא יותר. ועוד יש לומר טעם בזה דהנה אבא מקננא באצי' בחי' יו\"ד של שם, ואימא מקננא בבריאה ה' ראשונה, וביצי' שית ספירן ונודע כי יניקתם הוא רק מז\"ת, כמו שמהידים גדילים צפרנים, ומהעודפי' על הבשר מקבלים יניקה, וזהו שממית בידים תתפש שמידים מקבלת גם השממית, אבל מג\"ר אינם יכולים לקבל וכמ\"ש ימותו ולא בחכמה, וגם מג' ראשונות שבמדות ג\"כ אי אפשר להם לקבל כמ\"ש במ\"א<sup data-n=\"99\">9</sup>, לכן מובן מה שרק מל' דיצי' מתלבש בע' שרים כו'. ובזה יובן בכלל מה שאמר לאברם שבכדי שיודבק בשורש נשמתו זהו ע\"י הארץ דוקא, ובהיותו בחו\"ל א\"א לו לדבק בשורש נשמתו כו'.",[["96","6","<b>ויובן בהקדם. . נודע כי מל' דאצי'</b>: הבא לקמן עד קרוב לסוף הפרק מיוסד על ביאור לד\"ה ואני אראה בשונאי בס' מאמרי אדה\"ז תקס\"ד ע' רמה. ובתוס' הגהות באוה\"ת דרושים לשמע\"צ ע' א'תתכח-ט. והובא גם באוה\"ת לך לך שם תרעה, א ואילך."],["97","7","<b>מל' דאצי' מעולם לא ירדה להתלבש בע' שרים ורק מל' דעשי' ויצי'</b>: ראה אוה\"ת לך לך שם: ואף גם מלכות דבריאה אינה יורדת בתמידות כ\"כ למטה להתלבש בע' שרים רק לפרקים. ובמאמרי אדה\"ז תקס\"ד שם: מל' דבריאה להיותו רובו טוב עדיין, ג\"כ לא תוכל לסבול לשכון בנוגה דעשי' ואינה מתלבשת כ\"כ בנוגה רק בהארה מועטת מאד בלבד."],["98","8","<b>(זהו ע\"פ קבלת האריז\"ל ולא כמ\"ש בס' אור נערב)</b>: ראה אוה\"ת דרושים לשמע\"צ שם ע' א'תתכט: ולפי פי' הרמ\"ק בס' אור נערב מתגלה השפע בהשרים עצמן, וזה אינו לפי קבלת האריז\"ל וכמ\"ש וכבודי לאחר לא אתן, אלא שנמשך השפע גם בתוך מל' דעשי' המלובשת בהן. ע\"כ. וכן הובא בשם הרמ\"ק בס' אור נערב בלקו\"ת דרושים לשמע\"צ צב, ג. מאמרי אדה\"ז תקס\"ד שם ע' רמה. תקע\"א ע' קכו. אוה\"ת לך לך שם תרעה, ב. דרמ\"צ קצח, א. ביאוה\"ז להצ\"צ ח\"א ע' תמה. סה\"מ תרע\"ח ע' שנב. — בדפוסים שלפנינו מס' אור נערב לא הובא ענין זה [ראה אג\"ק כ\"ק אדמו\"ר חי\"ב ע' שכג], אך נמצא בשם הרמ\"ק בס' אשל אברהם למהר\"א אזולאי. ובס' טוב הארץ למהר\"נ שפירא פרק מעלות התפילות בא\"י (ירושלים, תרנ\"א דף כב, ב). וראה מ\"ש בזה בקובץ העו\"ב גל' תתכד ע' לד ואילך."],["99","9","<b>מג\"ר אינם יכולים לקבל. . וגם מג' ראשונות שבמדות. . כמ\"ש במ\"א</b>: סידור עם דא\"ח נו, ג. תו\"א וישלח כו, ב."]]],[2000510103,"ב) <b>וביאור</b> הענין יובן ע\"פ משארז\"ל במד\"ר למה נק' שמה ארץ שרצתה כו', פי' שרצתה ל' רצוא ול' רצון, פי' רצון לפי שנעוץ תחלתן בסופן ונעוץ סופן בתחלתן, ולכן היא בבחי' רצוא ותשוקה לאוא\"ס ב\"ה וכמ\"ש למען יזמרך כבוד כו' נהורא תתאה קארי תדיר לנהורא עילאה ולא שכיך כו'. ויובן זה ע\"פ מארז\"ל תניא ר' יוסי אומר אוי להם לבריות שרואות ואין יודעות מה הן רואות כו' הארץ על מה עומדת על העמודים שנאמר המרגיז ארץ ממקומה ועמודי' יתפלצון, עמודי' על המים, המים על הרוח, רוח בהרים, הרים בסערה<sup data-n=\"100\">10</sup>, וסערה תלוי' בזרועו של הקב\"ה, שנאמר ומתחת זרועות עולם.\n<b>והנה</b> מאמר זה אמר ר' יוסי בזהר ג\"כ<sup data-n=\"101\">11</sup>, רק שם נאמר בקיצור יותר, שא' כד ברא קוב\"ה עלמא עביד שמיא מאש וממיא מתערבים כחדא ולא הוי גלדי לבתר אתגלידו ברוחא עילאה, ומתמן שתיל עלמא לקיימא על סמכין, וכולא קאים באורייתא כד משתדלין ישראל באורייתא מתקיים עלמא. והיינו כמ\"ש במד\"ר אלה תולדות השמים כו', אלה בזכות מי נבראו ובזכות מי הם עומדים בזכות ואלה שמות בני ישראל, ואלה בזכות מי נבראו כו' בזכות אלה העדות החוקים והמשפטים, וכן אמרו עוד במד\"ר אמר הקב\"ה העולם ומלואה לא נברא אלא בזכות התורה שנאמר ה' בחכמה יסד ארץ, וכן אמרו במשנה על ג' דברים העולם עומד על התורה ועל העבודה ועל גמילות חסדים, והעיקר היא התורה שהרי עבודה וגמ\"ח נאמר ג\"כ בתורה וגם התורה היא קו האמצעי.\n<b>ויובן</b> זה ע\"פ מה שנבין תחלת דבריו שאמר עביד קוב\"ה שמיא מאש וממיא וכן אמרו במד\"ר נטל הקב\"ה אש ומים ופתכן זה בזה ומהם נעשו שמים, פי' הערוך פתכן ערבן ובלבלן, ולכן בתיבת שמים יש אש ומים, מים בשלימות והשי\"ן זהו מתיבת אש, והאל\"ף מתיבת אש יוצא מקמץ שתחת השי\"ן, כי קמץ מוציא אל\"ף<sup data-n=\"102\">12</sup> שזהו מהאותיות שמשלים לס\"ר אותיות שבתורה כנודע מר\"ת ישראל יש ס' רבוא אותיות לתורה, שהאותיות שיוצאין מהנקודות קמץ וחיריק וכדומה משלימים לס\"ר אותיות<sup data-n=\"103\">13</sup>. והענין הוא דכתיב כי אמרתי עולם חסד יבנה, ויש בזה ב' פי'<sup data-n=\"104\">14</sup> הא' שצריכים לבנות",[["100","10","<b>המים על הרוח, רוח בהרים, הרים בסערה</b>: בחגיגה יב, ב שם [וכן הובא לעיל במאמר שלפנ\"ז]: מים על ההרים. . הרים ברוח. . רוח בסערה."],["101","11","<b>והנה מאמר זה אמר ר' יוסי בזהר ג\"כ</b>: בהבא לקמן עד סוף פ\"ה ראה ד\"ה בזוה\"ק כו' ר' יוסי פתח להצ\"צ שם. וראה גם ביאוה\"ז לאדהאמ\"צ שם ח, ג ואילך. הובא באוה\"ת לך לך שם."],["102","12","<b>בתיבת שמים. . והאל\"ף מתיבת אש יוצא מקמץ שתחת השי\"ן כי קמץ מוציא אל\"ף</b>: ראה פירש\"י נדרים לז, ב: מה שקורין כו' שמים דלא כתבינן שא מים אל\"ף בין שי\"ן למ\"ם כו' הלכה למשה מסיני דנקראין הכי. ובפי' הר\"ן שם: שאע\"פ שאין בהם אל\"ף נקראים כאילו היתה בהם. [וראה בהנסמן בהערה שלאח\"ז]. וראה הערת כ\"ק אדמו\"ר בסה\"מ תש\"א ע' 11: ראה ג\"כ בזה בספרי שמות גיטין: בית שמואל שמות אנשים — ואלק. אהלי שם שם כלל יו\"ד ס\"ה. קב נקי שם. ועוד."],["103","13","<b>שהאותיות שיוצאין מהנקודות. . משלימים לס\"ר אותיות</b>: ראה לקו\"ת בהר מא, ב: אף שבתורה אין נמצא ס\"ר אותיות, היינו מפני אותיות המשך שהם אותיות אהו\"י שבכלל הנקודות שאינן בכתב אבל ישנן במחשבה, שהקמץ הוא אל\"ף והחירק הוא יו\"ד (וכדפרש\"י ספ\"ו דכתובות גבי ינחם כתיב כאילו כתיב ינאחם), אך איזו מהנקודות הם אינו ידוע. וראה גם סה\"מ תרכ\"ז (הוצאת תש\"ס) ע' קעא. תרכ\"ט ע' לב. תרל\"ג ח\"א ע' כג. ח\"ב ע' שסו."],["104","14","<b>עולם חסד יבנה ויש בזה ב' פי'</b>: ראה יהל אור להצ\"צ ע' שיד. סה\"מ תרכ\"ז ע' קמ. תרכ\"ט ע' עג. תרל\"ד ע' נד. וראה גם לקו\"ת האזינו עו, ב. שה\"ש יא, ד."]]],[2000510104,"החסד, או שע\"פ החסד נבנה העולם. אמנם הנה נודע כי מהחסד לבד לא הי' יכול להיות התהוות העולמות, וכמובן ממלכותא דארעא שהיא כעין כו' שע\"פ החסד לבד א\"א להיות הנהגת המלוכה כ\"א ע\"פ דין ומשפט כמ\"ש מלך במשפט כו' וארז\"ל אלמלא מוראו כו', וכך יובן למעלה שהגם דכתיב והוכן בחסד מ\"מ צ\"ל גם מלך במשפט כו', וכן לענין התהוות השמים א\"א ע\"י החסד לבד כ\"א גם ע\"פ גבורה, וז\"ע מים ואש. אמנם הנה הם שני הפכים שאש טבעו לעלות והמים יורדי' מגבוה כו' וגם בעצם מים מכבין אש, ולזה נק' הקב\"ה מלך שלמה כמ\"ש צאינה כו' מלך שהשלום שלו, כי המשל ופחד עמו עושה שלום כו', וכמשל שני שרים<sup data-n=\"105\">15</sup> שהם נפרדים זמ\"ז בתכלית השנאה כשעומדין לפני המלך מתבטלים לגמרי כו', וכך יובן שמפני כי המשל ופחד עמו עי\"ז נעשה שלום במרומיו מיכאל וגבריאל שהגם שמיכאל שר של מים וגבריאל שר של אש, ומ\"מ אין מכבין זא\"ז. ועד\"ז יובן בענין אש ומים דשמים, שכאשר מאיר בחי' רוחא עילאה מתבטלי' חו\"ג דאש ומים ומתקיימין כחדא, ובחי' רוח זה בחי' גבוה מדתו של יעקב, בחי' ונתתם לי אות אמת דא וא\"ו עמודא דאמצעיתא בריח התיכון, ושרשו מבחי' אויר אור יו\"ד, וזהו שאומרים בשמו\"ע אלקי אברהם כו' וביעקב ואלקי בתוס' וא\"ו, וכן והנורא, ושרש הוא\"ו והנורא הוא מאל עליון כו', ולכן ע\"י בחי' רוח עילאה זה מחברים ב' בחי' חו\"ג, כי כשמאיר הארה מבחי' דלאו מכל אינון מדות במדות עי\"ז מתבטלין חו\"ג כו'.\n<b>וזהו</b> שאמר בס\"י ג' אמות אמ\"ש<sup data-n=\"106\">16</sup>, אש מים אויר<sup data-n=\"107\">17</sup>, וכמו שאנו רואים שהאש מורגש בחוש הראי', והמים גם בחוש המישוש, והאויר לעוצם דקותו אינו מורגש בחושים הגשמי', ולכן ביכולתו לחבר ב' בחי' אש ומים. ועפ\"ז יובן מאמר ר' יוסי הנ\"ל שעביד שמיא מאש וממיא מתערבין כחדא ולא הוי גלדי, פי' כי המים כשהולכין הם הולכים בחוזק וכמ\"ש ואשמע את קול כנפיהם כקול מים רבים, וכתי' מקולות מים רבים אדירים, והרי הם בבחי' יש ומציאות התפשטות, אמנם ע\"י בחי' רוחא עילאה שנשב בם אתגלידו, והיינו שכאשר רוח צפוני' מנשב במים[ednref_26_כה] עי\"ז הם",[["105","15","<b>המשל ופחד עמו עושה שלום כו' וכמשל שני שרים</b>: הובא בשם הה\"מ בס' מאמרי אדה\"ז אתהלך לאזניא ע' יב. תקס\"ב ח\"ב ע' תמ. תקס\"ג ח\"א ע' נב. ביאוה\"ז לאדהאמ\"צ ח, ג. פלח הרמון שמות ע' רסא. וראה גם אגה\"ק סי\"ב (קיז, א). לקו\"ת תזריע כג, רע\"ג. סה\"מ תרל\"ג ח\"ב ע' תקד. תקלה. המשך מצה זו תר\"מ פרק נו\"ן (סה\"מ תר\"ם ח\"א ע' רלא-ב). ועוד."],["106","16","<b>שאמר בס\"י ג' אמות אמ\"ש</b>: ראה גם לקו\"ת שה\"ש מט, ג."],["107","17","<b>אמ\"ש אש מים אויר</b>: במאמר שלפנ\"ז (ד\"ה ויאמר גו' לך לך הא'): אמ\"ש שהוא ר\"ת אויר מים אש.\n\n[edn_26_כה] <b>ששכאשר רוח צפוני' מנשב במים. . בקי\"ס. . שהוליך ה' ברוח קדים</b>: בשולי הגליון נרשם בגוכי\"ק: אולי יש להעיר לענין ההפרש בין רוח קדים לרוח צפונית ממ\"ש בד\"ה אדם כי יהי' בעור בשרו<sup data-n=\"1620\">116</sup> מענין מתיבתא דרקיע שיש ב' מתיבתות, מתיבתא דמט\"ט ומתיבתא דקוב\"ה, מט\"ט ביו\"ד הוא בבריאה ע' בד\"ה ונערים ממשתה נגינתם בס' תקס\"ז<sup data-n=\"1621\">118</sup>, ובבריאה מאיר בינה, והיינו בהיכל קד\"ק דבריאה בחי' ג\"ע העליון, וז\"ע רוח צפונית צפון ה' עילאה, ומתיבתא דקוב\"ה זהו באצי' שהרקיע שע\"ג חיוין עילאין הוא בינה שבה התגלות עתיק שזהו בחי' רוח קדים בחי' קדמונו של עולם, וי\"ל כי תורה שלנו היא תורת הבריאה, בד\"ה ויתן אל משה בס' שמות ח\"ג<sup data-n=\"1622\">119</sup>, אבל תורה שלמעלה היא משל הקדמוני משל להבין בחי' קדמונו של עולם, והמשל הוא כמו רקיע, וע\"י רקיע זה מבינים הנמשל הוא בחי' הרוח קדים שמזה נעשה הרקיע, כי בתורה נאמר ויהי קול מעל לרקיע, וכמו שהוא בתורה שלנו מעל רקיע שע\"ג חיוין תתאין כ\"ה בתורה שלמעלה מעל לרקיע שע\"ג חיוין עילאין, וצ\"ע."],["1620","116","<b>בד\"ה אדם כי יהיה בעור בשרו</b>: אוה\"ת תזריע (כרך ב) ע' תקלב."],["1621","118","<b>בד\"ה ונערים. . בס' תקס\"ז</b>: ד\"ה ונערים ממשתה נגינתם הוא מש\"פ ויצא תקס\"ח, ונרשם בגוכי\"ק אדמו\"ר האמצעי בבוך (מס. 1196) הכולל מאמרי שנת תקס\"ז ותחילת תקס\"ח. — נדפס בס' מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרכב. וראה גם שם ע' תשלב. ס\"ע תשלג ואילך. סה\"מ תרל\"ב ח\"א ע' ריד ואילך. ח\"ב ע' שס ואילך."],["1622","119","<b>בד\"ה ויתן אל משה בס' שמות ח\"ג</b>: אוה\"ת תשא ע' א'תתקסט-ע. וראה גם סה\"מ תרכ\"ז ע' קסו."]]],[2000510105,"נקררי' ונעשי' כמו גליד וקרח, פי' שמתבטלים ממהותם והילוכם הקודם ונעשו כמו קרח בבחי' העדר ההתפשטות. וזהו קרח אותיות חרק<sup data-n=\"108\">18</sup> בחי' נקודה חדא להורות על הביטול אשר בם, שהגם שטבע האש לעלות, וטבע המים להיות נמשכים, וגם בעצם מים כו' כנ\"ל, מ\"מ ע\"י שהאיר בחי' רוחא עילאה נתבטלו ונעשו כמו גליד וקרח בבחי' ביטול והעדר ההתפשטות. וע\"ד שנאמר בקי\"ס נצבו כמו נד לפי שהוליך ה' ברוח קדים עזה ולכן נצבו כמו נד, כי איידי דטריד למיבלע לא פליט, ושם היה רוח קדים, וכאן ע\"י בחי' רוחא עילאה עי\"ז נתבטלו המים ואש ואגלידו ונעשה רקיע כעין הקרח, וכן אמרו ברבות לחים היו מעשיהם בראשון ובשני קרשו, והגם כי נבראו בראשון כמ\"ש בראשית כו' השמים, מ\"מ לחים היו וע\"י הרוחא עילאה נקרשו בשני כו'.\nג) <b>והנה</b> קיום בחי' הרוח הוא ע\"י התורה דכד משתדלין ישראל באורייתא כדין קאים עלמא, כי אורייתא מחכמה נפקת והחכמה היא בחי' אחד האמת אשר בה שורה אוא\"ס כמ\"ש בסש\"ב פל\"ה בהג\"ה, וזהו חכמה כח מ\"ה, היינו בבחי' מ\"ה דחכ' שורה אוא\"ס שלמעלה מבחי' חכמה, ואורייתא מחכמה נפקת, ולכן ע\"י הקול דתורה מתקיים בחי' רוחא עילאה הנ\"ל, כי הקול מורכב מג' יסודות אש מים רוח, כי יסוד האש הוא בלב, והריאה מרחפת ומנשבת על הלב<sup data-n=\"109\">19</sup> לקרר חומה,",[["108","18","<b>וזהו קרח אותיות חרק [חיריק]</b>: ראה לקו\"ת דרושים לשמע\"צ פז, ב (בהגה\"ה): ומבואר במ\"א בשם הרב הקדוש ר' אברהם בן הרב המגיד נ\"ע כי קרח אותיות חרק. ובס' מאמרי אדה\"ז על מארז\"ל ע' תב: שמע מבן מורו [הה\"מ] ע\"ה (ר' אברהם ז\"ל נבג\"מ) שקרח אותיות חר\"ק. וראה גם לקו\"ת שה\"ש כו, ב. מאמרי אדה\"ז תקס\"ה ח\"א ע' תנב. תקס\"ז ע' קעו. ביאוה\"ז לאדהאמ\"צ מה, ג. אוה\"ת שה\"ש (כרך ב) ס\"ע שצט-ק. סה\"מ תרכ\"ז ע' תכז. תרס\"ג ח\"א ע' קנו. קנח."],["109","19","<b>והריאה מרחפת ומנשבת על הלב</b>: ראה בכ\"ז בארוכה מאמרי אדהאמ\"צ במדבר ח\"ה ע' א'תתכז-ח."]]],[2000510106,"והריאה שואבת כל מיני משקה זהו בחי' המים שצריכים לקול, וע\"י אמצעות הקנה המוציא רוח יוצא הקול מורכב מג' יסודות אש מים רוח, ולכן כשמתגבר יסוד א' מהג' נעשה שינוי בהקול. ועפ\"ז יובן שע\"י קול דתורה שמורכב מג' יסודות אש מים רוח ואורייתא מחכמה נפקת אשר בה שורה אוא\"ס דלאו מכל אילין מדות איהו כלל, עי\"ז מתקיים בחי' הרוחא עילאה בחי' רוח שיתקיים העולם בחי' שמים שמחו\"ג.\n<b>ואמר</b> אח\"כ ומתמן שתיל עלמא לקיימא על סמכין הכוונה על בחי' ארץ שהיא קיימא על סמכין, דהנה כתיב כגבוה שמים מארץ, וכתיב שמים לרום כו', כי שמים בכלל הוא בחי' ע\"ס דאצי', כמ\"ש בבה\"ז בתוס' דבשלח<sup data-n=\"110\">20</sup>, ובאצי' איהו וחיוהי חד כו', אבל בכדי שיתהווה הארץ שהיא בחי' מקור לג' עולמות בי\"ע אשר משם יפרד והיה לד' ראשים, ד' מחנות שכינה<sup data-n=\"111\">21</sup>, ועולמות נבראים בעלי גבול, זהו ע\"י בחי' סמכין הם נו\"ה, שהם בחי' כליות יועצות איך להשפיע וכמו מי שצריך להשפיע שכל לזולתו צריך לייעץ בעצמו איך להשפיע, כמו\"כ יובן למעלה ענין כליות יועצות שהוא בחי' העצה איך שיומשך המשכת אלקות גם בבי\"ע, שזהו ע\"י הארץ בחי' מל'. ולכן אמר ומתמן שתיל עלמא לקיימא על סמכין בחי' נו\"ה, וכולא קאים באורייתא כי ע\"י תומ\"צ הוא קיום שמיא וארעא שז\"ע מ\"ש במחוקק במשענותם, במחוקק בחי' אותיות החקיקה שבתורה, במשענותם בחי' המצות<sup data-n=\"112\">22</sup> שנק' תמכין, שז\"ע העמודים שבגמ' והסמכין שבזהר כו'.\nד) <b>אך</b> עדיין צ\"ל מפני מה בגמרא אמר ר' יוסי זה סתם ובזהר אמר זה ע\"פ מה ידידות משכנותיך כו', שלכאורה מה שייך זה לפסוק מה ידידות. אך הענין הוא שבזהר הקדים זה לפ' לך לך, וע\"כ צ\"ל שפסוק מה ידידות שייך לאברם וגם שייך לבחי' הארץ אשר אראך, שלכן מקדים ר' יוסי פסוק זה וענין זה לפ' לך לך. והענין דפי' ל' ידידות הוא מל' תוקף האהבה, וע\"ד שארז\"ל וכולם אנו למדים מפרשיתו של אותו רשע, שזהו בחי' תוקף האהבה, וישראל נשתבחו בזה כמו שאמרו שם בג' לשונות של חיבה חיבב הקב\"ה את ישראל בדביקה ובחשיקה ובחפיצה, בדביקה ואתם הדבקים בה' כו', ובחשיקה לא כו' חשק ה' כו', ובחפיצה ואשרו כו' כי תהיו אתם ארץ חפץ, פי' פנימיות הרצון כו'. והיינו כי בהשפעות אלקות בעולמות יש שני בחי', הא' הוא מה שבטובו מחדש בכל יום תמיד מעשה בראשית, שבכל יום מתחדש הבריאה מאין ליש, ולכן השמש זורח ממזרח ושוקע במערב, וכן כל הילוך הכוכבים ליום וללילה לא ישנו תפקידם שוה בכל יום, ובלילה זמן החושך, וכאור בקר מתחיל להאיר כברייתו של עולם ברישא חשוכא והדר נהורא כמ\"ש ויהי ערב ויהי בקר כו', וחדשים לבקרים, שבכל יום נעשה ברי'",[["110","20","<b>כמ\"ש בבה\"ז בתוס' דבשלח</b>: דף מה, א."],["111","21","<b>ומשם יפרד והי' לד' ראשים ד' מחנות שכינה</b>: ראה אוה\"ת בראשית (כרך ג) תקלה, א (בשם הזהרי חמה). המשך תרס\"ו ס\"ע יא-ב."],["112","22","<b>במחוקק בחי' אותיות החקיקה שבתורה במשענותם בחי' המצות</b>: ראה לקו\"ת חוקת סג, ד. סד, סע\"ב-ג."]]],[2000510107,"חדשה שז\"ע ברכת השחר כמ\"ש מזה במ\"א<sup data-n=\"113\">23</sup>, ועז\"נ לעולם ה' דברך נצב בשמים שתמיד עומד דבר ה'<sup data-n=\"114\">24</sup> להחיות השמים עד\"מ, לפי שבטובו מחדש בכל יום תמיד מעשה בראשית. אמנם הנה כל זה הוא בדרך העלם והסתר הבורא מהנברא שדבר המהוה מסתתר מדבר המתהוה, שז\"ע בריאה יש מאין כמ\"ש מזה במ\"א<sup data-n=\"115\">25</sup>. אבל יש עוד בחי' א' שז\"ע בחי' תוס' וריבוי אורות שזהו רק לפרקים, אבל זהו עיקר בחי' ההמשכה כי תוספתו של הקב\"ה מרובה על העיקר כו' שז\"ע בחי' אור חדש על ציון תאיר<sup data-n=\"116\">26</sup> בחי' תוס' וריבוי אורות כו'. ויובן דבר זה ממשארז\"ל צמצם שכינתו בין שני בדי ארון<sup data-n=\"117\">27</sup>, וכתיב כי בענן כו' ונועדתי לך שמה, שלכאורה מהו השבח והרבותא בזה הלא מלא כל הארץ כבודו כתיב, וכתיב את השמים ואת הארץ אני מלא, דלית אתר פנוי מיני' כלל ומהו השבח כו'. אך נודע התירוץ בשם הה\"מ נ\"ע<sup data-n=\"118\">28</sup> שמה שמלא כל הארץ כבודו זהו רק בהעלם, אבל צמצם שכינתו בין ב' בדי הארון להאיר בבחי' גילוי, וע\"ד לע\"ל דכתיב ונגלה כבוד הוי' וראו כל בשר, כי ביום ההוא יהי' ה' אחד כו' ויראו הכל בבחי' ראי', ועכשיו הי' זה בבהמ\"ק לבד ולכן הי' ע\"י צמצום כו', ועד\"ז יובן ענין תוס' אורות שיאיר בחי' אור חדש בבחי' גילוי אלקות בחי' השפעה פנימיות כו'.\n<b>וזהו</b> שמסיים בזהר בשעתא דרוחא דכל רוחין ארים בסימא דנשמתא, שלכאורה צ\"ל מהו ענין רוחא דכל רוחין הלא הזכיר תחלה רק רוחא עילאה. אך י\"ל דרוחא עילאה שהזכיר תחלה ורוחא דכל רוחין זהו ענין ב' בחי' הנ\"ל, הא' בחי' המחדש בטובו בכל יום תמיד כו' זהו בחי' רוחא עילאה, ולכן כמו שבבחי' חידוש הישנות צ\"ל לעולם ה' דברך נצב בשמים דאל\"כ הי' לאין ואפס, כמו\"כ בבחי' רוחא עילאה אמר ר' יוסי בשעתא דרוחא אסתליק כולהו מרפפין וזעין ועלמא ארתת הה\"ד המרגיז ארץ כו' ועמודי' יתפלצון מל' ותכסיני פלצות. ואח\"כ אמר בשעתא דרוחא דכל רוחין ארים בסימא דנשמתא הכוונה בזה על בחי' תוס' אורות הנ\"ל, שז\"ע בחי' השפעה פנימי' כו'. ויובן זה ממה שאנו רואים שלמטה יש ד' בחי' דצח\"ם, דומם הוא בחי' היותר נמוך ופחות במדריגה, וצומח יותר נעלה ממנו",[["113","23","<b>וחדשים לבקרים שבכל יום נעשה ברי' חדשה שז\"ע ברכת השחר כמ\"ש מזה במ\"א</b>: בגוכי\"ק נרשם כאן: (בד\"ה ) והשאיר מקום חלק. וראה בארוכה מאמרי אדה\"ז תקס\"ג ח\"א ע' קכג-ד. תורת חיים שמות (כת\"י הר\"ש סופר) קח, א ואילך. ובהוצאת תשס\"ד ח\"א עד, א ואילך. וראה גם לקו\"ת אמור לא, ב. נצבים מו, סע\"ב. קונ' ענינה של תורת החסידות סי\"ג. ועוד."],["114","24","<b>לעולם ה' דברך נצב בשמים שתמיד עומד דבר ה'</b>: ראה בכ\"ז שעהיוה\"א פרק א."],["115","25","<b>שדבר המהוה מסתתר מדבר המתהוה. . כמ\"ש מזה במ\"א</b>: בגוכי\"ק נוסף כאן: (בד\"ה ) והשאיר מקום חלק, ולעיל במאמר שלפנ\"ז (מהדו\"ק) מציין לד\"ה מהיכן זכו (סה\"מ תרכ\"ז ע' שפח), וד\"ה מי כמוכה (סה\"מ תרכ\"ט ע' קסא-ב)."],["116","26","<b>שז\"ע בחי' אור חדש על ציון תאיר</b>: סיום ברכת ”יוצר המאורות\" ע\"פ נוסח אשכנז. הובא גם בלקו\"ת שה\"ש ט, ב. כ, ב. סידור עם דא\"ח סח, רע\"ב. מאמרי אדה\"ז תקס\"ב ח\"א ע' קצב. מאמרי אדהאמ\"צ במדבר ח\"א ע' קמו. אוה\"ת לך לך (כרך ד) תרצז, רע\"א. שה\"ש (כרך ג) ע' תתלד. סה\"מ תרכ\"ט ע' קט. וע' קצו. תרל\"ג ח\"א ע' כ. פר\"ת ע' קמה. ועוד."],["117","27","<b>ממשארז\"ל צמצם שכינתו בין שני בדי ארון</b>: בהבא לקמן ראה לקו\"ת אמור לד, ב. בלק עג, ב. לקמן ע' קמב. וש\"נ."],["118","28","<b>נודע התירוץ בשם הה\"מ נ\"ע</b>: הובא בלקו\"ת אמור לד, ב שם."]]],[2000510108,"להיות יש בו נפש הצומחת ואין לך עשב מלמטה שאין לו מזל מלמעלה השופע בו ואומר גדל כו'. ולמעלה ממנו הוא בחי' חי שיש בהם רוח חיים כמ\"ש תוצא הארץ נפש חי' כו' בהמה כו'. אמנם כל ג' בחי' אלו אינם בערך האדם שכל העולם לא נברא אלא לצוות לזה כמ\"ש כי זה כל האדם, ולכן האדם יש בו נפש המדברת ונפש השכליות להשכיל השכלות כו', אך נפש השכלית שבאדם הוא רק להשכיל השכלות גשמיות, ולמעלה בחי' נשמה הוא בחי' תוס' וריבוי אורות, בחי' נשמת שדי תבינם, רוחו ונשמתו אליו יאסוף שזהו בחי' גבוה מאד, וז\"ע ארים בסימא דנשמתא בחי' המתקת הנשמה מל' מתיקות ותענוג מבחי' תוס' אורות הנ\"ל כו'.\nה) <b>ועפ\"ז</b> יובן ענין הידידות מה ששייך לאברהם ולבחי' הארץ כו'. דהנה ארז\"ל יבוא ידיד בן ידיד ויבנה ידיד לידיד בחלקו של ידיד ויתכפרו בו ידידים, בן ידיד זה אברהם שנאמר מה לידידי, ויבנה ידיד זה בהמ\"ק שנאמר מה ידידות משכנותיך ה' צבאות, לידיד זה הקב\"ה שנאמר אשירה נא לידידי, שנק' בהמ\"ק ידיד ע\"ש מה ידידות ואברהם נק' ג\"כ ידיד, והיינו כמשנ\"ת לעיל שידידות הוא בחי' תוקף האהבות שהוא בחי' השפעה פנימיות, והוא כמ\"ש והוי' בהיכל קדשו היכל בגימ' אד' שהוא בחי' היכל לשם הוי' שבבהמ\"ק האיר בחי' שם הוי', וז\"ע כי בענן אראה, וכתי' ונועדתי לך אותיות ונודעתי מל' והאדם ידע בחי' השפעה פנימיות כו', וז\"ע מה ידידות משכנותיך שקאי על בהמ\"ק. וכמו\"כ אברהם שנק' ידיד ע\"ש תוקף האהבה שהי' לו לאלקות בבחי' פנימיות, ועי\"ז נמשך לו בחי' תוס' אורות בחי' רוחא דכל רוחין ארים בסימא דנשמתא, שז\"ע מה שישראל עלו במח' וארז\"ל מחשבתן של ישראל קדמה לכל דבר. דהנה כתיב כי לא מחשבותי מחשבותיכם<sup data-n=\"119\">29</sup> שלכאורה יפלא מהו שמשבחין אותו שמחשבתו אינו דומה למחשבותיכם ולא בשארי לבושי הנפש או מדות הנפש, והיינו לפי שבמחשבה ניכר יותר כי בבחי' מחשבה אם יחשוב אדם כל היום כולו לא יתהוה מזה כלום, משא\"כ ע\"י דבורו אם יצוה לזולתו יעשה זאת, וע\"י מעשה יכול לעשות בעצמו, והגם כי זהו רק יש מיש לבד, שאם מתכנשין כל באי עולם אין יכולים לברוא אפילו כנף יתוש א', מ\"מ יש מיש יכולים לעשות, אבל במחשבה נראה וניכר לכל שאם יחשוב כל היום לא יתהוה מזה כלום, אבל למעלה שתיכף כשעלה במח' לברוא נברא הכל, וזהו שאמר בזהר שבמח' א' נבראו כל העולמות, ומה שנפרטו אח\"כ בעשרה מאמרות זהו בכדי שיתהוה עלמין דאתגליין עד עוה\"ז הגשמי<sup data-n=\"120\">30</sup>, כי מבחי' מח' נתהוו עלמין סתימין ובכדי שיהי' עלמין דאתגליי' זהו ע\"י הדבור, אבל מ\"מ בכלל נבראו הכל ע\"י מח' אחת ואפילו תחה\"מ, ואין בפרט אלא מה שבכלל, וזהו כי לא מחשבותי מחשבותיכם. ובבחי' מח' הקדומה זה עלו ישראל במח' וקדמו לכל דבר, וזהו בחי' שורש ומקור הנשמה אשר נשארה למעלה בחי' מזל שבנשמה בחי'",[["119","29","<b>דהנה כתי' כי לא מחשבותי מחשבותיכם</b>: בהבא לקמן ראה סה\"מ תרל\"ד ע' רמ. ובארוכה לקו\"ת שה\"ש יז, סע\"ג ואילך. וראה גם לקו\"ת ואתחנן ב, ב."],["120","30","<b>שבמח' א' נבראו. . ומה שנפרטו. . בעשרה מאמרות. . בכדי שיתהוה. . עוה\"ז הגשמי</b>: ראה בכ\"ז בארוכה סה\"מ תרכ\"ז ע' רפב ואילך [ובהנסמן שם בתחילת המאמר]."]]],[2000510109,"ונוזלים מן לבנון, ועל בחי' זו אמרו מזלייהו חזי, והארה מבחי' הנשמה ירדה בבחי' בראת יצרת כו' להחיות הגוף כו'.\n<b>ולכן</b> בכדי שיבוא אברהם לידבק בשורש נשמתו שזהו בחי' גבוה מאד נעלה כו', שלכן אמר האריז\"ל שגילוי שורש ומקור הנשמה גבוה יותר מבחי' גילוי אליהו ורוה\"ק<sup data-n=\"121\">31</sup>, זהו ע\"י הארץ אשר אראך דוקא כי למה נק' שמה ארץ שרצתה, והיינו בחי' הרצוא והתשוקה ול' רצון, כי נעוץ תחלתן בסופן וסופן בתחלתן, ולכן בבחי' ארץ שהיא סוף המדרגות בבחי' אור ישר יש בה בחי' נעיצת התחילה יותר מבחי' ראש המתפשט הוא בחי' ראשית חכ' כו' כמ\"ש במ\"א<sup data-n=\"122\">32</sup>. ולכן בכדי שיבוא לבחי' שרשו ומקורו זהו ע\"י הארץ, כי בארץ בא לבחי' רצוא ותשוקה לאלקות עד בחי' רצה\"ע שנעוץ סופן בתחלתן ותחלתן בסופן דוקא, והי' צריך לצאת מארצו הוא עבר הנהר או אור כשדים, וגם מטעם שנת' לעיל ס\"א שבחו\"ל אינו מתלבש רק מל' דיצי' לא יותר כו'. וזהו שנאמר לך לך ב\"פ שאם הכוונה שילך מארצו הי' די במה שיאמר פעם א' לך, אלא הכוונה לבוא בבחי' לך לבחי' שורשו ומקורו שלמעלה כו'. וב' כפי\"ן שבלך י\"ל כמו מעשה אבות כו' ועתידים בניו להקדים נעשה לנשמע שבאותה שעה קשרו להם שני כתרים א' כנגד נעשה וא' כנגד נשמע בחי' כתר דאו\"י ואור חוזר, כי כתר הוא בחי' מחבר אלקות ועולמות, וכתר דאור ישר מחבר אוא\"ס המאציל עם אצי', וכתר דאור חוזר הוא מלמטה למעלה בחי' כ\"ע דאיהו כתר מל' שמלמטה למעלה בחי' מל' הוא כתר כו' כי נעוץ תחלתן בסופן כו' וסופן בתחלתן.\nוא\"ו) <b>ובכ\"ז</b> יובן ענין מה שסמך ר' יוסי בזהר מאמר זה ע\"פ מה ידידות כי זהו הקדמה לענין אברהם שהי' ידיד אהבה פנימיות, ושיודבק בשרש נפשו זהו ע\"י הארץ דוקא שבה הי' בית המקדש שנק' מה ידידות בחלקו של ידיד הוא בנימין בחי' צדיק תחתון כו'.\n<b>אך</b> עדיין צ\"ל מפני מה בגמרא אמר ר' יוסי מאמר זה באריכות שהארץ עומדת על עמודי' ועמודי' על המים, הרים, רוח, סערה, וסערה בזרועו של הקב\"ה, ובזהר אמר בקצרה עביד שמיא מאש וממיא, וע\"י רוחא עילאה אתגלידו ומתמן שתיל עלמא לקיימא על סמכין, ולא הזכיר יותר. והענין הוא דהנה בזהר התחיל מלמעלה למטה ובגמרא התחיל מלמטה למעלה, שהתחיל מארץ ולכן ביאר בגמרא כוונת נעיצת התחילה יותר, והיינו כי התחיל מארץ ואמר שעומדת על העמודים הם בחי' הסמכין שבזהר בחי' נה\"י, שמנה\"י דז\"א נעשים מוחין לנוק', ואח\"כ אמר",[["121","31","<b>שגילוי שורש ומקור הנשמה גבוה יותר מבחי' גילוי אליהו ורוה\"ק</b>: ראה גם לקו\"ת תצא לו, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתלב. על מארז\"ל ע' רל. ביאוה\"ז להצ\"צ ח\"א ע' קצז. סה\"מ תרל\"ב ח\"ב ע' תקיז. המשך מים רבים תרל\"ו ע' רג. ועוד."],["122","32","<b>בבחי' ארץ. . נעיצת התחילה יותר מבחי' ראש המתפשט. . כמ\"ש במ\"א</b>: ראה בכ\"ז בארוכה סה\"מ תר\"ל ע' שכ. תרל\"ב ח\"א ע' קז. תרל\"ב ח\"ב ע' שסז ואילך. וראה גם מאמרי אדה\"ז תקע\"א ע' ס. נביאים ע' רסה. אוה\"ת בראשית (כרך ו) תתרכו, ב. סה\"מ תרל\"ג ח\"א ע' קטז."]]],[2000510110,"מים והרים ורוח הם חג\"ת, ובזהר כללן במה שאמר עביד שמיא מאש וממיא ורוחא עילאה, שע\"י בחי' הרוח אגלידו השמים, והיינו כי מים הוא בחי' חסד כי אמרתי עולם חסד יבנה הנ\"ל בחי' חסד דאברהם, והרים אלו האבות כמ\"ש בתיקונים ע\"פ שמעו הרים את ריב ה' אלו אבהן, שכמו ההר היא גבוה ועליונה משטח הארץ כמו\"כ האבות היו גבוהים ועליונים כו'. ויש לומר בדרך פרט קאי על יצחק שנעקד ע\"ג הר המורי', ומ\"מ קאי על כל האבות כי אברהם עקדו ויעקב עדיין לא נולד, א\"כ הי' כלול ביצחק. ורוח בסערה, הנה בחי' סערה בקדושה היא בחי' גבוה מאד נעלה, ויובן ע\"פ משארז\"ל במד\"ר ע\"פ ה' בסופה ובסערה דרכו, בסופה זה משה שנאמר ותשם בסוף כו' ובסערה זה אלי' שנאמר ויעל אלי' בסערה השמי', וקאי שם על תחה\"מ שאז משה ג\"כ בא, א\"כ בחי' סערה זו הוא כמ\"ש בתחה\"מ ונתתי רוחי בכם וחייתם, שהוא בחי' גבוה מאד, וע\"ד שבמבול נאמר לא ידון רוחי, שתחלה האיר בחי' רוח ומזה נמשך בחי' אריכות ימים, ואח\"כ כשהי' צריכים לחיות רק ק\"ך שנים נאמר לא ידון רוחי, מובן שהרוח הוא בחי' גבוה שנמשך מבחי' א\"א. ורוח דתחה\"מ י\"ל שהוא עוד גבוה יותר, כי יש ג' בחי' ברוח, רוה\"ק, ורוח דעמודא דאמצעיתא, ויש בחי' רוח עילאה סתימאה שבחשאי, וע\"ז אמרו העולה קדש קדשים, וי\"ל שבזהר נכלל זה במה שאמר רוחא דכל רוחין שהוא בחי' סערה הנ\"ל שמזה נמשך בסימא דנשמתא שבזה נכלל גם בחי' נשמה יתירה דשבת ששרשה מבחי' הכתר, בחי' אז תתענג על הוי' כו'. אך מה שאמר בגמרא וסערה בזרועו של הקב\"ה ובזהר לא הזכיר מזה, י\"ל לפי שבגמרא התחיל בארץ לכן ביאר כוונת נעיצת התחילה יותר, ולכן א' שסערה תלוי' בזרועו של הקב\"ה שנאמר ומתחת זרועות עולם הוא בחי' סובב הכללי[ednref_27_כו] המקיף לכל הד' בחי' אבי\"ע בשוה שזהו בחי' כוונת נעיצת התחילה שבשרשו ארץ קדמה כו'.\nז) <b>ומעתה</b> נבוא לתרץ מה שאברהם בכדי שיבוא לידבק בשרשו זהו ע\"י הארץ, האם נאמר שישראל שבחו\"ל כו' כנ\"ל. אך הענין הוא דכתיב ביום ההוא כרת ה' כו' לזרעך נתתי את הארץ הזאת[ednref_28_כז], ודבורו של הקב\"ה חשיב מעשה,",[["","","[edn_27_כו] <b>ומתחת זרועות עולם. . סובב הכללי</b>: בשולי הגליון נרשם בגוכי\"ק: אויר אור יו\"ד אוירא דכיא פי' בבה\"ז בתוס' דבשלח<sup data-n=\"1623\">134</sup> חכ' דא\"ק, מ\"מ א\"ק זהו אדם דבריאה בכלליות ומתחת זרועות סובב הכללי כו'.\n\n[edn_28_כז] <b>דכתיב ביום ההוא כרת ה' כו' לזרעך נתתי את הארץ הזאת</b>: בשולי הגליון נרשם בגוכי\"ק: בברית בין הבתרים מביא במדרש בשם פסיקתא שהי' בן ע' שנה<sup data-n=\"1624\">135</sup> וכ\"ה בתוס' ד\"ז דברכות וכ\"ה בסדר עולם, וחזר לחרן ה' שנים וכשהי' בן ע\"ה יצא מחרן שנית, והרלב\"ג חולק ע\"ז. ובשם מדרש תנחומא הביאו שהי' בן מ\"ח שנה בברית בין הבתרים ונתבשר לו שאחר נ\"ב שנים יוליד בן, וא\"י איך א\"ל הארץ הזאת ע\"כ הי' בארץ כנען."],["1623","134","<b>בבה\"ז בתוס' דבשלח</b>: ביאוה\"ז לאדהאמ\"צ מד, א."],["1624","135","<b>בברית בין הבתרים. . שהי' בן ע' שנה</b>: ראה תורה שלמה לך לך טו, ט סי' צט. וש\"נ."]]],[2000510111,"לכן מיד כשאמר נתן הארץ הזאת ברוחניות לזרעו, וז\"ע מה שנק' ישראל ארץ חפץ כמ\"ש ואשרו כו' כי תהיו אתם ארץ חפץ, פי' חפץ פנימיות הרצון, והיינו שהארץ אשר היא טובה לזריעה וראוי' יותר משאר הארץ נק' ארץ חפץ שבה רצון האדם יותר לזרוע בה, כי עיקר מכוון מהזריעה היא הצמיחה כו'. כמו\"כ יובן מה שנק' ישראל ארץ חפץ לפי שהם הם בחי' ארץ אשר הם מקום הראוי לזרוע בהם והוא מפני שניתן להם ארץ העליונה בבחי' מתנה כו'. והזריעה היא בחי' אור זרוע לצדיק וכמארז\"ל במד\"ר זרע הקב\"ה התורה והמצות והנחילם לישראל לע\"ל ולא הניח דבר שלא עשה בה מצוה, בא לחרוש לא תחרוש בשור ובחמור, בא לזרוע לא תזרע כרמך כלאים, בנה בית מזוזה מעקה, עשה בגד ציצית, ולכן ע\"י שניתן לנו הארץ העליונה והתומ\"צ וגדול המצווה ועושה עי\"ז אנו יכולים לדבוק בשרש נשמתינו גם בחו\"ל.\n<b>ואברהם</b> הגם כי קיים אברהם כל התורה כולה שנאמר עקב, וארז\"ל אפי' עירובי תבשילין מ\"מ כל עיקר קיום המצות שלו הי' ע\"י עובדות<sup data-n=\"123\">33</sup> כי זה הי' קודם מ\"ת, ועיקר עבודתו הי' להמשיך ש' הוי' ולהודיע אלקותו בעולם, וכמ\"ש ויטע אשל כו' ויקרא בשם ה' כו', אש\"ל ר\"ת אכילה שתי' לוי'<sup data-n=\"124\">34</sup>, וע\"י שהרבה חסד בעולם המשיך המשכת אלקות כו', וכן יצחק ע\"י חפירת בארות כו' אך מ\"מ הלא ארז\"ל במד\"ר ע\"פ לריח שמניך טובים כל המצות שעשו האבות ריחות היו, אבל אנו שמן תורק שמך דבר שמריקים מכלי אל כלי, פי' ריחות הוא רק הארה בעלמא שאינו עצם הדבר אבל ע\"י המצות שנתן לנו במ\"ת עי\"ז נמשך המשכה עצמיות כמו ע\"י תפילין עד\"מ נמשך מוחין לז\"א, וזהו בחי' שמן תורק כו' ושרשו מבחי' שמן משחת קדש שמושח את הקדש כו'. ונמצא כי יש יתרון המעלה בתומ\"צ שניתן לנו על בחי' התורה שקיים אברהם עד שלא ניתנה.\n<b>וזהו</b> שאברם לא הי' יכול לבוא ע\"י עבודתו לשרש נשמתו כ\"א ע\"י הארץ דוקא, לפי שבה נעוץ התחילה ונעוץ סופן בתחלתן, כי עבודתו הי' ע\"י עובדות לכן הי' צריך עכ\"פ להיות בארץ שמכוונת נגד הארץ העליונה שבה מאיר מל' דאצי' ומל' דבריאה ע' בסש\"ב בפרקים האחרונים<sup data-n=\"125\">35</sup>, וזהו מ\"ש הפרד\"ס בשם ספר הבהיר אמרה מדת החסד כל ימי היות אברהם בארץ לא הוצרכתי אני לעשות מלאכתי שהרי אברהם עומד במקומי וישמור משמרתי, דקדק לומר בארץ לפי שע\"י הארץ בא להיות מרכבה לבחי' חסד דאצי', שע\"י העקידה נתעלה לבחי' האצי', ולכאורה הלא ניסה אותו הקב\"ה במס\"נ שהפילו אותו לכבשן האש, ומדוע לא נתעלה אז לבחי' האצי', אלא לפי שאז הי' בחו\"ל באור כשדים לכן לא הי' יכול",[["123","33","<b>קיים אברהם כל התורה. . מ\"מ. . קיום המצות שלו הי' ע\"י עובדות</b>: ראה בארוכה לקמן ד\"ה וכל העם רואים את הקולות. וש\"נ."],["124","34","<b>אש\"ל ר\"ת אכילה שתי' לוי'</b>: ראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ט ע' 94. לקו\"ש חט\"ו ע' 501. סה\"ש תשמ\"ז ח\"א ע' 70 (הע' 89). וע' 84 (הע' 85)."],["125","35","<b>ע' בסש\"ב בפרקים האחרונים</b>: פנ\"א (עב, רע\"ב). פנ\"ב (עג, ב). פנ\"ג (עד, ב)."]]],[2000510112,"להגיע למדריגתו שבאצי', וכנ\"ל ששם מתלבש רק מל' דיצי' לא יותר כו', אבל ע\"י הארץ בא ע\"י נסיון העקידה להיות מרכבה לחסד דאצי' כו'. אך כ\"ז הוא קודם מ\"ת אבל ע\"י מ\"ת והארץ העליונה אשר ניתן לנו הכח שלה ברוחניות כמ\"ש לזרעך נתתי כו' עי\"ז אנו יכולים לבא לידבק לשורש נשמתינו גם בחו\"ל. וז\"ע הכריתות ברית דמשה שגם בהיותם כו' לא מאסתים בגלות בבל, ולא געלתים בגלות מדי, לכלותם בגלות כו', שגם בחו\"ל ע\"י התומ\"צ ימשיכו בחי' תוס' וריבוי אורות להוסיף אורות באצי' ואני ה' אלקי' לע\"ל יתגלה בחי' זו כו'.\n<b>ובכלל</b> ז\"ע הסולם דיעקב שאמרו בזהר סולם דא צלותא, וכן הוא במד\"ר סולם דא כבש המזבח ותפלה במקום תמידין תקנו, ואמרו עוד סולם זה סיני, והיינו בחי' מ\"ת, והיינו כי ע\"י הסולם מתחבר ומתדבק הארת הנשמה המלובשת בגוף עם שרש ומקור הנשמה[ednref_29_כח], ויש בזה שני אופנים באופן חיבורם, וכנודע ממשל<sup data-n=\"126\">36</sup> כשאחד עומד בהר והשני בעומק שיש שני אופנים באופן חיבורם, או שהתחתון יעלה למעלה או שהעליון ירד למטה, וז\"ע תפלה ותורה, תפלה היא בחי' העלאה מלמטה למעלה לכן מתחלת בדברים תחתונים בברכת השחר שלא עשני כו', וע\"י ד' שליבות שבסולם דתפלה מגיע לשרש נשמתו, וז\"ע שמע ישראל בחי' ישראל דלעילא שורש נשמתו כמו שהוא בבחי' ונוזלים מן לבנון כו', וע\"י התורה הוא הדביקות מלמעלה למטה, שנמשך בחי' שרש ומקור הנשמה לבחי' הנשמה המלובשת בגוף מלמעלה למטה, ולכן בתפלה צ\"ל והתפללו כו' דרך ארצם דוקא, והיינו לא מיבעי למ\"ד תפלות אבות תקנום שצ\"ל דרך ארצם דוקא, שהרי אברהם לא הי' יכול לבוא בסולם להתקשר לבחי' שורש נשמתו כ\"א ע\"י הארץ דוקא, ואפילו למ\"ד תפלות כנגד תמידין תקנו זהו ג\"כ בזמן ומקום בהמ\"ק וכלי המקדש, לכן צ\"ל עכ\"פ דרך ארצם. והענין הוא דבבחי' מלמטה למעלה יש דקדוקים יותר, וכמשל שהתחתון יעלה בהר זהו טורח יותר, ועד\"ז יובן דכתיב מי יעלה בהר ה' נקי כפים ובר לבב שחשיב שם הרבה בחי', ולכן בעליית הסולם דתפלה צ\"ל עכ\"פ דרך ארצם, אבל ע\"י התורה שמלמעלה למטה אין צריך דרך ארצם כי מלמעלה למטה אין שום מונע כלל, ולכן ארז\"ל כל העוסק בתורת עולה כאלו הקריב עולה גם עכשיו שלא יש בהמ\"ק וכלי המקדש, ועולה עצמה אם היו מקריבין אותה חוץ",[["126","36","<b>ויש בזה שני אופנים באופן חיבורם וכנודע ממשל</b>: ראה לקו\"ת ראה כו, א. מאמרי אדה\"ז הנחות הר\"פ ע' קנח. סה\"מ תקס\"ט ע' קלא. וע' קמא ואילך. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשפו-ז. וע' תתלה ואילך. אמרי בינה (שער הק\"ש) עא, ד. עג, ד ואילך. אוה\"ת בחוקותי (כרך ב) ע' תרעא. תרפא. תרפד. סה\"מ תרל\"ג ח\"ב ע' תכא. תער\"ב — ע\"ו ע' רנח ואילך. לקמן ד\"ה ואלה תולדות. ועוד.\n\n[edn_29_כח] <b>ע\"י הסולם מתחבר ומתדבק. . עם שרש ומקור הנשמה</b>: בשולי הגליון נרשם בגוכי\"ק: כתהאריז\"ל ששורש הנשמה גבוה מרוה\"ק."]]],[2000510113,"למקומה היתה פסולה והעוסק בתורת עולה כאלו הקריב במקומה וכלי המקדש, והוא לפי שהתורה היא למעלה מזמן ומקום, לכן כל העוסק בתורת עולה כו' ועי\"ז מתחבר שורש ומקור נשמתו לבחי' הנשמה שמלובש בגוף גם בהיותו בחו\"ל ע\"י התורה ותפלה מלמטה למעלה ומלמעלה למטה כו'."],[2000510114,"<h3>וד' פקד את שרה כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ וירא, ל\"א).</b>\nהוא וב\"ד כו' בני חיי ומזוני - ה\"פ\nוירא\n<b>וה'</b> פקד את שרה<sup data-n=\"127\">1</sup> כאשר אמר ויעש ה' לשרה כאשר דבר. וצ\"ל ענין כפל הלשון שאמר מתחלה וה' פקד ואח\"כ ויעש. והנה איתא בזהר ע\"ז ויעש עשי' לעילא דעשי' במזלא תליא, וזהו ענין ונהר יוצא מעדן כו' שנק' מזלא, דבני כו' במזלא תליא. והנה מתחלה צ\"ל שאמר תחלה וה' פקד בתוס' וא\"ו ואח\"כ אמר ויעש ה' בלא וא\"ו.\n<b>והענין</b> הוא דהנה איתא במדרש ס\"פ בא פי\"ט לשעבר אני וב\"ד הייתי מהלך לפניהם, דבמצרים כתיב וה' הולך לפניהם, אבל לע\"ל אני לבדי שנאמר כי ה' הולך לפניהם כו'. והחילוק הוא דהנה איתא במד\"ר פ' וארא פי\"ב כל מקום שנאמר וה' הוא ובית דינו של מעלה, הוא וסנקליטון שלו<sup data-n=\"128\">2</sup> עכ\"ל. וכ\"מ שנאמר ה' בלא וא\"ו מורה עצמותו בלא בית דינו. וצ\"ל כי לכאורה אינו מובן מה איכפת אם הוא ג\"כ עם בית דינו. אך הנה מתחלה צ\"ל ענין בית דין. והענין דהנה בית דין הוא בחי' אד' שהוא בחי' דין דינא דמלכותא דינא, והוא ענין מ\"ש כי שמש ומגן הוי' אלקים שאלקים הוא בחי' מגן ונרתק על בחי' הוי'<sup data-n=\"129\">3</sup>, כמו שלשמש יש מגן ונרתק שאם לא הי' המגן לא היו יכולים לקבל את אור השמש מפני תוקף בהירותו וע\"י המגן שמסתיר את אורו וזיוו יכולים לקבל את אורו כו', כך הוא ענין שמש ומגן הוי' כו' לפי שבחי' הוי' הוא מורה על עצמותו שהוא בחי' הי' והוה ויהי' כו', ואם הי' מאיר בחי' הוי' כמו שהוא לא היו יכולים לקבל העולמות והיו בטלים במציאות והי' כלא",[["127","1","<b>וה' פקד את שרה</b>: מאמר זה מיוסד והגהות על הנחה מד\"ה זה להצ\"צ בכת\"י 1063 נב, א ונמצא תוכנו בשינויים בד\"ה זה באוה\"ת וירא (כרך ד) תשנד, א ואילך. המיוסד על ד\"ה זה בביאוה\"ז לאדהאמ\"צ יא, ב ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ע' כה ואילך.\nלכמה מעניני המאמר ראה: מאמרי אדה\"ז על מארז\"ל ע' קפט ואילך. קצט ואילך. אוה\"ת וירא שם תשמח, ב ואילך. תשנא, א ואילך. שם (כרך ז) תתשצא, ב. ביאוה\"ז להצ\"צ (כרך א) ע' נז ואילך. שם (כרך ב) ע' תרלז. לקמן המשך והחרים ד\"ה ויאמר גו' מחר חודש. סה\"מ תרל\"ג ח\"א ע' רלח ואילך. רמז ואילך. תרנ\"ח ע' קעט ואילך.\nהמאמר נמצא בשינויים ובתוס' הגהות בד\"ה זה בסה\"מ תרמ\"ג (הוצאת תשמ\"ט) ע' רפג ואילך. וראה גם ד\"ה זה בסה\"מ תרמ\"ד ע' קנה-ו. תשמ\"ג (הוצאת תשס\"ב) ע' 44 ואילך."],["128","2","<b>במד\"ר פ' וארא. . הוא וסנקליטון שלו</b>: ראה בפי' המ\"כ למד\"ר שם: סנקליטון, פי' הערוך שרי יועציו."],["129","3","<b>שמש ומגן הוי' אלקים שאלקי'. . מגן ונרתק על בחי' הוי'</b>: ראה שעהיוה\"א רפ\"ד. תו\"א ויצא כא, ד. תו\"ח חיי שרה קכח, סע\"ב ואילך. ויצא כו, ג-ד."]]],[2000510115,"הי', וע\"כ כדי שיוכלו לקבל ולא יהיו בטלים כו' הוצרך להתצמצם ולהסתיר, וע\"י בחי' אלקים כו' עי\"ז יוכלו לקבל גילוי אורו כו', וזהו מ\"ש כבוד מלכותך יאמרו וגבורתך ידברו כו'. ובזה יובן מ\"ש וה' הוא ובית דינו דהיינו שהוי' נסתתר בבחי' בית דינו בחי' אד' שלא יהי' מאיר בחי' הוי' כמו שהוא רק ע\"י בחי' אד', ומ\"מ בלא בחי' שם הוי' המשותף בבחי' בית דינו (שזהו בחי' הוא שבבית דינו) לא היו יכולים לקבל כלל. וזהו מ\"ש בתחלה עלה במח' לברוא העולם במדה\"ד ואח\"כ שיתף מדה\"ר, לפי שאם הי' בחי' דין לבד לא היו ג\"כ יכולים לקבל, כ\"א ע\"י ב' הבחי' דהיינו ע\"י בחי' שם הוי' שנסתתר בבחי' שם אד' עי\"ז יכולים לקבל.\nב) <b>ובזה</b> יובן המדרש שבמצרים כתיב וה' הוא וב\"ד, דהיינו שהגם שעיקר יצ\"מ הי' כדי להיות גילוי שם הוי'<sup data-n=\"130\">4</sup>, כמ\"ש בפ' וארא לכן אמור לבנ\"י אני הוי' וכתי' אח\"כ וידעתם כי אני הוי' המוציא אתכם מתחת סבלות מצרים וכמ\"ש במ\"א, אך מ\"מ אינו מאיר אלא בבחי' שם אד' שהוא בחי' לבוש. וזהו מה שארז\"ל פסחים ד\"ן ע\"א ע\"פ זה שמי כו' לא כמו שאני נכתב אני נקרא נכתב בהוי' ונק' באד', לפי שעתה אינם יכולים לקבל גילוי שם הוי' כמו שהוא רק ע\"י בחי' לבוש, וזהו מ\"ש וה' בהיכל קדשו היכל גימ' אד' שהוא בחי' היכל ולבוש לבחי' שם הוי'. אבל לע\"ל כי הולך לפניהם ה' שיהי' גילוי שם הוי' בעצמו שלא ע\"י בחי' שם אד'.\n<b>ומ\"ש</b> לע\"ל והי' אור הלבנה כאור החמה ואור החמה<sup data-n=\"131\">5</sup> יהי' שבעתיים כו' שגם לע\"ל יהי' חילוקי מדריגות, מ\"מ יהי' הכל שם הוי'[ednref_30_ל] והיינו שאור הלבנה בחי' מל' שם אד' או שם אלקים יהי' במדרגת שם הוי'. וזהו שא' יעקב והי' הוי' לי לאלקי'<sup data-n=\"132\">6</sup> שבחי' שם הוי' יהי' במדרגת שם אלקי' דעכשיו, כי ז\"א לגבי עתיקא כאלקים יחשב, ומה שעכשיו הוא בחי' שם הוי' יחשב בחי' שם אלקים לע\"ל, שע\"י בחי' שם הוי' הלזה יתגלה בחי' שם הוי' דלעילא. וזהו מ\"ש ביום ההוא יהי' ה' אחד ושמו אחד וארז\"ל פסחים ד\"ן ע\"א, אטו האידנא לאו אחד הוא, לא כמו שאני נכתב אני נקרא, נכתב בשם הוי' יו\"ד ה\"א, ונק' בשם אד', אבל לע\"ל יהי' נק' כמו",[["130","4","<b>שעיקר יצ\"מ היה כדי להיות גילוי שם הוי'. . וכמ\"ש במ\"א</b>: ראה אוה\"ת וארא ע' רמ. סה\"מ תרכ\"ט ע' צד ואילך. עטר\"ת ע' שטו ואילך. תרפ\"א ס\"ע רב ואילך. לקמן ד\"ה וידבר גו' זאת חוקת."],["131","5","<b>והי' אור הלבנה כאור החמה ואור החמה יהי' שבעתיים. . א\"כ יהי' ג\"כ חילוקי מדריגות</b>: ראה ד\"ה זה תרמ\"ג שם: הרי לע\"ל יהי' ג\"כ חילוקי מדריגות חמה ולבנה שהו\"ע שמש ומגן הנ\"ל (ע' בלק\"ת פ' שמיני בדרוש המילואים פ\"ב כ' וז\"ל ושם אלקים נק' מגן וזהו ג\"כ ענין לבנה עכ\"ל). עיי\"ש."],["132","6","<b>וזהו שא' יעקב והי' הוי' לי לאלקים שבחי' שם הוי' יהי' במדריגת שם אלקים דעכשיו</b>: ראה תו\"א ויצא כא, ד. כב, ג. ובארוכה תו\"ח ויצא כו, ג-ד.\n\n[edn_30_ל] <b>שגם לע\"ל יהי' חילוקי מדריגות מ\"מ יהי' הכל שם הוי'</b>: בשוה\"ג נרשם בגוכי\"ק: והי' אור הלבנה כאור החמה כו' א\"כ יהי' ג\"כ חילוקי מדרגות, י\"ל לע\"ל יהי' נקרא שם הוי' דלעילא כמו שנכתב בשם הוי' דלתתא, אבל עכשיו הקרי שם אד'."]]],[2000510116,"שנכתב<sup data-n=\"133\">7</sup>, וזהו ושמו אחד שיהי' נק' בשם הוי' כמו שנכתב בשם הוי'. וגם הוי' אחד שב' בחי' הוי' יהי' אחד, והיינו כי עכשיו גילוי שם הוי' הוא ע\"י שם אד', שז\"ע שהקריאה היא בשם אד' שהקרי הוא בחי' הגילוי הוא בחי' שם אד' אנת אשתמודע אדון על כולא, והכתיב הוא בחי' ההעלם הוא ש' הוי', פי' שהוא בחי' שיתף מדה\"ר הנ\"ל ובחי' הוא שבבית דינו שלמעלה, אבל לע\"ל שיהי' נק' כמו שנכתב יהי' העילוי בב' בחי', היינו מה שהגילוי יהי' ע\"י בחי' שם הוי' שאינו מסתיר כ\"כ כמו בחי' שם אד', שהגם שזהו בחי' שם הוי' דלתתא מ\"מ הוא בחי' שם הוי' כו', וגם שהגילוי יהי' מבחי' שם הוי' דלעילא שיתגלה ע\"י בחי' שם הוי' דלתתא. וזהו והי' אור הלבנה כאור החמה, שאור הלבנה הוא בחי' שם אד' או שם אלקים יהי' כאור החמה הוא בחי' שמש הוי' כו', ואור החמה יהי' שבעתיים כאור שבעת הימים בחי' כתר בכלל, ובפרט הוא בחי' ז\"ת דעתיקא קדישא<sup data-n=\"134\">8</sup>, ונמצא כי הגם שלע\"ל יהי' ג\"כ חילוקי מדריגות מ\"מ יהי' הגילוי שלא בערך מכמו שהוא עכשיו שיהי' הגילוי מבחי' שם הוי' דלעילא, וז\"ע הוי' אחד דרך שם הוי' דלתתא שהוא בחי' ושמו אחד שיהי' נקרא כמו שנכתב שיתגלה בחי' שם הוי' שלא ע\"י לבוש דשם אד' כו'. ועפ\"ז יובן מ\"ש וה' פקד את שרה שהוא בחי' הוא ובית דינו דהיינו שהפקידה הוא מבחי' הוי' שמתלבש בשם אד'. אבל כדי שיהי' בחי' ויעש בפו\"מ הוא בבחי' שם הוי' שלמעלה מהתלבשות<sup data-n=\"135\">9</sup> בכלים כי עשי' לעילא.\nג) <b>אך</b> עדיין צ\"ל כיון דכתיב ויעש ה' כו' למה צריך לוה' פקד כו'. אך מתחלה צ\"ל משארז\"ל שלהי מו\"ק דך\"ח ע\"א דחיי בני ומזוני לאו בזכותא תליא אלא במזלא<sup data-n=\"136\">10</sup>, ולכאורה אינו מובן שהרי כתיב ועבדתם את ה' כו' וברך את לחמך כו' לא תהי' משכלה כו' את מספר ימיך אמלא, הלא מבואר בפסוק זה בני חיי ומזוני<sup data-n=\"137\">11</sup> ובתנאי שיהי' דוקא בבחי' עובד אלקים שזהו מ\"ש ועבדתם כו' שהוא בחי' זכות, וכן נמי כתיב אם בחוקתי תלכו ונתתי גשמיכם כו' וכתיב והי' אם שמוע תשמעו כו' ונתתי מטר כו' ואספת דגנך כו' וכתיב למען ירבו ימיכם וימי בניכם כו', וכן כתיב נמי בעשרת הדברות שבפ' ואתחנן למען יאריכון ימיך ולמען ייטב לך כו', הרי מבואר שבני חיי ומזוני בזכותא דוקא תליא. וגם במד\"ר וירא פנ\"ג ע\"פ וה' פקד את שרה אמר ר' אחא הקב\"ה בעל פקדונות הוא, עמלק הפקיד אצלו חבילה של קוצים, והחזיר לו הקב\"ה חבילה של קוצים שנאמר פקדתי את אשר עשה עמלק לישראל (שמואל א' ט\"ו), שרה הפקידה אצלו מצות ומעשים טובים,",[["133","7","<b>ביום ההוא יהי' ה' אחד ושמו אחד. . לע\"ל יהי' נק' כמו שנכתב</b>: בהבא לקמן ראה בכ\"ז אוה\"ת תבוא ע' תתשי. תתשכח. ועוד."],["134","8","<b>ואור החמה יהי' שבעתיים כאור שבעת הימים. . ז\"ת דעתיקא קדישא</b>: ראה בכ\"ז לקו\"ת צו ט, ב ואילך."],["135","9","<b>וה' פקד. . בחי' הוא ובית דינו. . אבל. . בחי' ויעש בפו\"מ. . הוי' שלמעלה מהתלבשות</b>: ראה גם מד\"ר וירא פנ\"ג, ה: ר' נחמי' אמר וה' פקד את שרה כאשר אמר, מה שאמר לה ע\"י מלאך, ויעש ה' לשרה כאשר דבר מה שאמר לה הוא."],["136","10","<b>משארז\"ל. . דחיי בני ומזוני לאו בזכותא תליא אלא במזלא</b>: בהבא לקמן ראה סה\"מ תרל\"ג ח\"א ע' רלח ואילך. רמז ואילך. לקמן ד\"ה ויאמר גו' מחר חודש. וש\"נ."],["137","11","<b>וברך. . לא תהי' משכלה. . מבואר בפסוק זה בני חיי ומזוני</b>: ראה גם תו\"ח שמות (כת\"י הר\"ש סופר) תמ, א. ובהוצאת תשס\"ד ח\"ב דף שב, ג. סה\"מ תשי\"ב ע' 164."]]],[2000510117,"החזיר לה הקב\"ה מצות ומעשים טובים [שנא' וה' פקד את שרה]. נמצא מבואר שהפקידה שהופקדה שרה בבני להוליד את יצחק זהו מפני שהפקידה אצל הקב\"ה מצות ומעשים טובים, וא\"כ גם בני בזכותא תליא שזהו ע\"פ זכות דמצות ומעשים טובים דוקא. ועוד צ\"ל מש\"א במזלא תלי' והלא ארז\"ל שבת דקנ\"ו ע\"א וע\"ב אין מזל לישראל<sup data-n=\"138\">12</sup>.\n<b>אך</b> הנה מתחלה צ\"ל מהות ענין מזל<sup data-n=\"139\">13</sup>, דהנה נודע שלא כל הנשמה מתלבשת בגוף, שהרי מלאך בשליש עולם, והנשמה גבוה מבחי' מלאך וא\"כ איך יכולה להתלבש בגוף קטן כזה, אלא שרק הארה מהנשמה מתלבש בגוף, אבל עצמות הנשמה נשארת דבוקה למעלה באלקים חיים כו'. וזהו מ\"ש נשמה שנתת בי טהורה כו' ואתה משמרה, שיש שני בחי', א' שמתלבש בגוף בחי' ואתה נפחת בי כמ\"ש ויפח באפיו נשמת חיים, והב' שהיא רק בבחי' ואתה משמרה שהיא רק בבחי' מקיף ואינו מתלבש בגוף והוא בחי' חי' יחידה, דהנה יש ה' בחי' נר\"נ ח\"י, נר\"נ הם המתלבשים בגוף נשמה במוח ורוח בלב כו', אבל חי' יחידה אינם מתלבשים בגוף, ונק' בחי' מזלא ע\"ש יזל מים מדליו, ומזל הוא ל' פועל שהוא המקור להיות ההשפעה ורוח חיים להחיות רוח שפלים, גם שפע אלקי' והרהורי תשובה שבאים לאדם הם מכח המזל כו', אע\"ג דאיהו לא חזי מזלי' חזי שרואה ושומע הכרוזין שלמעלה ב\"ק יוצאת ומכרזת שובה כו', ועי\"ז משפעת למטה להיות התעוררות בלב כו', כי ההארה שירדה ונמשכה למטה בגוף אינו דבר נפרד לגמרי כו'. והנה כתיב ונוזלים מן לבנון שבחי' המזל נמשך מבחי' לבנון, שהוא ע\"ד והחכ' מאין תמצא כי החכ' תחי' שהיא ראשית התפשטות החיות נמשך מבחי' אין שהוא בחי' שלמעלה מהשכל והוא בחי' אין שאינו מושג, וזהו בחי' לבנון שהוא בחי' לב נו\"ן, לב הוא בחי' ל\"ב נתיבות חכמה ונו\"ן הוא בחי' נ' שערי בינה, דהיינו שהוא התחברות בחי' חו\"ב בחי' אין ויש, והממוצע המחברם גבוה משניהם שהוא בחי' אין.\nד) <b>והנה</b> כמו שיש שני בחי' בנשמה כמו\"כ יש ג\"כ באלקות, שארז\"ל בברכות דף יו\"ד ע\"א מה הקב\"ה מלא את כל העולם כך הנשמה מלאה את כל הגוף, ובמדרש תלים ע\"פ ברכי נפשי מה הנפש ממלאה את הגוף כך הקב\"ה ממלא את העולם, ויש בחי' אוא\"ס ב\"ה שקדוש ומובדל כו' וכמאמר איהו תפיס בכולא עלמין ולית מאן דתפיס בי', והיינו שיש ג\"כ שני בחי' אלו, בחי' המתלבש בעולמות שהוא בחי' ממכ\"ע, והב' מה שלמעלה מהתלבשות בעולמות שהוא בחי' סוכ\"ע, ונק' בחי' מזל, והיינו שהוא למעלה מבחי' חכ'. וזהו מ\"ש בזהר שנהר יוצא מעדן הוא בחי' מזל, והיינו לפי שנהר יוצא כו' להשקות את הגן, כי גן הוא בחי' מה שהנשמות יושבין ונהנין מזיו כו' שהוא בחי' השגה, אבל נהר יוצא מעדן הוא למעלה מהשגה והוא בחי' עדן עין לא ראתה, ומה שנהר זה משקה את הגן היינו שהארה מבחי' זו נמשך בגן",[["138","12","<b>מש\"א במזלא תליא והלא ארז\"ל. . אין מזל לישראל</b>: באוה\"ת וירא שם תשנה, ב מציין ע\"ז: וע' מזה בתוס' מו\"ק (דכ\"ח ע\"א) וסוף מס' שבת דקנ\"ו א' שנדחקו מאד בזה."],["139","13","<b>אין מזל לישראל. . צ\"ל מהות ענין מזל</b>: בהבא לקמן ראה בארוכה לקו\"ת האזינו עא, ד. שה\"ש טז, ד. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשנז. מאמרי אדהאמ\"צ דברים ח\"ד ע' א'קסט. וש\"נ."]]],[2000510118,"עדן שמשיגים הנשמות ע\"י זיו תורתן ועבודתן שלהם עצמם מה שעשו בעוה\"ז שז\"ע שכר מצוה מצוה, היינו הארה מבחי' התומ\"צ[ednref_31_לב] נמשך בג\"ע להתענג הנשמות שיושבין שם. וז\"ע ארים בסימא דנשמתא שנת' בזח\"א לך לך דע\"ז ע\"א, שנת' בד\"ה ויאמר כו' לך לך<sup data-n=\"140\">14</sup> שזהו בחי' תוס' אורות, היינו הארה מבחי' מזל שהוא בחי' נהר שיוצא מעדן בחי' עין לא ראתה כו', ועיקר גילוי בחי' זו יהי' לע\"ל[ednref_32_לא] כו', כמ\"ש במ\"א שע\"י העבודה בתומ\"צ דעכשיו מוסיפים תוס' אורות באצי'<sup data-n=\"141\">15</sup> ולע\"ל יתגלה בחי' [זו], ומ\"מ הארה מבחי' זו מאיר בג\"ע כו' שז\"ע ארים בסימא דנשמתא כו'.\n<b>ובזה</b> יובן משארז\"ל בני חיי כו' לאו בזכותא תליא אלא במזלא דאין הפי' במזלא דהיינו המזלות הקבועים בגלגל, שמזל מחכים מזל מעשיר כו', אשר ע\"ז ארז\"ל אין מזל לישראל כי חלק אותם ה' לכל העמים, אבל הפי' במזלא תליא היינו במזל העליון שהוא בחי' אוא\"ס מה שלמעלה מבחי' חכ', וכמאמר אבא יונק ממזלא, שאו\"א יונקים ממזל הח' מזל ונוצר שנק' מזל העליון ומזל הי\"ג ונקה<sup data-n=\"142\">16</sup>. וזהו לא בזכותא, דזכות הוא בבחי' חכ'. דהנה איתא שיש היכל הזכות, דהיינו שיושבין ודנין ע\"ב סנהדרין אם לזכות כו' כמ\"ש בזח\"ב פקודי דרנ\"א ודרנ\"ב שהוא היכל הגבורה, ומספר ע\"ב סנהדרין כנגד שם ע\"ב שהוא בחי' חסד, וזהו ע\"ד אחליפו דוכתי' שבפ' שמע והי' אם שמוע שהוא אור החסד בכלי הגבורה, ואור הגבורה בכלי החסד כמ\"ש במ\"א<sup data-n=\"143\">17</sup>. ועד\"ז כאן ההיכל הזכות עצמו הוא היכל הגבורה, והסנהדרין שיושבין לדין הם ע\"ב כמנין חסד, והם כנגד ע' סנהדרין ושני סופרי",[["140","14","<b>שנת' בד\"ה ויאמר כו' לך לך</b>: תרל\"א לעיל ס\"ע כו. וע' מ."],["141","15","<b>כמ\"ש במ\"א שע\"י העבודה בתומ\"צ דעכשיו מוסיפים תוס' אורות באצי'</b>: ראה לקו\"ת דברים א, ב. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפג. הנחות הר\"פ ע' נז. מאמרי אדהאמ\"צ ויקרא ח\"א ע' נה. ביאוה\"ז להצ\"צ ח\"א ע' תסג. סה\"מ תרכ\"ז ע' תסז. תרכ\"ט ע' רכח. ד\"ה פזר נתן תרמ\"ב. סה\"מ מלוקט ח\"א ע' ז."],["142","16","<b>שאו\"א יונקים ממזל הח'. . ונוצר. . ונקה</b>: ראה לקו\"ת קרח נד, ד. דרושים לחה\"ס פ, ג. וראה גם אגה\"ק סי' כח (קמח, א). ועוד."],["143","17","<b>אחליפו דוכתי' שבפ' שמע והי' אם שמוע שהוא אור החסד בכלי הגבורה. . כמ\"ש במ\"א</b>: ראה לקו\"ת ואתחנן יב, ד. סידור עם דא\"ח עג, ג ואילך. מאמרי אדה\"ז תקס\"ז ע' רפה ואילך. ענינים ע' סב ואילך. אוה\"ת בשלח ע' תקנז. דרמ\"צ קכ, סע\"א ואילך. סה\"מ תרכ\"ז ע' שלג. שמ. תרכ\"ט ע' רמה ואילך. המשך תער\"ב ח\"א ס\"ע כ ואילך. וראה גם ספר הערכים חב\"ד כרך ד ע' רח.\n\n[edn_31_לב] <b>אך מ\"מ צריך ג\"כ זכות של תומ\"צ</b>: בשולי הגליון נרשם בגוכי\"ק: בלק\"ת בשה\"ש בביאור ע\"פ אני ישינה בפי' פתחי לי כחודה<sup data-n=\"1625\">158</sup>.\n\n[edn_32_לא] <b>הארה מבחי'. . נהר שיוצא מעדן. . ועיקר גילוי בחי' זו יהי' לע\"ל</b>: בשולי הגליון נרשם בגוכי\"ק: י\"ל הנהר הוא בחי' רוחא דכל רוחין שהוא מבינה כמ\"ש בזהר ויקהל דרל\"ח ב' רוח עילאה סתימאה, שהכוונה על בינה כמו שבה התגלות התענוג שלמעלה מהחכ'. ולכן מפרש ר\"י בזח\"א דע\"ז א' רוחא דכל רוחין על הגילוי שבג\"ע שזהו הארת עונג העליון שמתגלה לצדיקים מבחי' נהר הנ\"ל. ולע\"ל כשיהי' והניף ידו על הנהר והכהו לז' נחלים, י\"ל שיהי' הגילוי מבחי' ז\"ת דע\"י, ע\"י שיתגלה בתחה\"מ מבחי' טל תחי' ג\"ר דע\"י יהי' הגילוי בעולמות מבחי' ז\"ת דע\"י. וצ\"ע עדיין."],["1625","158","<b>בלקו\"ת בשה\"ש בביאור ע\"פ אני ישינה בפי' פתחי לי כחודה</b>: דף לה, ג. וראה ד\"ה וה' פקד תרמ\"ג שם: לא בזכותא תליא, ומ\"מ אמרו במדרש שנפקדה שרה מפני שהפקידה מצות ומעש\"ט כנ\"ל הרי צריכים זכות ג\"כ, ושניהם אמת, והוא ע\"ד שאמרז\"ל פתחו לי כחודה של מחט ואני אפתח לך כפתחו של אולם, דהאולם לא הי' לו דלתות ורומז על בחי' אתעדל\"ע שאין אתעדל\"ת מגיע לשם, ומ\"מ צ\"ל פתחו לי כחודה של מחט דהגם שאין אתעדל\"ת מגיע לשם מ\"מ אינו נמשך אלא דוקא כשיש שלימות למטה."]]],[2000510119,"הדיינין שכותבים דברי המזכין ודברי המחייבין כמארז\"ל בסנהדרין פ\"ד משנה ג', ושורש החסד הוא בחי' חכ' כי המדות מתנהגים עפ\"י חכ' כו'. וזהו לאו בזכותא תלי' שאין הב\"ד של מעלה יכולים לשפוט בעצמם ליתן לו בנים, כמו למשל שאנו רואים במלכותא דארעא שאע\"פ שיש בעלי משפט הדנין כל דבר מ\"מ דבר גדול אין יכולים לדון בעצמם וצריכים להעלות אצל המלך בעצמו והוא ישפוט כו', וזהו\"ע בני חיי ומזוני במזלא תליא שהוא בחי' אוא\"ס מה שלמעלה מבחי' חכ', לפי שהוא דבר גדול מאד מה שאין יכולים בעצמם לשפוט כו'. אך מ\"מ צריך ג\"כ זכות של תומ\"צ לפי שע\"י ב\"ד של מעלה נתעלה הדבר אל בחי' מזל העליון, וע\"כ נאמר ועבדתם כו' וברך את לחמך כו', לפי שתלוי ג\"כ בזכות שעי\"ז נתעלה הדבר אל בחי' אוא\"ס כו' מה שלמעלה מבחי' חכ'. ולכן גם גבי שרה א\"ר אחא שזהו ע\"י שהפקידה מצות ומעשים טובים דעי\"ז זכתה להפקד בב\"ד שלמעלה שיותן לה בן, אך הם עצמם אין ביכולתם ליתן כ\"א שפסקו ע\"י שהפקידה מצות ומעשים טובים עי\"ז ראוי' היא שתפקד בבנים, והעלו לבחי' אוא\"ס שלמעלה מבחי' חכ' הוא בחי' מזל העליון דונוצר, ומשם נמשך לשרה בן. ולכן הגם כי ויעש ה' לשרה כו', מ\"מ צ\"ל תחלה וה' פקד שהוא בחי' ב\"ד ששופטים הדבר לזכות תחלה ע\"פ החכ', ואח\"כ מעלים הדבר לבחי' אוא\"ס שלמעלה מהחכ' הוא בחי' מזל העליון דנוצר הנ\"ל, ומשם נמשך ויעש ה' כו'.\nה) <b>ובזה</b> יובן ג\"כ מש\"א וה' פקד כו' בוא\"ו ואח\"כ ויעש ה' כו', והיינו לפי שתחלה צ\"ל בחי' וה' פקד בחי' הוא וב\"ד, ואח\"כ שיהי' בחי' ויעש בחי' עשי' נאמר ויעש ה' בלא וא\"ו שהוא בחי' שם הוי' כמו שהוא למעלה מבחי' כלים דאצי'. וזהו שלע\"ל נאמר כי הולך לפניכם ה' והיינו שלמעלה יהי' התגלות כבוד מלכותו ית' על כולם וכמ\"ש והי' ה' למלך כו' כי עתה אינו רק בחי' מלך ישראל וכמ\"ש כה אמר ה' מלך ישראל[ednref_33_לג] כו', אבל לע\"ל והי' ה' למלך על כל הארץ כי אז",[["","","[edn_33_לג] <b>עתה אינו רק בחי' מלך ישראל וכמ\"ש כה אמר ה' מלך ישראל</b>: בשולי הגליון נרשם בגוכי\"ק: בענין אלקי ישראל, ע' בספר יהושע ישעי' סי' מ\"ד וא\"ו בד\"ה כה אמר כו'<sup data-n=\"1626\">159</sup> ס\"ו דף רל\"ב ע\"א."],["1626","159","<b>ע' בספר יהושע ישעי'. . בד\"ה כה אמר כו'</b>: ראה אוה\"ת נ\"ך (כרך א) ס\"ע רמג: עכשיו בחי' ואני בתוך הגולה היינו ואני אחרון דהיינו מל' דעשי' המלובשת בק\"נ, ולע\"ל כתיב מלך ישראל וגואלו פי' שגואל בחי' מלך היינו מל' דעשי' ואזי יהי' אני ראשון ואני אחרון בשוה כי המל' נעשית כתר מלמטה למעלה כו'."]]],[2000510120,"אהפוך אל עמים שפה ברורה לקרוא כולם בשם הוי' ולעבדו שכם א'. ומ\"מ י\"ל ע\"ד ההפרש שעכשיו בין בן כרך ובן כפר<sup data-n=\"144\">18</sup>, או כמו שרי מלוכה ורואי פני המלך, ויש בני מלכים<sup data-n=\"145\">19</sup> כו'. וזהו ג\"כ שמתחלה נק' שרי, כי שרה לשון שררה בחי' מל', ושרי הוא בחי' רק מלך ישראל, אבל שרה הוא גילוי מלכותו על הכל, וכמארז\"ל שרי היא שרה, שרי לאומתה (שרי ל' יחיד משמע שרתי) ולבסוף נעשית שרה לכל העולם כולו בגמ' ספ\"ק דברכות די\"ג א' ובר\"פ מ\"ז ברבות באו\"א קצת דקאמר שרי לעצמה<sup data-n=\"146\">20</sup>. וזהו שילדה את יצחק צחוק עשה לי כו' לשון תענוג שיהי' לע\"ל, נאמר ה' בלא וא\"ו כו', ומענין ויעש יובן ג\"כ ענין מעשה המצות שהם גבוהים מאד וכמ\"ש רז\"ל נמנו וגמרו תלמוד גדול שמביא לידי מעשה וזיל בתר טעמא והיינו לפי שעיקר תכלית הבריאה שיהי' גילוי אלקות מה שאינו עפ\"י השתלשלות וזה נק' בחי' עשי' כי המשכת תוס' אורות מה שלא עפ\"י השתלשלות נק' עשי' וזהו עין לא ראתה יעשה ל' עשי', וכן כתיב השמים החדשים אשר אני עושה והמשכת אורות אלו ממשיכים ע\"י מעשה המצות שהוא עשי' בפ\"מ ע\"כ מעשה גדול ולכן אמר בזהר עשי' לעילא, אך מ\"מ תלמוד גדול שמביא לידי מעשה<sup data-n=\"147\">21</sup> שזהו שנאמר וה' פקד שצ\"ל מקודם ע\"פ ב\"ד שמקבלין ודנין ע\"פ החכמה כו' וד\"ל.",[["144","18","<b>ומ\"מ י\"ל ע\"ד ההפרש שעכשיו בין בן כרך ובן כפר</b>: ראה ד\"ה זה תרמ\"ג (שאף שלע\"ל יהי' הוי' למלך על כל הארץ, גם על אומות העולם): מ\"מ גם לע\"ל יהיו צדיקים במעלה עליונה יותר, ואפ\"ל שהרי ארז\"ל כאו\"א נכווה בחופתו של חבירו, וי\"ל ע\"ד ההפרש שעכשיו בין בן כרך ובן כפר. — אודות ההפרש בין בן כרך ובן כפר ראה בארוכה לקו\"ת ברכה צז, א-ב. סידור עם דא\"ח ריא, ב. אוה\"ת מג\"א (הוצאת תש\"נ) ע' ערה. סה\"מ תרכ\"ט ע' פג. תער\"ב-ע\"ו ע' שיא ואילך. תשי\"ד ע' 83 ואילך. תשל\"ז 169 ואילך. תשל\"ט (הוצאת תשס\"ב) ע' 119 ואילך. לקו\"ש חכ\"א ע' 202 ואילך. חל\"ג ע' 20 ואילך."],["145","19","<b>בין בן כרך ובן כפר או כמו שרי מלוכה. . ויש בני המלך</b>: ראה ד\"ה זה תרמ\"ג: ואפ\"ל דההפרש בין ב' המשלים, דבן כרך ובן כפר נא' על ישעי' שהוא כבן כרך שראה את המלך ויחזקאל כבן כפר, וידוע דנבואת ישעי' הי' מעולם הבריאה ונבואת יחזקאל עולם היצירה. והמשל הב' דשרים ובנים אפ\"ל דשרים ג\"כ באצי' וכמו ריב\"ז שאמר אני כשר לפני המלך."],["146","20","<b>וכמארז\"ל שרי היא שרה. . שרי לעצמה</b>: בגוכי\"ק נרשם כאן בתחילה: וכמארז\"ל ספ\"ק דברכות די\"ג א' שרי לאומתה (שרי ל' יחיד משמע שרתי) ולבסוף נעשה שרה לכל העולם כולו. ואח\"כ נרשם בגוכי\"ק הגה\"ה בצידי הגליון כבפנים."],["147","21","<b>אורות אלו ממשיכים ע\"י מעשה המצות. . ע\"כ מעשה גדול. . מ\"מ תלמוד גדול שמביא לידי מעשה</b>: ראה בארוכה בכ\"ז סה\"מ תרל\"ג ח\"ב ע' תעט ואילך. [ובהנסמן שם בתחילת המאמר]. תרל\"ד ע' פו ואילך."]]],[2000510121,"<h3>חיי שרה (א)</h3>\n<b></b><b>בס\"ד. ש\"פ חיי שרה<sup data-n=\"148\">1</sup>, ל\"א.</b>\n<b>חיי</b> שרה מאה שנה, ופי' בזהר מאה ברכות, שארז\"ל חייב אדם לברך מאה ברכות שלמדו זה ממ\"ש ועתה כו' מה כו' שואל מעמך א\"ת מ\"ה אלא מאה. ולכאורה צ\"ל הלא כתי' מה, ואיך כו'.\n<b>ויובן</b> בהקדם ההפרש בין ברכה להודאה דכתי' (דה\"א ך\"ט י\"ג) מודים אנחנו לך, משמע לעצמותו, אבל ברכה הוא רק לשמך כמ\"ש (בנחמי' ט' ה') ויברכו שם כבודך, וצ\"ל הלא כתיב בכל יום אברכך ואהללה כו', אברכך משמע לעצמותו כו'. הנה בנוסח הברכה יש נוכח ונסתר, ממכ\"ע וסוכ\"ע, אתה אותיות מאל\"ף ועד תי\"ו, דבר ה', בע\"מ נברא, אותיות הדבור עדאת\"ג, אותיות המח' עדאתכ\"ס, במאמר א' נבה\"ע כמ\"ש בזהר, וכ\"ז הוא ממכ\"ע. והברכה להמשיך ממקור ושורש ממכ\"ע, והיינו מבחי' כח המח', דהנה בנפש יש ב' בחי' לבושי' היינו ששכל ומדות הם ג\"כ אינם מעצמיות הנפש כמ\"ש בת\"א בד\"ה פתח אלי'<sup data-n=\"149\">2</sup> ובלק\"ת בביאור ולא תשבית<sup data-n=\"150\">3</sup>, כ\"א הם לבושי' עצמי' כמו גופין, ומחדו\"מ הם לבושים נפרדים, וכמו שבלבושים דשכל ומדות יש גילוי השכל וכח השכל המשכיל כל ההשכלות, כמו\"כ בלבושים דמחדו\"מ יש גילוי המח' ויש כח המח', אשר גילוי המח' הוא מה שבמח' א' נבה\"ע היא כלא נגדו כערך מח' א' נגד כלליות המח', ויותר מזה, והברכה היא להמשיך מבחי' כח המח' שיומשך בגילוי כו'. והנה סדר ההמשכה הוא תחלה בנש\"י כי ישראל עלו במח' משא\"כ מלאכים, ואח\"כ נמשך בעולם, וזהו שאומרים בק\"ש תחלה ה' אלקינו ואח\"כ אחד ז' רקיעי' וארץ וד' רוחות, וזהו ה' אלקינו ואח\"כ מלך העולם, מלוכה וממשלה, ממשלה בע\"כ, ומלוכה ברצון ה' מלך שיהי' גילוי ש' הוי', וכ\"ז הוא בחי' ממכ\"ע ל' נוכח. ול' נסתר אקב\"ו הוא בחי' סוכ\"ע, אך א\"א להמשיך מבחי' סוכ\"ע כ\"א שתחלה צ\"ל בחי' ממכ\"ע, ואח\"כ כו'. והברכה עושים על המצות שהם בחי' גבוה תרי\"ג וז' תר\"ך עמודי אור בחי' כתר. ועוי\"ל שהמצות הם בחי' ביטול, כי נחלקים לג' בחי' תורה ועבודה וגמ\"ח, עבודה קרבנות שנכלל באש שלמעלה, תפלה במקום תמידין להקריב נה\"ב ברשפי אש האהבה, תורה כל האומר אין לי אלא תורה אפי' תורה אין לו שצ\"ל בבחי' ביטול, וגמ\"ח הרי הוא מצמצם א\"ע וגומל חסד ונותן צדקה. וזהו מה ה' אלקיך שואל מעמך, ששואל מעמך בחי' יר\"ש שיש אצלך כי אדם אתם אדם גימ' מ\"ה בחי' ביטול שיש בנפש, וע\"י בחי' מ\"ה זה ממשיכין בחי' מאה כמשי\"ת. ולכן כל ההמשכה הוא ע\"י מ\"ה, דאיהו אורח האצי', ואיהו שקיו כו'.",[["148","1","<b>חיי שרה</b>: הוא קיצור ורישומי דברים מהמאמר שלאח\"ז ד\"ה ויהיו חיי שרה (הב'), אך ישנם כאן כמה ענינים שאינם בהמאמר שלאח\"ז.\nלכללות המאמר ראה בהנסמן לקמן בהמאמר שלאח\"ז, ולא נסמנו כאן עוה\"פ רוב המ\"מ וציונים שכבר נסמנו שם."],["149","2","<b>כמ\"ש בת\"א בד\"ה פתח אלי'</b>: דף יג, ג."],["150","3","<b>ובלק\"ת בביאור ולא תשבית</b>: פ' ויקרא ד, ב. וראה גם סה\"מ תרכ\"ז ע' תנז. ובהנסמן שם."]]],[2000510122,"<b>ומעתה</b> יובן שהברכה היא בבחי' שמך אבל לעצמותו הוא רק בחי' הודאה, דהנה חכ' היא ראשית ההשתלשלות, פי' השתלשלות שיש להם ערך זל\"ז שבי\"ע יש להם ערך לאצי' כמ\"ש בד\"ה פתח אלי' הנ\"ל, שבאצי' גופא יש אבי\"ע חו\"ב ז\"א ומל', שאימא מקננא בבריאה והם ד' אותיות ש' הוי' יו\"ד באצי' ה' בבריאה ו' ביצי' ה' בעשי', והרי הדבור יש לו ערך לגבי השכל שהרי אומרים שכל באותיות הדבור, אבל חכ' לגבי אוא\"ס אין ערוך כלל, ומאין תמצא כמו המוצא מציאה שא\"י מאין באה, וכמו\"כ התהוות החכ' מא\"ס כי אנת הוא חד ולא בחושבן כו'.\n<b>ועפ\"ז</b> יובן ההפרש בין ברכה להודאה, שברכה היא המשכה מבחי' שורש ומקור שהוא מבחי' חכ' ראשית ההשתלשלות שיומשך בבחי' גילוי, ולכן החכמים תקנו הברכות שהם עיני העדה בחי' ראי' שיומשך בבחי' ראי' וגילוי כו', אבל באוא\"ס ב\"ה שלמעלה מהחכ' אינו שייך בחי' ברכה כ\"א הודאה בלבד. וענין בחי' ברכה בנפש כי יש אמונה וברכה, אמונה היא רק בבחי' מקיף, ולכן הגם שמאמין יכול להיות מעוברי רצונו, כענין גנבא אפום מחתרתא שהגם שעובר רצונו מ\"מ הוא רחמנא קרי', שזה הוראה שאצלו הוא רק האמונה בבחי' מקיף שאינו פועל בפנימיותו שלא יעבור רצונו ית', וכל ענין הברכה להיות וידעת היום בבחי' ידיעה והכרה והרגשה שיתאמת אצלו כאילו רואה, וז\"ע צדיק באמונתו יחי' שיהי' לו חיות בהאמונה, והיינו ע\"י צדיק מאה ברכות יו\"ד קדישים ד' קדושות צדי\"ק אמנים, זהו בחי' ברכה. אמנם כ\"ז הוא בבחי' ש' הוי' שז\"ע ויברכו את שם שבבחי' זו שייך ברכה, אבל בעצמותו הוא רק מודים אנחנו לך כי לית מת\"ב כלל, שאפי' ח\"ע ג\"כ אינו משיג מהות הא\"ס, ע' בזח\"א חיי קך\"ב א' מח' ויובלא, לכן זהו רק בבחי' הודאה הגם כי אינו משיג מ\"מ מודה שכן הוא, וזהו מודים אנחנו לך לעצמותו, אבל בבחי' שמו שייך ברכה שיומשך בגילוי כל, וזהו ויברכו את שם.\n<b>ומעתה</b> צ\"ל הלא כתי' אברכך משמע עצמותו כו'. ויובן בהקדם ענין מה שנבה\"ע בבי\"ת ולא באל\"ף שך\"ו דורות קרא האל\"ף תגר על שלא נבה\"ע בו שהוא ראשון לכל האותיות עד שבמ\"ת פתח באל\"ף אנכי, ונת' הטעם בזהר לפי שא' ר\"ת ארור, ובי\"ת ר\"ת ברכה, ולכאורה א\"מ שהרי אל\"ף הוא אותיות פלא, ומרמז על בחי' אני ראשון ואני אחרון ובשביל שהוא ר\"ת ארור לא נברא בו העולם, וגם צ\"ל דא\"כ איך התחיל במ\"ת באל\"ף. אך הענין הוא דהנה כלליות התומ\"צ הם בחי' צמצום שצמצם א\"ע כבי' שזהו שאמר הכתוב תען כו' כי כל מצותיך צדק, שנמשלו לצדקה שכמו ענין הצדקה שמצמצם א\"ע ונותן לעני, כך כלליות התומ\"צ הם צמצומים שמצד עצמו אם חטאת כו' ורבו פשעיך כו' אם צדקת כו' שאינו תופס מקום כלל רק שצמצם א\"ע בבחי' רצון התומ\"צ. וזהו שארז\"ל אנכי ולא יהי' מפי הגבורה כו', שאנכי מקור רמ\"ח מ\"ע, ולא יהי' מקור שס\"ה ל\"ת, מפי הגבורה, פי' גבורה הוא צמצום שצמצם בבחי' רצון אותיות צינור להיות התומ\"צ כי מצ\"ע כחשיכה כאורה כו', ולכן כתיב הלא אח עשו ליעקב שמצד עצמותו שוה, רק שצמצם להיות ואוהב את יעקב כו'. וזהו שלא נבה\"ע"],[2000510123,"באל\"ף כי מבחי' אל\"ף הי' יכול להיות נמשך לכולם בשוה שאל\"ף בחי' פלא בחי' אני ראשון כו' שם כחשיכה כאורה שאינו תופס מקום, והי' נמשך ע\"ד שאה\"כ זכרנו את הדגה אשר נאכל במצרים חנם, דגה הוא בחי' השפעה שנמשכה חנם בלא מצות, ולא הי' נמשך גילוי אלקות, ועיקר המכוון הי' שלהיות כי נתאוה הקב\"ה להיות לו דירה בתחתונים שזהו ע\"י התומ\"צ דוקא. וזהו שאמר בזהר שא' ר\"ת ארור היינו שמאל\"ף יכולים גם י\"א ארורים לקבל היינו בחי' ארור כנען (ואליעזר יצא מכלל ארור שלבן הוציאו מכלל ארור שא\"ל בא ברוך ה' הוציאו מכלל ארור לכלל ברוך), לכן נבה\"ע בבי\"ת שמרמז על בחי' חכ' כמ\"ש בחכמה יבנה בית בי\"ת דבראשית, כמ\"ש בראשית ות\"י בחוכמתא, וע\"פ החכ' יש חילוקי מדריגות שז\"ע כשר פסול טמא טהור שזה יוכל לעלות וזה לא יוכל כ\"א בדרך דחי' כמ\"ש במ\"א<sup data-n=\"151\">4</sup>, ולכן ע\"פ החכ' אינו נמשך כ\"א למקום הראוי דוקא, וזהו בראשית בשביל התורה שנק' ראשית ובשביל ישראל שנק' ראשית, היינו שע\"פ החכ' אינו נמשך כ\"א לנש\"י דוקא. ואח\"כ הי' מ\"ת באל\"ף שהגם שמאל\"ף יכולים הכל לקבל כנ\"ל, זהו מאל\"ף עצמו, אבל מאחר שכבר נבה\"ע בבי\"ת בחי' צמצום החכ' הנה אח\"כ כשנמשך מבחי' אל\"ף אינו נמשך ג\"כ כ\"א למקום הראוי דוקא. וזהו אנכי הוי' שנמשך מבחי' אנכי דרך ש' הוי' יו\"ד צמצום דחכ' כנ\"ל שיו\"ד באצי' בחי' חכ', ולכן הי' מ\"ת אחר ך\"ו דורות מבריאת העולם כדי שיומשך ש' הוי' בעולם שע\"י ך\"ו דור כמספר ש' הוי' נמשך בחי' ש' הוי' בעולם ואז הגם שנמשך מבחי' אל\"ף בחי' אנכי ג\"כ אינו נמשך כ\"א למקום הראוי כו', וכמ\"ש אם תגביהי כנשר הוא בחי' דרך הנשר בשמים בחי' מקיפים עליונים ששם אינו תופס מקום אם צדקת כו' מ\"מ משם אורידך נאום הוי', שמאחר שנמשך דרך ש' הוי' א\"י לקבל כי נמשך רק למקום הראוי כו'.\n<b>ועפ\"ז</b> יובן ענין מה שלמדו רז\"ל א\"ת מה אלא מאה, שההפרש בין מ\"ה למאה הוא באות א', והיינו שע\"י בחי' הביטול דמ\"ה שבחכמה, כי חכ' היא כח מ\"ה, וע\"י בחי' מ\"ה ממשיכים בחי' האל\"ף דאנכי הנמשך ונעשה מאה. וזהו בכל יום אברכך שהברכה היא לעצמותו למעלה מבחי' חכ', והיינו כי סתם ברכה היא בחכמה, כמ\"ש בתיקונים ובזהר איהו ברוך ואיהי ברכה, איהו ברוך בחי' יסו\"א שנק' ברוך, ואיהי ברכה שבחי' מל' מקבלת הברכה מבחי' יסו\"א. א\"נ איהי ברכה קאי על יסוד אימא. אמנם ע\"י מאה ברכות ממשיכים האל\"ף בבחי' מ\"ה שז\"ע אברכך שמשמע אוא\"ס ב\"ה עצמותו שלמעלה מבחי' חכ' שיומשך בבחי' מ\"ה דחכ' כו'.\n<b>וז\"ע</b> חיי שרה מאה שנה, שרה ל' שררה מל', כי שרית בחי' מל', וחיי שרה הוא שמקבלת מבחי' מאה בחי' כתר. אך זהו ע\"י עשרים שנה בחי' חו\"ב שנק' תרדל\"מ, שז\"ע יו\"ד עם המילוי, שהמילוי הוא ו\"ד שעולה ג\"כ מספר עשרה,",[["151","4","<b>וע\"פ החכ' יש חילוקי מדריגות. . שזה יוכל לעלות וזה לא יוכל כ\"א בדרך דחי' כמ\"ש במ\"א</b>: ראה בארוכה אוה\"ת נ\"ך ע' תתקפ ואילך. ובכ\"מ."]]],[2000510124,"וכשמדבר אות יו\"ד בהכרח לומר גם המילוי, כי כשחושב או כשכותב יכול לחשוב או לכתוב הנקודה של היו\"ד בעצמה, אבל כשמדבר בהכרח להוציא גם המילוי כו', ונמצא כי המילוי הוא הגילוי לזולתו שכאשר רצונו לגלות אות יו\"ד לזולתו בהכרח לומר גם המילוי כו', וזהו בחי' בינה בחי' גילוי החכ' כשבא בבחי' השגה והבנה, כי חכ' הוא בחי' נקודה של היו\"ד היא עדיין בחי' ברק המבריק בחי' בריקת וסקירת השכל שאינה בבחי' השגה עדיין כמ\"ש מזה במ\"א<sup data-n=\"152\">5</sup>, וז\"ע ביו\"ד נברא העוה\"ב, עוה\"ב בחי' צדיקים יושבים ונהנים שהוא בחי' השגה זה נברא ביו\"ד בחי' חכ' כו'. ובכדי שיומשך מבחי' מאה בחי' כתר לבחי' שרה היא המל', זהו ע\"י אמצעות העשרים בחי' חו\"ב וכנ\"ל שכאשר נמשך מבחי' אל\"ף צ\"ל ע\"י החכמה דוקא בכדי שלא יומשך רק למקום הראוי כו', וכמו\"כ בענין חיי שרה כו'. ולכן משה חי ק\"ך שנה שמתן תורה הי' ע\"י משה, והתורה אם כי אורייתא מחכ' נפקת זהו רק שיצאה מחכ' אבל שרשה ומקורה היא בבחי' הכתר וכמ\"ש ואהי' אצלו שעשועי', בחי' שעשועי המלך כו' ולכן נענש דוד על שקרא ד\"ת זמירות, כי באמת לא ידע אנוש ערכה ואלקים הבין דרכה כמ\"ש מזה במ\"א<sup data-n=\"153\">6</sup>, וי\"ל שלכן אורייתא מחכ' נפקת בכדי שלא יומשך כ\"א למקום הראוי כו', ומשה שקיבל תורה מסיני חי ק\"ך שנה להורות על ראשית ההמשכה שמבחי' כתר ושנמשכה ע\"י חו\"ב שהם בחי' עשרים שנה. ושבע שנים זהו בחי' ז' מדות, כי כדי שיומשך בעלמא דאתגלי' צ\"ל נמשך ע\"י בחי' מדות דוקא, שאל\"כ הי' נשאר ההמשכה בבחי' עלמין סתימין כו' וע\"י המדות מאיר בדבור בחי' מל' עלמא דאתגליא כו'.\n<b>ובכ\"ז</b> יובן מאמר ר\"ע במד\"ר מה זכתה אסתר למלוך על קך\"ז מדינות, אמר הקב\"ה תבוא אסתר בת בתה של שרה שחייתה קך\"ז שנים ותמלוך על מאה ועשרים ושבע מדינה, דלכאורה אין לו הבנה מה שייך קך\"ז מדינות לחיי שרה. אך הענין דכתי' המולך מהודו ועד כוש, פי' הודו הוא כמ\"ש הוד והדר לבשת שבשעת ברה\"ע לבש לבוש דבחי' הוד והדר, והגם שנברא העולם בבי\"ת כנ\"ל מ\"מ האיר מבחי' לבוש דהוד והדר, ולכן אור שנברא ביום ראשון הי' אדם מביט מסוף העולם ועד סופו שהי' מאיר גילוי אלקות מבחי' הוד והדר בחי' כתר דרך הבי\"ת דחכ' כו' ורק שע\"י חטא עה\"ד נחסרו המאורות כו', ופי' כוש הוא ל' שחרות היינו בחי' אלביש שמים קדרות כו' ומ\"מ כתיב המולך מהודו ועד כוש שגם בבחי' אלביש שמים קדרות יכולים ג\"כ להמשיך מבחי' הוד והדר, ע' בד\"ה דבר ואמרת<sup data-n=\"154\">7</sup>. אך כדי שיומשך מבחי' הוד והדר צ\"ל מאה ועשרים ושבע, היינו שיתלבש בחי' לבוש דהוד והדר בחי' לבושי' כתלג חיור בבחי' עשרים בחי' חו\"ב",[["152","5","<b>חכ'. . נקודה. . ברק המבריק. . שאינה בבחי' השגה עדיין כמ\"ש מזה במ\"א</b>: ראה בארוכה ביאוה\"ז להצ\"צ ח\"א ע' תקיג ואילך. וראה גם דרך מצותיך ב, א ואילך. ועוד."],["153","6","<b>ולכן נענש דוד על שקרא ד\"ת זמירות. . כמ\"ש מזה במ\"א</b>: ראה קו\"א לתניא ד\"ה דוד זמירות (קס, א ואילך). לקו\"ת במדבר יח, א ואילך. סה\"מ תרכ\"ז ס\"ע רצד ואילך. ס\"ע שצא ואילך. תרג ואילך. וש\"נ. תרכ\"ט ע' תה. וש\"נ."],["154","7","<b>ע' בד\"ה דבר ואמרת</b>: ראה באוה\"ת בהעלותך ע' שלג (שם נת' בענין הוד והדר). וראה גם ד\"ה דבר גו' ואמרת בסה\"מ תר\"ל ע' קעא."]]],[2000510125,"כדי שלא יהי' יניקה לחיצוני', ואח\"כ בשבע בחי' ז' מדות בכדי שיומשך בעדאת\"ג, וזהו תבוא אסתר כו' של שרה שחי' קך\"ז שנים שהוא מבחי' כתר ע\"י חו\"ב וז' מדות, ותמלוך על קך\"ז שעי\"ז נמשך מבחי' הוד והדר לבחי' מל' שז\"ע המולך מהודו ועד כוש, כמו שחיי שרה הוא מבחי' מאה דכתר שכלול יו\"ד מיו\"ד ע\"י עשרים חו\"ב ושבע ז' מדות כו'."],[2000510126,"<h3>ויהיו חיי שרה כו' (ב)</h3>\n<b>בס\"ד.</b>\n<b>ויהיו</b> חיי שרה<sup data-n=\"155\">1</sup> מאה שנה ועשרים שנה ושבע שנים שני חיי שרה כו'. בזהר חיי שרה פי' שמאה שנה הוא רזא דמאה ברכאן<sup data-n=\"156\">2</sup> שחייב אדם לברך מאה ברכות בכל יום, וכמו שלמדו רז\"ל מפסוק ועתה מה ה' אלקיך שואל מעמך א\"ת מה אלא מאה, שחייב אדם לברך מאה ברכות בכל יום כו'. והנה יש להבין איך לומדים זה מפסוק זה שהרי לא נאמר בפירוש מאה, ומניין להם לומר א\"ת מה אלא מאה כו'.\n<b>אך</b> הענין הוא דהנה מתחילה י\"ל החילוק שבין ברכה להודאה<sup data-n=\"157\">3</sup>, דהנה כתיב (דה\"א ך\"ט י\"ג) מודים אנחנו לך, שמשמע מזה שהודאה היא לעצמותו ומהותו ממש<sup data-n=\"158\">4</sup>, וברכה היא רק לשמך דכתיב (נחמי' ט' ה') ויברכו שם כבודך. ולכאורה אינו מובן",[["155","1","<b>ויהיו חיי שרה</b>: לכללות המאמר (עד פיסקא: וזהו ענין ויהיו חיי שרה) ראה ביאוה\"ז להצ\"צ ח\"א ע' תקעא-ב. תקעט. וחלקו (עד פיסקא: ועתה י\"ל מ\"ש) מיוסד על ד\"ה ועתה אלקינו באוה\"ת חנוכה (כרך ה) תתקלה, א ואילך. וראה גם מאמרי אדה\"ז תקס\"ח ח\"ב ע' תשז ואילך.\nעניני המאמר נמצאים בשינויים לקמן בד\"ה אר\"ע מה זכתה אסתר, ובד\"ה כי הנה יוצר הרים תרל\"א (לקמן ע' קצט ואילך. וע' רה ואילך). ד\"ה כי הנה יוצר הרים בסה\"מ תרל\"ב ח\"ב ע' תקנד ואילך. תרל\"ד ע' לו ואילך. ד\"ה להבין כו' הברכה דיוצר האדם תרמ\"ב נדפס בסה\"מ דרושי חתונה לכ\"ק אדמו\"ר מהר\"ש ע' קסב ואילך.\nהמאמר נמצא בשינויים ובתוס' הגהות בד\"ה זה בסה\"מ תרמ\"ג ע' טו ואילך. [ההגהות הם רק לחלקו הראשון של המאמר. ובהוספות לשם (ע' שיא בהוצאת תשמ\"ט) נדפס בשלימותו המאמר דתרל\"א]. וראה תוכן המאמר בשינויים בד\"ה זה תשמ\"ג ובד\"ה זה תנש\"א (סה\"מ מלוקט ח\"ה ע' סה ואילך)."],["156","2","<b>בזהר חיי שרה פי' שמאה שנה הוא רזא דמאה ברכאן</b>: נת' בארוכה בביאוה\"ז לאדהאמ\"צ יב, ג ואילך. קלא, ב ואילך. (ובהנסמן לקמן פיסקא: וזהו ענין ויהיו חיי שרה)."],["157","3","<b>אך הענין הוא. . החילוק שבין ברכה להודאה</b>: בהבא לקמן בפיסקא זו ראה אוה\"ת חנוכה שם תתקלה, א. תתקלז, א. אוה\"ת נ\"ך (כרך ב) ע' תתקנט ואילך. וראה גם תו\"א בשלח סו, ג. מג\"א צז, רע\"א. קכא, ד. לקו\"ת פקודי ד, רע\"ג. מסעי פט, רע\"א. דברים א, א. עקב טז, סע\"ד. סידור עם דא\"ח קח, ג. קסה, ב ואילך. שה, ד. [ובדרושים שנסמנו לעיל בתחילת המאמר]."],["158","4","<b>שהודאה היא לעצמותו ומהותו ממש</b>: בד\"ה זה תרמ\"ג מוסיף: וכמ\"ש הטוב שמך ולך נאה להודות, דטוב הוא מצד השגה וזה שייך בבחי' שמך, אבל לך היינו לא\"ס עצומ\"ה רק נאה להודות."]]],[2000510127,"שהרי כתיב ג\"כ בכל יום אברכך ואהללה שמך לעולם ועד, שמשמע מדכתיב אברכך שברכה היא ג\"כ לעצמותו ממש רק הילול הוא לשמך.\n<b>והענין</b> הוא דהנה בנוסח הברכה יש לשון נוכח ול' נסתר<sup data-n=\"159\">5</sup>, ברוך אתה הוי' הוא לשון נוכח, אשר קדשנו במצותיו וצונו הוא ל' נסתר. והענין הוא דנוכח ונסתר הוא כנגד בחי' ממכ\"ע וסוכ\"ע, כי לשון נוכח הוא כנגד בחי' ממכ\"ע, וזהו אתה הוי', כי אתה הוא אותיות שמא' ועד תי\"ו וה' מוצאות הפה שנבראו בהם שמים וארץ שהם מתלבשים בתוך העולמות ממש בבחי' כח הפועל בנפעל כו', ויש שני בחי' אותיות, אותיות הדיבור ואותיות המחשבה, שמאותיות הדבור נתהווה עלמין דאתגליין, ומאותיות המחשבה נתהווה עלמין סתימין דלא אתגליין וכמאמר במחשבה אחת נברא העולם, וכל זה הוא בחי' ממכ\"ע. והנה שורש ענין ברכה היא המשכה מבחי' מקור ממכ\"ע בבחי' אותיות אלו, דהיינו מבחי' כח המחשבה באותיות המחשבה, שיש ג\"כ כח המחשבה כמו שאנו רואים בנפש האדם שיש בו ב' מיני לבושים, ע' בת\"א בפ' וירא בד\"ה פתח אלי'<sup data-n=\"160\">6</sup>, וע' ג\"כ בלק\"ת פ' ויקרא בביאור ע\"פ ולא תשבית<sup data-n=\"161\">7</sup> מלח, והיינו שהשכל ומדות הם לבושים עצמים לנפש ע\"ד גופין, ומח' דבור ומעשה הם ג\"כ לבושים לנפש, רק שהם לבושים נפרדים. וכמו שיש בלבושים עצמי' דהיינו בשכל גילוי השכל וכח המשכיל, כך גם בלבושים של מחדומ\"ע יש ג\"כ גילוי המחשבה וכח המחשבה. והנה גילוי המח' שנתהווה ממנו עולמות הוא בטל בתכלית לגבי כח המחשבה כביטול מח' אחת לגבי כח המחשבה וכמאמר במחשבה אחת נברא העולם כו', שבטל לגבי בחי' כח המחשבה. וזהו ענין הברכה להמשיך ברכה והמשכה מבחי' כח המח' באותיות המחשבה. וסדר ההמשכה הוא בבחי' הוי' אלקינו דהיינו בבחי' נש\"י<sup data-n=\"162\">8</sup>, ע' בד\"ה את ה' האמרת (ל\"א)<sup data-n=\"163\">9</sup>, כי נשמות",[["159","5","<b>בנוסח הברכה יש לשון נוכח ול' נסתר</b>: ראה בכ\"ז לקו\"ת מסעי צא, ב ואילך. דרושים לשמע\"צ פח, א. וראה סה\"מ ה'ת\"ש ע' 148 ובהמ\"מ שם. ועוד."],["160","6","<b>בת\"א בפ' וירא בד\"ה פתח אלי'</b>: דף יג, ג."],["161","7","<b>בלק\"ת פ' ויקרא בביאור ע\"פ ולא תשבית</b>: דף ד, ב. וראה גם סה\"מ תרכ\"ז ע' תנז. וש\"נ."],["162","8","<b>הוי' אלקינו דהיינו בבחי' נש\"י. . כי נשמות ישראל עלו במח'</b>: בד\"ה זה תרמ\"ג שם מבאר הקשר בין הוי' אלקינו לבחי' מחשבה ישראל עלו במחשבה, כי הוי' אלקינו הוא חכ' ובינה, כידוע דמח' הוא בחי' חכ', כמאמר מחשבא ויובלא לא אתפרש לעלמין, יובלא הוא בינה ומחשבה חכ', וזהו דהוי' אלקינו מרמז על ההמשכה בנשמות ישראל שישראל עלו במחשבה."],["163","9","<b>ע' בד\"ה את הוי' האמרת (ל\"א)</b>: סה\"מ תר\"ל ע' רצו [והוא מר\"ה תרל\"א. —ראה כת\"י 356 בתחילתו, ועוד], וז\"ל: וזהו הוי' אלקינו, שאלקינו היינו הכח וחיות שלנו הוא מבחי' שם הוי' כו'."]]],[2000510128,"ישראל עלו במחשבה[ednref_34_לד], משא\"כ המלאכים נתהוו מבחי' דבור<sup data-n=\"164\">10</sup> עליון וכמ\"ש בדבר ה' שמים נעשו כו', וע\"כ תחלה נמשך בנש\"י, ואח\"כ מלך העולם שנמשך הגילוי גם בבחי' עולם שהוא מבחי' דבור כו'. וזהו ג\"כ מ\"ש שמע ישראל הוי' אלקינו, שמתחלה נמשך בנש\"י, ואח\"כ ה' אחד שנמשך הגילוי גם בעולמות, כי אחד הוא ז' רקיעים וארץ וד' רוחות העולם. וזהו מלך העולם, היינו שיהי' בחי' מלוכה בעולם, כי הנה כתיב וממשלתך בכל דור ודור, והחילוק בין מלוכה לממשלה הוא, כי ממשלה הוא בע\"כ, משא\"כ מלוכה הוא ברצון<sup data-n=\"165\">11</sup> כו' להיות ה' מלך, שבבחי' מלוכה מאיר גילוי שם הוי'[ednref_35_לה] וע\"י הברכה ממשיכים שיהי' גילוי בחי' מלוכה כו'. וזהו ענין לשון נוכח שהוא המשכה ממקור בחי' ממכ\"ע באותיות המח' ואותיות הדבור כו'. ואח\"כ אומרים לשון נסתר דהיינו שממשיכים ג\"כ מבחי' סוכ\"ע שהוא בחי' נסתר והיינו לפי שאינו מושג כלל, אך א\"א להמשיך מבחי' סוכ\"ע כ\"א שיומשך תחלה מבחי' ממכ\"ע<sup data-n=\"166\">12</sup> ואח\"כ יכולים להמשיך גם מבחי' סוכ\"ע כו', וזהו ענין הברכה שהוא המשכה מבחי' ממכ\"ע וסוכ\"ע.\n<b>והנה</b> הברכה היא על המצות דוקא לפי שמצות שרשן גבוה מאד כי תרי\"ג מצות דאורייתא וז' דרבנן הוא תר\"ך עמודי אור שהוא בחי' כתר סוכ\"ע. ועוד לפי שעיקר המצות הוא בחי' ביטול, כי המצות נחלקים לג' קוין וכמשארז\"ל על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח, והנה ג' קוין אלו הם בחי' ביטול, כמו עבודה הוא להקריב את נפש הבהמה ע\"ג המזבח ונכללת באש שלמעלה, וכן תפלה שבמקום קרבנות זהו ג\"כ להקריב נפש הבהמית ברשפי אש האהבה כו', וכן תורה כל האומר אין לי אלא תורה אפי' תורה אין לו<sup data-n=\"167\">13</sup>, וגמ\"ח הוא ג\"כ בבחי' ביטול שצריך ליתן מחיי נפשו גם לחבירו שזהו א\"א כ\"א ע\"י ביטול<sup data-n=\"168\">14</sup>.",[["164","10","<b>ישראל עלו במחשבה משא\"כ המלאכים נתהוו מבחי' דבור</b>: ראה תו\"א ס\"פ וישב ל, סע\"א-ב. לקו\"ת בחוקותי מה, א. ובכ\"מ."],["165","11","<b>ממשלה הוא בע\"כ משא\"כ מלוכה הוא ברצון</b>: ראה תו\"א בראשית ג, ד. יתרו עד, ד. לקו\"ת דברים א, רע\"ב. דרושים לר\"ה נה, סע\"ב. נו, סע\"ב. שה\"ש מד, סע\"ג. לקו\"ש חט\"ו ע' 237. וש\"נ."],["166","12","<b>א\"א להמשיך מבחי' סוכ\"ע כ\"א שיומשך תחלה מבחי' ממכ\"ע</b>: בד\"ה זה תרמ\"ג שם נוסף כאן הגה\"ה: ואפ\"ל הכוונה כשמגיעים לכל הבחי' שאפשר להשיג ע\"י אתעדל\"ת, אז מאיר ממילא גם מדרי' ובחי' שאין אתעדל\"ת מגיע לשם שאינו שורה אלא כשיש שלימות."],["167","13","<b>ג' קוין אלו הם בחי' ביטול. . וכן תורה. . אין לי אלא תורה אפי' תורה אין לו</b>: לעיל בד\"ה חיי שרה (הא') מוסיף כאן (השייכות דתורה לביטול): אפי' תורה אין לו שצ\"ל בבחי' ביטול."],["168","14","<b>וגמ\"ח. . א\"א כ\"א ע\"י ביטול</b>: ראה בארוכה סה\"מ תרנ\"ה ע' כא-ב. תש\"ב ע' 53 ואילך.\n\n[edn_34_לד] <b>ע' בד\"ה את ה' האמרת (ל\"א) כי נשמות ישראל עלו במחשבה</b>: בשולי הגליון נרשם בגוכי\"ק: [בד\"ה האמרת (ל\"א) נת' פי' אלקינו כוחינו וחיותינו וכ\"ה בתו\"א ובלק\"ת בכ\"ד<sup data-n=\"1627\">180</sup>, משא\"כ או\"ה אומרים רם כו', וכאן הטעם מפני כי נש\"י עלו במח'. ויש לחבר ב' הטעמים<sup data-n=\"1628\">181</sup>. ולכן נמשך בנש\"י קודם השרי מעלה שלהם מפני כי עלו במח', וגם אפי' המלאכים היותר עליונים ממתינים מלומר שירה עד שיאמרו ישראל כמ\"ש במ\"א ע\"פ ברן יחד כו' ואח\"כ ויריעו<sup data-n=\"1629\">187</sup> כו'].\n\n[edn_35_לה] <b>שבאצי'. . ד' בחי' אבי\"ע. . כנגד. . שם הוי'</b>: בשולי הגליון נרשם בגוכי\"ק: [ע' בד\"ה וה' פקד דתקס\"ז מענין אבי\"ע שבאצי'<sup data-n=\"1630\">189</sup>, וע' בביאור ע\"פ וכל העם רואים<sup data-n=\"1631\">190</sup> בענין ההפרש שבין דומם צומח לחי ומדבר כן הוא ההפרש בין י\"ה לו\"ה]."],["1627","180","<b>פי' אלקינו כוחינו וחיותינו וכ\"ה בתו\"א ובלק\"ת בכ\"ד</b>: ראה תו\"א בראשית ו, רע\"א. לקו\"ת פינחס פ, א. דרושים לר\"ה סב, ד. וראה גם לקו\"ת אחרי כו, א. בלק עד, ב. דרושים לשבת שובה סז, רע\"ג. ועוד."],["1628","181","<b>ויש לחבר ב' הטעמים</b>: בהמאמר כאן לא נת' הקשר בין ב' הטעמים, ונת' בד\"ה זה תרמ\"ג שם בהגה\"ה: ואפשר ר\"ל דפי' עלו במח' שהם עיקר המכוון ועיקר ברה\"ע הי' בשביל ישראל כו' וזהו כוחינו וחיותנו שנש\"י הם עיקר המכוון כו'. וזהו הוי' אלקינו דתחלה נמשך בנש\"י שהם עלו במח' פי' שהם עיקר המכוון, וזהו אלקינו כוחינו וחיותינו."],["1629","187","<b>כמ\"ש במ\"א ע\"פ ברן יחד כו' ואח\"כ ויריעו</b>: אוה\"ת נ\"ך ע' תרפד. (וש\"נ)."],["1630","189","<b>ע' בד\"ה וה' פקד דתקס\"ז מענין אבי\"ע שבאצי'</b>: מאמרי אדה\"ז על מארז\"ל וזהר ס\"ע קצ ואילך. וע' קצט ואילך. ובתוס' הגהות בביאוה\"ז להצ\"צ ח\"א ע' סב ואילך."],["1631","190","<b>וע' בביאור ע\"פ וכל העם רואים</b>: מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרמב ואילך."]]],[2000510129,"<b>והנה</b> בנפש יש ג\"כ בחי' ביטול וכמ\"ש ועתה ישראל מה ה' אלקיך שואל מעמך דהיינו מ\"ה שיש בנפש האדם, כי יש בנפש האדם בחי' ביטול וכמ\"ש אדם אתם אתם קרוים אדם כי אדם בגימ' מ\"ה, ועיקר ההמשכה הוא ע\"י בחי' ביטול דוקא וכמשארז\"ל א\"ת מ\"ה אלא מאה, דהיינו לפי שע\"י מ\"ה דוקא יכולים להמשיך מבחי' מאה שהוא בחי' כתר, וזהו מ\"ש בת\"ז שם מ\"ה מלגאו דאיהו אורח כל אצי' ואיהו שקיו דאילנא, שכל ההמשכות הוא ע\"י שם מ\"ה דוקא לפי שהוא בחי' ביטול כו'.\n<b>ועתה</b> י\"ל מה שברכה הוא רק לשמך, והודאה הוא לעצמותו. והענין הוא דהנה ידוע שחכ' היא ראשית ההשתלשלו', והנה ענין ההשתל' הוא שיש להם ערך, שאפי' עולמות בי\"ע שהם בבחי' בריאה מאין ליש יש להם ערך עכ\"פ לעולם האצי' כמ\"ש מזה בד\"ה פתח אלי'<sup data-n=\"169\">15</sup> הנ\"ל, וכידוע שבאצי' יש ג\"כ ד' בחי' אבי\"ע, והם חכמה ובינה ומדות ודבור, שחכמה היא עולם אצי', ובינה היא בחי' עולם הבריאה כי בינה מקננא בכורסייא, וז\"א בחי' יצי', ודבור בעולם עשי', שהם כנגד ד' אותיות של שם הוי', יו\"ד באצי', ה' בבריאה, ו' ביצי', ה' אחרונה בעשי' כו', נמצא שיש להם ערך כמו שבאצי' יש ערך לחכמה ובינה ומדות ודבור, כמו\"כ יש ג\"כ ערך לעולמות בי\"ע עם אצי', ואפי' לעולם עשי' עם עולם אצי' יש ג\"כ ערך, כמו שאנו רואים שהדבור אעפ\"י שהוא רחוק מבחי' שכל, מ\"מ יש להם ערך שהרי השכל נתלבש בדבור כו', משא\"כ התהוות חכ' מאא\"ס[ednref_36_לו] אינו בערך השתל' עו\"ע לפי שאין ערוך אלי' כלל וכמ\"ש אנת הוא חד ולא בחושבן שאינו בערך כלל, אלא מאין ליש ממש וכמ\"ש והחכ' מאין כו' בדרך מציאה כו', כולם בחכ' עשית שהחכ' נחשבת כעשי' לגבי א\"ס ב\"ה.\n<b>והנה</b> בזה יובן החילוק שבין ברכה להודאה<sup data-n=\"170\">16</sup>, דהנה ברכה הוא המשכה מהעלם אל הגילוי, וכמ\"ש ברוך ה' אלקי ישראל מן העולם ועד העולם<sup data-n=\"171\">17</sup> דהיינו מעלמא דאתכסי' לעלמא דאתגלי' שהיא המשכה בבחי' גילוי, וע\"כ אינו שייך לומר בחי' ברכה כ\"א בבחי' חכ' שהוא ראשית ההשתל', שיכולים להמשיך ברכה וגילוי מבחי'",[["169","15","<b>בד\"ה פתח אלי'</b>: תו\"א וירא שם יד, א ואילך."],["170","16","<b>והנה בזה יובן החילוק שבין ברכה להודאה</b>: בהבא לקמן עד סוף הפיסקא ראה אוה\"ת חנוכה שם תתקלז, א."],["171","17","<b>ברוך. . מן העולם ועד העולם דהיינו מעלמא דאתכסי' לעלמא דאתגליא</b>: ראה גם אוה\"ת בראשית (כרך ג) תקצה, א. יהל אור להצ\"צ ע' ריח-ט. סה\"מ תרל\"ג ח\"א ע' צה ואילך. סה\"מ תרל\"ח ע' צד.\n\n[edn_36_לו] <b>שאפי' בחי' ח\"ע ג\"כ אינו משיג מהות של אא\"ס</b>: בשולי הגליון נרשם בגוכי\"ק: כולם בחכ' עשית, כעשי'."]]],[2000510130,"חכ' שהוא מקור בחי' עלמא דאתכסי' כו'. וזהו שחכמים תיקנו הברכות והיינו לפי שחכמים הם עיני העדה בבחי' ראי'<sup data-n=\"172\">18</sup> וע\"כ הם תיקנו הברכות שהוא המשכה בבחי' גילוי וראי' כו'. ובנפש ענין הברכה הוא ג\"כ להמשיך בחי' ראי', כי יש אמונה וברכה<sup data-n=\"173\">19</sup>, אמונה היא רק בבחי' מקיף וע\"כ יכול לעשות ג\"כ ההיפוך וכמשארז\"ל גנבא אפום מחתרתא רחמנא קרי', וע' מזה בד\"ה ואהבת את (למ\"ד) בסופו<sup data-n=\"174\">20</sup>. וענין הברכה הוא להמשיך כח וחיות באמונה וכמ\"ש וצדיק באמונתו יחי', דהיינו שע\"י צדיק שהוא בחי' ק' ברכות וצ' אמנים ויו\"ד קדישים וד' קדושות עי\"ז ממשיכים חיות באמונה, וענין החיות באמונה הוא שיהי' בחי' ראי' ודעת וכמ\"ש וידעת היום שהוא בחי' הכרה והרגשה באלקות ויהי' נתאמת בעיניו כאלו הוא רואה ממש. והנה כ\"ז שייך בבחי' שמך דהיינו בבחי' שם הוי' שהוא בחי' חכ' לפי שהוא ראשית ההשתל' ויכולים להמשיך בבחי' גילוי, משא\"כ מבחי' עצמות אא\"ס א\"א להמשיך בבחי' ברכה וגילוי לפי שלית מחשבה תפיסא בי' כלל שאפי' בחי' ח\"ע ג\"כ אינו משיג מהות של אא\"ס, וע\"כ אינו שייך שם רק בחי' הודאה, כי הודאה אינה בבחי' השגה כלל רק שאע\"פ שאינו משיג בשכלו מודה שכן הוא האמת. וזהו מודים אנחנו לך, שלעצמותו ומהותו אנו מודים לבד בבחי' הודאה לפי שא\"א להמשיך מבחי' אא\"ס בבחי' ברכה וגילוי, ויברכו שם כבודך שבבחי' שמך<sup data-n=\"175\">21</sup> שייך לומר גם בחי' ברכה.\n<b>ועתה</b> י\"ל מ\"ש בכל יום אברכך<sup data-n=\"176\">22</sup>, שמשמע ששייך ברכה גם למהותו ועצמותו. ובכדי להבין זה י\"ל קצת הענין מהו שבריאת העולמות מתחיל בבי\"ת בראשית ברא כו', וך\"ו דורות הי' האל\"ף קורא תגר עד מ\"ת שפתח הקב\"ה באל\"ף אנכי כו', ופי' בזהר פ' ויגש דף ר\"ה ע\"ב הטעם למה לא פתח בריאת העולמות באל\"ף לפי שאל\"ף הוא ר\"ת ארור ובי\"ת הוא ברכה, ולכאורה אינו מובן שהרי",[["172","18","<b>שחכמים הם עיני העדה בבחי' ראי'</b>: ראה אגה\"ק סי\"ד (קכ, ב). לקו\"ת ואתחנן ב, סע\"ד. ועוד."],["173","19","<b>יש אמונה וברכה</b>: להעיר מלקו\"ת עקב יז, רע\"ד: וזהו\"ע אמת ואמונה שהוא ג\"כ ענין ברכה והודאה, כי אמת מקרוב שנראה בעין השכל, ואמונה ברחוק שמאמין שכך הוא האמת. וראה גם אוה\"ת בראשית (כרך ג) תקנח, א. סה\"מ תרל\"ח ע' קכ: האמונה ענין א' הוא עם הודאה."],["174","20","<b>בד\"ה ואהבת את (למ\"ד) בסופו</b>: סה\"מ תר\"ל ע' רמא. וראה גם שם ע' קיא. סה\"מ תרל\"ב ח\"א ע' צ-צא."],["175","21","<b>שלעצמותו ומהותו. . בבחי' הודאה לפי שא\"א להמשיך. . ברכה וגילוי. . שבבחי' שמך</b>: ראה תו\"א בשלח סו, ג: ההפרש בין ברכה להודאה, כי הודאה הגם שמודים שהאמת הוא כמו שהוא קמי' מ\"מ אינו בגלוי ממש. וענין ברכה הוא שתהי' המשכה בגלוי ממש כמו שהוא למעלה כו'. הובא בסה\"מ תרל\"ח שם ע' קכ."],["176","22","<b>ועתה י\"ל מ\"ש בכל יום אברכך</b>: בהבא לקמן (בענין שברה\"ע הי' באות בי\"ת) ראה בארוכה מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרסו ואילך. מאמרי אדהאמ\"צ קונטרסים ע' ריב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' תקעא. תקעט. ח\"ב ע' תשיח ואילך. תשכא. אוה\"ת בשלח (כרך ז) ע' ב' תרנד. ויקרא (כרך ג) ע' תתנז ואילך."]]],[2000510131,"אל\"ף הוא אות ראשון שהוא בחי' פלא[ednref_37_לז] וגם אל\"ף מורה על בחי' אני ראשון ואני אחרון ואיך ע\"י שאל\"ף הוא ר\"ת ארור עי\"ז לא הי' יכול להיות ברה\"ע. אך הענין הוא, דהנה עיקר ענין תומ\"צ הוא רק בחי' צמצום שנתצמצם בבחי' תומ\"צ וכמ\"ש תען לשוני אמרתך כי כל מצותיך צדק, דהיינו כי המצות הוא רק בחי' צדקה כמו מי שעושה צדקה לעני שמצמצם א\"ע, כך ענין תומ\"צ הוא רק צמצום שנתצמצם ברצון של תומ\"צ, כי מצד עצמותו אם חטאת מה תפעל בו ורבו פשעיך מה תעשה לו אם צדקת מה תתן לו או מה מידך יקח (באיוב סי' ל\"ה ו\"ז), וזהו שארז\"ל אנכי ולא יהי' לך מפי הגבורה שמענו דהיינו שזה גופא שיהי' בחי' אנכי שהוא מקור לרמ\"ח מ\"ע ולא יהי' לך שהוא מקור לשס\"ה ל\"ת<sup data-n=\"177\">23</sup> מפי הגבורה שהוא בחי' צמצום שנתצמצם בזה כו' וזהו רצון אותיות צנור. וזהו מ\"ש הלא אח עשו ליעקב ואוהב את יעקב כו', והיינו שמצד עצמותו שוין לפניו ממש כי כחשיכה כאורה שוין לפניו, רק שיהי' ואוהב את יעקב זהו ע\"י צמצום כו'. וזהו שלא נברא העולם באל\"ף כי אם הי' נבה\"ע באל\"ף שהוא בחי' אני ראשון ואני אחרון אשר שם כחשיכה כאורה שוים לפניו ויכולים הכל לקבל, הי' יניקת החיצונים יותר מדאי, וזהו ע\"ד מ\"ש זכרנו את הדגה אשר נאכל במצרים חנם, שגם כשנברא העולם בבי\"ת הי' מתחלה השפעת חיצוניות חנם בלא מצות<sup data-n=\"178\">24</sup>, כי דגה הוא השפעה למטה, והי' מתחלה ההשפעה בלא מצות לפי ששם כחשיכה כאורה שוין כו' וממילא לא הי' גילוי אלקות למטה, ועיקר המכוון הי' כדי שיהי' גילוי אלקות למטה כי נתאוה הקב\"ה להיות לו דירה בתחתונים כו'. וזהו מ\"ש בזהר שאל\"ף הוא ארור דהיינו שמאל\"ף יכול לקבל גם י\"א ארורים שבקליפה ארור כנען, רק באליעזר כתי' בא ברוך ה' שלבן הוציאו מכלל ארור לכלל ברוך<sup data-n=\"179\">25</sup>, וע\"כ נבה\"ע בבי\"ת כי בי\"ת הוא בחי' חכ' בחכ' יבנה בית<sup data-n=\"180\">26</sup> בראשית ברא ות\"י בחוכמתא ברא, והיינו שכיון שנתצמצם האור בבחי' חכ' הנה בחכמה יש שם דקדוק<sup data-n=\"181\">27</sup> שזה כשר וזה פסול כו', והיינו שעפ\"י חכמה אינו נמשך האור כ\"א דוקא במי שהוא בטל אליו כו' וע\"כ לא יוכל להיות יניקת החיצונים כיון שהם בבחי' פירוד ויש ודבר כו', וזהו בראשית בשביל התורה",[["177","23","<b>אנכי. . מקור לרמ\"ח מ\"ע ולא יהי'. . לשס\"ה ל\"ת</b>: ראה תניא פ\"כ (כה, ב)."],["178","24","<b>ע\"ד מ\"ש זכרנו את הדגה אשר נאכל במצרים חנם. . בלא מצות</b>: ראה בכ\"ז בארוכה אוה\"ת בהעלותך ע' שפז."],["179","25","<b>ובאליעזר כתי' בא ברוך ה' שלבן הוציאו מכלל ארור לכלל ברוך</b>: ראה ויק\"ר פי\"ז, ה: אמר ר' יוסי בן דוסא אליעזר הוא כנען, וע\"י ששימש אותו צדיק יצא מכלל ארור ובא לכלל ברוך, הה\"ד ויאמר ארור כנען, וכתיב ויאמר בא ברוך ה'. וראה עד\"ז בב\"ר פ\"ס, ז. זח\"ג קג, סע\"א. קנה, א [ומסיים שם: דאתא מלאך ואעיל מלה דא בפומי' דלבן]."],["180","26","<b>וע\"כ נבה\"ע בבי\"ת בחכ' יבנה בית</b>: ראה בכ\"ז בארוכה ביאוה\"ז להצ\"צ שם ח\"ב ע' תשיד."],["181","27","<b>בחכ' יש שם דקדוק</b>: ראה תו\"א בראשית ה, ד. אוה\"ת שמות (כרך ז) ע' ב'תקכד ואילך. ביאוה\"ז להצ\"צ ח\"ב שם ע' תשיח ואילך.\n\n[edn_37_לז] <b>ולכאורה אינו מובן שהרי אל\"ף. . שהוא בחי' פלא</b>: בשולי הגליון נרשם בגוכי\"ק: לית מח' תפיסא, מח' חכ' כמ\"ש בזח\"א חיי קך\"ב ע\"א דלא אתפריש מח' ויובלא לעלמין, שהם חו\"ב, וגם צ\"ל דא\"כ איך התחיל עשה\"ד באלף."]]],[2000510132,"שנק' ראשית ובשביל ישראל שנק' ראשית, לפי שמבחי' חכמה לא יוכלו לקבל כו' כ\"א רק נש\"י. והנה מ\"ת מתחיל באל\"ף והיינו שהגם שמאל\"ף יכול להיות יניקת החיצוני' היינו מאל\"ף עצמו, אך אח\"כ כשנבה\"ע בבי\"ת ונמשך האור ע\"י חכ' לא יוכל לקבל גם מבחי' אל\"ף, וזהו אנכי הוי' שנמשך אנכי בבחי' שם הוי'. וזהו ענין ך\"ו דורות שקרא האל\"ף תגר כי ך\"ו הוא כנגד שם הוי', ועד שנמשך האור בבחי' הוי' לא הי' יכול להתחיל באל\"ף כדי שלא יהי' יניקת החיצונים, אך אח\"כ כשנמשך בבחי' שם הוי' שהוא בחי' חכמה אזי לא יוכלו לקבל וכמ\"ש אם תגביהי כנשר משם אורידך נאום הוי', ע' בד\"ה והי' הנשאר בציון (ל\"א)<sup data-n=\"182\">28</sup> ס\"ג.\n<b>והנה</b> בזה יובן מה שלמדו רז\"ל מפסוק ועתה ישראל מה הוי' אלקיך שואל מעמך א\"ת מה אלא מאה, והיינו כי החילוק שבין מה למאה הוא שמאה הוא באל\"ף, והיינו שע\"י מ\"ה שהוא בחי' ביטול דחכמה עי\"ז ממשיכים מבחי' אל\"ף בבחי' חכ' ואעפ\"כ לא יהי' יניקת החיצוני' כיון שנמשך בבחי' חכ'. וזהו ג\"כ מ\"ש בכל יום אברכך שמשמע מהותו ועצמותו, והיינו כי סתם ברכה הוא בחי' חכמה, כי ברוך הוא יסוד אבא איהו ברוך ואיהי ברכה<sup data-n=\"183\">29</sup>, איהי ברכה הוא בחי' מל' שמקבלת הברכה מבחי' יסוד אבא, או אפ\"ל איהי ברכה הוא בחי' יסוד אימא. אך עי\"ז שמברכים מאה ברכות בכל יום עי\"ז ממשיכים מבחי' מאה שהוא בחי' כתר ששם הוא בחי' מאה שהוא בחי' התכללות מיו\"ד ויו\"ד מיו\"ד כו'. וזהו בכל יום אברכך שע\"י מאה ברכות ממשיכים מהו\"ע שמאיר בבחי' כתר בחי' אל\"ף כו' בבחי' מ\"ה שהיא בחי' חכמה.\n<b>וזהו</b> ענין ויהיו חיי שרה<sup data-n=\"184\">30</sup> מאה שנה ועשרים שנה, והיינו כי שרה הוא לשון שררה שר ה' בחי' שרית עם אלקים שהוא בחי' מל', והנה חיי שרה היינו שהמל' מקבל מבחי' מאה שנה שהוא בחי' כתר. ועשרים שנה היינו שההמשכה שנמשך מבחי' מאה שנה צריך להתלבש בבחי' עשרים שנה שהוא בחי' חו\"ב כי חו\"ב נק' עשרים שנה שהם תרין ריעין דלא מתפרשין. וזהו ענין יו\"ד שהמלוי שלו הוא בחי' ו\"ד שעולה ג\"כ עשרה, והיינו כי המילוי הוא בחי' גילוי<sup data-n=\"185\">31</sup>, שהרי כשכותבין יו\"ד או כשמחשב במחשבתו אות יו\"ד יכול לצייר הנקודה של היו\"ד בעצמו לבד ואינו צריך להמילוי, רק כשמדבר יו\"ד בהכרח להוציא ג\"כ ו\"ד, והיינו שהגילוי של חכ' הוא בחי' בינה שהם בחי' אין ויש. וזהו ביו\"ד נברא עוה\"ב כי עוה\"ב הוא בחי'",[["182","28","<b>בד\"ה והי' הנשאר בציון (ל\"א)</b>: לעיל ע' יד ואילך."],["183","29","<b>איהו ברוך ואיהי ברכה</b>: ראה בכ\"ז בארוכה סידור עם דא\"ח קסה, סע\"ב ואילך. שה, ד. אוה\"ת נ\"ך (כרך ב) ע' תתקנט ואילך."],["184","30","<b>וזהו ענין ויהיו חיי שרה</b>: בהבא לקמן בפיסקא זו ראה מאמרי אדה\"ז תקס\"ו ע' נ ואילך. על פרשיות התורה ח\"א ע' קלג ואילך. תו\"ח חיי שרה קכו, ב ואילך. אוה\"ת חיי שרה קי, ב ואילך. ביאוה\"ז להצ\"צ ח\"א ע' עח ואילך. מאמרי אדהצ\"צ הנחות תרט\"ו ע' לה-ו. סה\"מ תר\"ל ס\"ע כג-ד. פר\"ת ע' קמז-ח."],["185","31","<b>יו\"ד שהמילוי שלו. . ו\"ד. . המילוי הוא בחי' גילוי</b>: ראה ביאוה\"ז לאדהאמ\"צ נג, א-ב. ולהצ\"צ ח\"א ע' רפד ואילך. דרמ\"צ סו, ב. וראה גם מאמרי אדה\"ז הנחות הר\"פ ע' לג."]]],[2000510133,"גילוי צדיקים יושבין ונהנין בהשגה כו' שהוא בחי' בינה, ונבראת ביו\"ד חכ'. וחיי שרה הוא בחי' מאה ועשרים שנה, שמקבלת מבחי' מאה שהוא בחי' כתר, רק שנמשך בבחי' עשרים שהוא בחי' חו\"ב כדי שלא יהי' יניקת החיצוני' כו'. וזהו ג\"כ שמשה הי' חי מאה ועשרים שנה והיינו לפי שמשה קיבל את התורה, והגם שאורייתא מח\"ע נפקת, נפקת דוקא, אבל שורש התורה היא מבחי' כתר וכמ\"ש ואהי' שעשועי' כו' בחי' שעשועי המלך כו' ולכן כתי' לא ידע אנוש ערכה כו' אלקים הבין דרכה, וזהו שנענש דוד על שקרא ד\"ת בשם זמירות כמ\"ש במ\"א<sup data-n=\"186\">32</sup>, רק שנתלבשה בבחי' ח\"ע כו'. ושבע שנים היינו שכדי שיומשך למטה בעלמא דאתגליי' צריך שיומשך גם בבחי' מדות כו', כי אם לא הי' נמשך במדות הי' רק בגילוי למעלה בעלמין סתימין, וכדי שיומשך למטה בעלמא דאתגליא צריך שיקבל גם מבחי' ז' מדות כנ\"ל.\n<b>והנה</b> בזה יובן מ\"ש ברבות<sup data-n=\"187\">33</sup> א\"ר עקיבא מה זכתה אסתר למלוך על שבע ועשרים ומאה מדינה, אלא תבוא אסתר בת בתה של שרה שחייתה מאה ועשרים ושבע שנים, ותמלוך על מאה ועשרים ושבע מדינה כו'. ולכאורה אין לזה הבנה כלל. אך הענין הוא דהנה מתחלה כתי' המולך מהודו ועד כוש<sup data-n=\"188\">34</sup>, פי' הודו זהו ע\"ד מ\"ש הוד והדר לבשת שארז\"ל שבשעת ברה\"ע נתלבש בלבוש הוד והדר, לפי שבעת בריאת העולמות הי' גילוי אלקות, כי הגם שברה\"ע הי' בבי\"ת מ\"מ נתלבש גם בלבוש הוד והדר, ולכן אור שנברא ביום ראשון הי' אדם מביט בו מסוף העולם ועד סופו כו', רק אח\"כ אחר חטא עה\"ד נחסר האור כו'. ופי' כוש הוא ל' שחרות בחי' אלביש שמים קדרות ושק אשים כסותם, שנעשה חשך והעלם והסתר כו'. ואעפ\"כ כתיב המולך מהודו ועד כוש דהיינו שאעפ\"כ יכולים להמשיך גם עתה בחי' הוד והדר. אך כדי שיומשך מבחי' הוד והדר צריך שיהי' מאה ועשרים ושבע כו', דהיינו שמתחלה יתלבש בחי' מאה שהוא בחי' כתר שהוא בחי' לבוש של הוד והדר לבושי' כתלג חיור בבחי' עשרים שהוא בחי' חו\"ב, כדי שלא יהי' יניקת החיצוני', וגם כדי שיומשך למטה זהו ע\"י התלבשות בשבע שנים שהוא בחי' ז' מדות שנעשים מקור לעולמות כו'. וזהו ענין השייכות של שבע ועשרים ומאה מדינה לשני חיי שרה שהי' מאה ועשרים ושבע שנים כו' וד\"ל.",[["186","32","<b>שנענש דוד על שקרא ד\"ת בשם זמירות כמ\"ש במ\"א</b>: ראה קו\"א לתניא ד\"ה דוד זמירות (קס, סע\"א ואילך) ובליקוט פי' ומ\"מ שם. תו\"א מקץ לב, א. לקו\"ת במדבר יח, א ואילך. סה\"מ תרכ\"ז ע' רנד-ה. וש\"נ. וע' תסג-ד. וש\"נ. תרכ\"ט ע' תה. וש\"נ. ועוד."],["187","33","<b>והנה בזה יובן מ\"ש ברבות</b>: בהבא לקמן עד סוף המאמר ראה אוה\"ת חיי שרה קיד, א-ב. לקמן ד\"ה אר\"ע מה זכתה אסתר. — וראה (באו\"א) בשיחת פורים תש\"ל (שיחו\"ק תש\"ל (הוצאת תשמ\"ו ח\"א ע' 638). וראה גם שיחת פורים תשכ\"א (שיחו\"ק תשכ\"א ע' 129)."],["188","34","<b>אך הענין הוא. . המולך מהודו ועד כוש</b>: בהבא לקמן ראה בארוכה לקו\"ת שה\"ש ו, ב. אוה\"ת מגילת אסתר (הוצאת תש\"נ) ע' ג-ד."]]]]});
